        self, athlete_id: str, session_id: str, training_day: str
    ) -> dict[str, Any] | None:
        return self._select_first(
            self.client.table("session_completions")
            .select("*")
            .eq("athlete_id", athlete_id)
            .eq("session_id", session_id)
