                raise HTTPException(
                    status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
                    detail="failed to persist feedback",
                )
            return rows[0]
        except HTTPException:
            raise
        except _STORE_CLIENT_ERRORS as exc:
            self._raise_feedback_store_error(exc, detail="failed to persist feedback")

    def list_admin_feedback(self, *, limit: int = 50) -> list[dict[str, Any]]:
        try:
            response = (
                self.client.table("beta_feedback")
                .select(
                    "id,submitted_by_profile_id,surface,category,response,reason,comment,"
                    "structured_response,contact_allowed,priority,plan_id,today_checkin_id,"
                    "session_id,camp_phase,app_version,"
                    "readiness_snapshot,injury_snapshot,technical_context,"
                    "screenshot_path,screenshot_expires_at,created_at,updated_at,"
                    "profiles!beta_feedback_submitted_by_profile_id_fkey(email,full_name)"
                )
                .order("created_at", desc=True)
                .limit(100)
                .execute()
            )
            rows = getattr(response, "data", None) or []
            rows.sort(
                key=lambda row: (
                    str(row.get("priority") or "normal") == "safety",
                    str(row.get("created_at") or ""),
                ),
                reverse=True,
            )
            return rows[: max(1, min(limit, 100))]
        except _STORE_CLIENT_ERRORS as exc:
            self._raise_feedback_store_error(exc, detail="failed to read admin feedback")

    def get_feedback_screenshot_path(self, feedback_id: str) -> str | None:
        try:
            row = self._select_first(
                self.client.table("beta_feedback")
                .select("screenshot_path")
                .eq("id", feedback_id)
                .gt("screenshot_expires_at", datetime.now(timezone.utc).isoformat())
            )
            return str(row.get("screenshot_path") or "").strip() or None if row else None
        except _STORE_CLIENT_ERRORS as exc:
            self._raise_feedback_store_error(exc, detail="failed to read feedback screenshot")

    def create_feedback_screenshot_signed_url(self, path: str, *, expires_in: int) -> str:
        try:
            response = self.client.storage.from_("feedback-screenshots").create_signed_url(
                path,
                expires_in,
            )
            url = str(response.get("signedURL") or response.get("signedUrl") or "").strip()
            if not url:
                raise HTTPException(
                    status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
                    detail="feedback screenshot unavailable",
                )
            return url
        except HTTPException:
            raise
        except _STORAGE_CLIENT_ERRORS as exc:
            self._raise_feedback_store_error(exc, detail="failed to open feedback screenshot")

    def claim_feedback_rate_limit(
        self,
        profile_id: str,
        *,
        report_limit: int,
        screenshot_limit: int,
        has_screenshot: bool,
    ) -> tuple[bool, str | None, int]:
        try:
            response = self.client.rpc(
                "claim_beta_feedback_rate_limit",
                {
                    "p_submitted_by_profile_id": profile_id,
                    "p_report_limit": report_limit,
                    "p_screenshot_limit": screenshot_limit,
                    "p_window_seconds": 3600,
                    "p_has_screenshot": has_screenshot,
                },
            ).execute()
            rows = getattr(response, "data", None) or []
            if not rows:
                raise HTTPException(
                    status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
                    detail="feedback rate limit unavailable",
                )
            row = rows[0]
            return bool(row.get("allowed")), row.get("blocked_scope"), int(row.get("retry_after_seconds") or 0)
        except HTTPException:
            raise
        except _STORE_CLIENT_ERRORS as exc:
            self._raise_feedback_store_error(exc, detail="feedback rate limit unavailable")

    def upload_feedback_screenshot(self, path: str, data: bytes, mime: str) -> None:
        try:
            self.client.storage.from_("feedback-screenshots").upload(
                path,
                data,
                {"content-type": mime, "upsert": "false"},
            )
        except _STORAGE_CLIENT_ERRORS as exc:
            self._raise_feedback_store_error(exc, detail="failed to upload screenshot")

    def delete_feedback_screenshots(self, paths: list[str]) -> None:
        if not paths:
            return
        try:
            self.client.storage.from_("feedback-screenshots").remove(paths)
        except _STORAGE_CLIENT_ERRORS as exc:
            self._raise_feedback_store_error(exc, detail="failed to delete screenshot")

    def list_expired_feedback_screenshots(self, *, limit: int = 100) -> list[dict[str, Any]]:
        response = (
            self.client.table("beta_feedback")
            .select("id,screenshot_path,screenshot_expires_at")
            .not_.is_("screenshot_path", "null")
            .is_("screenshot_deleted_at", "null")
            .lte("screenshot_expires_at", datetime.now(timezone.utc).isoformat())
            .order("screenshot_expires_at")
            .limit(max(1, min(limit, 500)))
            .execute()
        )
        return getattr(response, "data", None) or []

    def list_profile_feedback_screenshots(self, profile_id: str, *, limit: int = 100) -> list[dict[str, Any]]:
        response = (
            self.client.table("beta_feedback")
            .select("id,screenshot_path,screenshot_expires_at")
            .eq("submitted_by_profile_id", profile_id)
            .not_.is_("screenshot_path", "null")
            .order("created_at")
            .limit(max(1, min(limit, 500)))
            .execute()
        )
        return getattr(response, "data", None) or []

    def clear_feedback_screenshot(self, feedback_id: str, expected_path: str) -> bool:
        response = (
            self.client.table("beta_feedback")
            .update(
                {
                    "screenshot_path": None,
                    "screenshot_mime": None,
                    "screenshot_size_bytes": None,
                    "screenshot_width": None,
                    "screenshot_height": None,
                    "screenshot_expires_at": None,
                    "screenshot_deleted_at": datetime.now(timezone.utc).isoformat(),
                }
            )
            .eq("id", feedback_id)
            .eq("screenshot_path", expected_path)
            .execute()
        )
        return bool(getattr(response, "data", None) or [])

api/structured_plan_locked_merge.py:
"""Deterministically render governed banked roles in structured cards.

Stage 1 owns a banked prescription once its role governance marks the selected
drill as locked. Structured conversion may enrich the surrounding card, but it
must not omit, rename, or paraphrase those bank-owned fields. The role's
countdown day is authoritative: converter slips in the day itself (the day split
across two rows, a blank label on a dated row, or the day dropped outright) are
repaired onto that day, and within it this module repairs, moves, or creates the
governed session and block without another model call. Only a drill the
converter placed on a different day stays unresolved, since moving it would be
guessing.

Two banked systems share this pathway (see ``_LOCKED_CONTENT_SPECS``): the
Tactical Watch and the Fight Visualisation countdown protocol. They differ only
in which role field carries the bank object, the fixed session title, and how the
bank record's own fields map onto the card's block -- so the repair, move and
create logic below is written once and driven by that spec.
"""
from __future__ import annotations

import copy
import re
from dataclasses import dataclass, field
from datetime import date
from typing import Any, Iterable, Mapping

from fightcamp.fight_date_utils import parse_fight_date

from .structured_plan_calendar_spine import _resolve_fight_date, _rest_day, _valid_phase
from .structured_plan_sparring_reconcile import reconcile_coach_led_sparring_days


@dataclass(frozen=True)
class LockedContentSpec:
    """How one banked system projects onto a structured card."""

    content_field: str
    session_title: str
    session_slug: str
    session_type: str
    block_type: str


# Order is precedence: a role carrying more than one bank object (never expected)
# resolves to the first match, deterministically.
_LOCKED_CONTENT_SPECS = (
    LockedContentSpec(
        content_field="tactical_watch",
        session_title="Tactical Focus",
        session_slug="tactical-watch",
        session_type="skill",
        block_type="mindset",
    ),
    LockedContentSpec(
        content_field="fight_visualization",
        session_title="Fight Visualisation",
        session_slug="fight-visualization",
        session_type="skill",
        block_type="mindset",
    ),
)


def _spec_for_role(role: Mapping[str, Any]) -> tuple[LockedContentSpec, Mapping[str, Any]] | None:
    for spec in _LOCKED_CONTENT_SPECS:
        content = role.get(spec.content_field)
        if isinstance(content, Mapping):
            return spec, content
    return None


@dataclass(frozen=True)
class LockedMergeApplication:
    countdown_label: str
    block_name: str


@dataclass(frozen=True)
class LockedMergeIssue:
    countdown_label: str | None
    block_name: str
    reason: str


@dataclass
class LockedMergeResult:
    plan: dict[str, Any]
    applied: list[LockedMergeApplication] = field(default_factory=list)
    unresolved: list[LockedMergeIssue] = field(default_factory=list)


def _locked_roles(value: Any) -> Iterable[Mapping[str, Any]]:
    if isinstance(value, Mapping):
        governance = value.get("governance")
        if isinstance(governance, Mapping) and governance.get("selected_drill_locked") is True:
            yield value
        for child in value.values():
            yield from _locked_roles(child)
    elif isinstance(value, (list, tuple)):
        for child in value:
            yield from _locked_roles(child)


def _normalise(value: Any) -> str:
    return " ".join(
        str(value or "")
        .replace("\u2018", "'")
        .replace("\u2019", "'")
        .replace("\u2013", "-")
        .replace("\u2014", "-")
        .lower()
        .split()
    )


def _is_named_variant(value: Any, name: str, *, session_title: str | None = None) -> bool:
    """Recognise converter labels that explicitly name the locked bank drill."""
    label = _normalise(value)
    drill = _normalise(name)
    if label in {
        drill,
        f"{drill} mental rehearsal",
        f"{drill} visualisation",
        f"{drill} visualization",
    }:
        return True
    return bool(
        session_title
        and label in {
            f"{_normalise(session_title)}: {drill}",
            f"{_normalise(session_title)} - {drill}",
        }
    )


def _countdown(value: Any) -> str | None:
    match = re.search(r"D-\s*(\d+)", str(value or ""), re.IGNORECASE)
    return f"D-{int(match.group(1))}" if match else None


def _role_day(role: Mapping[str, Any]) -> str | None:
    # This is the same precedence used by the existing locked faithfulness path.
    for key in ("scheduled_countdown_label", "countdown_label", "countdown_display_label"):
        label = _countdown(role.get(key))
        if label:
            return label
    return None


def _days(plan: Mapping[str, Any]) -> Iterable[dict[str, Any]]:
    for week in plan.get("weeks") or []:
        if not isinstance(week, Mapping):
            continue
        for day in week.get("days") or []:
            if isinstance(day, dict):
                yield day


def _day_dday(day: Mapping[str, Any], fight_date: date | None) -> int | None:
    """A day's countdown distance from its label, else from its ISO date."""
    label = _countdown(day.get("countdown_label"))
    if label is not None:
        return int(label[2:])
    if fight_date is None:
        return None
    parsed = parse_fight_date(str(day.get("date") or "").strip())
    if parsed is None:
        return None
    delta = (fight_date - parsed).days
    return delta if delta >= 0 else None


def _drill_on_card(plan: Mapping[str, Any], names: set[str]) -> bool:
    return any(
        _is_named_variant(value, name)
        for day in _days(plan)
        for session in day.get("sessions") or []
        if isinstance(session, Mapping)
        for value in [session.get("title")]
        + [
            block.get("display_name")
            for block in session.get("blocks") or []
            if isinstance(block, Mapping)
        ]
        for name in names
    )


def _insert_day(plan: dict[str, Any], day: dict[str, Any], d_day: int, fight_date: date) -> None:
    """Place a new day in the week whose countdown span covers it, else the nearest."""
    best: tuple[int, list[Any]] | None = None
    for week in plan.get("weeks") or []:
        if not isinstance(week, dict) or not isinstance(week.get("days"), list):
            continue
        ddays = [
            value
            for value in (
                _day_dday(item, fight_date) for item in week["days"] if isinstance(item, Mapping)
            )
            if value is not None
        ]
        if not ddays:
            continue
        distance = 0 if min(ddays) <= d_day <= max(ddays) else min(abs(v - d_day) for v in ddays)
        if best is None or distance < best[0]:
            best = (distance, week["days"])
    days = best[1] if best else None
    if days is None:
        weeks = plan.get("weeks")
        if not isinstance(weeks, list) or not weeks or not isinstance(weeks[0], dict):
            return
        days = weeks[0].setdefault("days", [])
    index = next(
        (
            position
            for position, item in enumerate(days)
            if isinstance(item, Mapping)
            and (_day_dday(item, fight_date) is not None)
            and _day_dday(item, fight_date) < d_day
        ),
        len(days),
    )
    days.insert(index, day)


def _resolve_authoritative_day(
    plan: dict[str, Any],
    *,
    day_label: str,
    names: set[str],
    role: Mapping[str, Any],
    planning_brief: Mapping[str, Any],
) -> tuple[dict[str, Any] | None, str | None]:
    """Find the one card day for the role's countdown, repairing converter slips.

    The role's day is authoritative, so the card's day structure is repaired to
    it rather than rejecting the whole card:

    * a day split across two rows is coalesced into the first (no session lost),
    * a dated row with a blank/garbled label is matched by date and relabelled,
    * a dropped day is recreated as an empty day for the watch to land on.

    A dropped day is only recreated when the drill is nowhere else on the card.
    If the converter put it on another day, moving it would be guessing, so that
    stays unresolved and faithfulness rejects the card.
    """
    fight_date = parse_fight_date(_resolve_fight_date(dict(planning_brief)))
    d_day = int(day_label[2:])
    matches: list[tuple[dict[str, Any], dict[str, Any]]] = []
    for week in plan.get("weeks") or []:
        if not isinstance(week, dict):
            continue
        for day in week.get("days") or []:
            if isinstance(day, dict) and _day_dday(day, fight_date) == d_day:
                matches.append((week, day))

    if matches:
        _, keep = matches[0]
        for week, duplicate in matches[1:]:
            keep.setdefault("sessions", []).extend(
                session for session in duplicate.get("sessions") or [] if isinstance(session, dict)
            )
            week["days"] = [item for item in week.get("days") or [] if item is not duplicate]
        if _countdown(keep.get("countdown_label")) is None:
            keep["countdown_label"] = day_label
        return keep, None

    if _drill_on_card(plan, names):
        return None, "locked drill is on a different structured day"
    if fight_date is None:
        return None, "structured day missing and fight date unknown"
    dated = [
        (distance, day)
        for day in _days(plan)
        if (distance := _day_dday(day, fight_date)) is not None
        and _valid_phase(day.get("phase_label"))
    ]
    neighbour_phase = (
        _valid_phase(min(dated, key=lambda pair: abs(pair[0] - d_day))[1].get("phase_label"))
        if dated
        else ""
    )
    day = _rest_day(d_day, fight_date, _valid_phase(role.get("camp_phase"), neighbour_phase))
    # It will carry the zero-load watch, so it is not a rest day.
    day["day_type"] = "low"
    _insert_day(plan, day, d_day, fight_date)
    return day, None


def _stable_id(value: str) -> str:
    return re.sub(r"[^a-z0-9]+", "-", value.lower()).strip("-") or "watch"


def _duration(content: Mapping[str, Any]) -> dict[str, Any]:
    """Normalise the bank's duration onto the card's single-value shape.

    The Tactical Watch bank stores one integer; the Fight Visualisation bank
    stores a ``[min, max]`` bound. The selected duration takes precedence on
    the card; older roles without that field retain the upper-bound fallback.
    """
    raw = content.get("prescribed_duration_min") or content.get("duration_min")
    if isinstance(raw, (list, tuple)) and raw:
        value = raw[-1]
    else:
        value = raw
    return {"value": value if isinstance(value, int) else 1, "unit": "minutes"}


def _mindset_anchor(content: Mapping[str, Any]) -> dict[str, Any]:
    """The card's coaching lines, one distinct claim per slot.

    A Tactical Watch carries a real four-part mindset block. The Fight
    Visualisation bank carries a single trusted ``cue`` instead, and filling
    every slot with it printed that one sentence three times on the card
    ("Focus", "Reset" and "Coach cue" all reading "Take the space, do not chase
    it."). A single cue is a single cue: it fills the coach-cue slot and the
    others stay empty rather than repeating it or inventing generic filler.
    """
    mindset = content.get("mindset")
    mindset = mindset if isinstance(mindset, Mapping) else {}
    cue = str(content.get("cue") or "").strip()
    intent = str(mindset.get("intent") or "").strip()
    focus = str(mindset.get("focus") or "").strip()
    reset = str(mindset.get("reset") or "").strip()
    anchor = str(mindset.get("anchor") or "").strip()
    if not (intent or focus or reset or anchor):
        return {
            "intent": cue,
            "focus_cue": "",
            "reset_cue": "",
            "confidence_anchor": None,
        }
    return {
        "intent": intent or cue,
        "focus_cue": focus,
        "reset_cue": reset,
        "confidence_anchor": anchor or None,
    }


def _restore_open_plan_tactical_watches(
    plan: dict[str, Any], planning_brief: Mapping[str, Any]
) -> None:
    """Restore open-plan Tactical Watch fields from the deterministic rotation."""
    spec = planning_brief.get("open_plan_spec")
    spec = spec if isinstance(spec, Mapping) else {}
    tactical = spec.get("tactical_watch")
    tactical = tactical if isinstance(tactical, Mapping) else {}
    rotation = tactical.get("weekly_rotation")
    if not isinstance(rotation, (list, tuple)):
        return

    for entry in rotation:
        if not isinstance(entry, Mapping):
            continue
        watch = entry.get("tactical_watch")
        if not isinstance(watch, Mapping):
            continue
        name = str(entry.get("name") or watch.get("name") or "").strip()
        if not name:
            continue

        targets = [
            (session, block)
            for day in _days(plan)
            for session in day.get("sessions") or []
            if isinstance(session, dict)
            for block in session.get("blocks") or []
            if isinstance(block, dict)
            and _normalise(block.get("display_name")) == _normalise(name)
        ]
        if len(targets) != 1:
            continue

        session, block = targets[0]
        session["session_type"] = "skill"
        session["objective"] = watch.get("why")
        session["mindset_anchor"] = _mindset_anchor(watch)
        block.update(
            {
                "block_type": "mindset",
                "display_name": watch.get("name") or name,
                "duration": _duration(watch),
                "coaching_cues": [
                    str(value) for value in watch.get("instructions") or []
                ],
                "purpose": watch.get("why"),
            }
        )
        if watch.get("progress"):
            block["progression_rule"] = watch["progress"]


def _new_watch_block(
    *, day_label: str, name: str, watch: Mapping[str, Any], spec: LockedContentSpec
) -> dict[str, Any]:
    return {
        "block_id": f"locked-{_stable_id(day_label)}-{_stable_id(name)}",
        "block_type": spec.block_type,
        "display_name": name,
        "duration": _duration(watch),
        "coaching_cues": [],
        "regression_options": [],
        "substitutions": [],
    }


def _new_watch_session(
    *,
    day_label: str,
    title: str,
    name: str,
    watch: Mapping[str, Any],
    spec: LockedContentSpec,
) -> dict[str, Any]:
    return {
        "session_id": f"locked-{_stable_id(day_label)}-{spec.session_slug}",
        "session_type": spec.session_type,
        "title": title,
        "objective": str(watch.get("why") or "Review the tactical plan."),
        "completion_status": "not_started",
        "mindset_anchor": _mindset_anchor(watch),
        "blocks": [],
    }


def _is_safe_named_watch_shell(
    session: Mapping[str, Any], authoritative_names: set[str]
) -> bool:
    """Return whether a drill-titled session can safely become the Watch.

    The structured converter occasionally emits the locked drill name as its
    own otherwise-empty session. It is the same governed content, not a second
    athlete session. Only reuse or remove that shell when it has not been
    started and carries no independent blocks.
    """
    if not _is_unstarted(session):
        return False

    blocks = session.get("blocks") or []
    return isinstance(blocks, list) and all(
        isinstance(block, Mapping)
        and any(
            _is_named_variant(block.get("display_name"), name)
            for name in authoritative_names
        )
        for block in blocks
    )


def _is_unstarted(session: Mapping[str, Any]) -> bool:
    return _normalise(session.get("completion_status")) in {"", "not_started", "not started"}


def _is_generic_visualization_shell(session: Mapping[str, Any], name: str) -> bool:
    """Only remove an unstarted converter session explicitly titled as a visualisation."""
    if not _is_unstarted(session):
        return False
    title = _normalise(session.get("title"))
    if not title.startswith("fight visualisation -"):
        return False
    blocks = session.get("blocks") or []
    return isinstance(blocks, list) and all(
        isinstance(block, Mapping)
        and _normalise(block.get("block_type")) in {"", "mindset"}
        and (
            _normalise(block.get("display_name")) == "fight visualisation"
            or _is_named_variant(block.get("display_name"), name)
        )
        for block in blocks
    )


def merge_locked_structured_content(
    structured_plan: dict[str, Any], planning_brief: Any
) -> LockedMergeResult:
    """Apply locked fields on their authoritative day.

    The role's countdown day is authoritative: a split, unlabelled or dropped
    day is repaired onto it (see ``_resolve_authoritative_day``), while a drill
    the converter placed on another day stays unresolved. Inside that day,
    Stage 1 is authoritative, so harmless converter drift (renamed/moved/missing
    Tactical Watch structure) is repaired deterministically instead of rejecting
    the entire athlete card.
    """
    plan = copy.deepcopy(structured_plan)
    result = LockedMergeResult(plan=plan)
    # ``optional`` is server-owned: only a locked optional role below may set
    # it, so a model-supplied value can never make real training skippable.
    for day in _days(plan):
        for session in day.get("sessions") or []:
            if isinstance(session, dict):
                session.pop("optional", None)
    if not isinstance(planning_brief, Mapping):
        return result

    _restore_open_plan_tactical_watches(plan, planning_brief)

    for role in _locked_roles(planning_brief):
        governance = role.get("governance")
        governance = governance if isinstance(governance, Mapping) else {}
        resolved = _spec_for_role(role)
        spec, watch = resolved if resolved is not None else (None, None)
        name = str(
            governance.get("selected_drill_name")
            or (watch or {}).get("name")
            or "locked drill"
        )
        day_label = _role_day(role)
        if watch is None or spec is None:
            result.unresolved.append(
                LockedMergeIssue(day_label, name, "missing locked bank metadata")
            )
            continue
        if day_label is None:
            result.unresolved.append(LockedMergeIssue(None, name, "missing authoritative countdown label"))
            continue

        authoritative_names = {
            _normalise(governance.get("selected_drill_name")),
            _normalise(watch.get("name")),
        } - {""}
        target_day, day_issue = _resolve_authoritative_day(
            plan,
            day_label=day_label,
            names=authoritative_names,
            role=role,
            planning_brief=planning_brief,
        )
        if target_day is None:
            result.unresolved.append(LockedMergeIssue(day_label, name, day_issue or "structured day not resolved"))
            continue
        matching_days = [target_day]
        sessions = [
            session
            for session in matching_days[0].get("sessions") or []
            if isinstance(session, dict)
        ]
        # This is fixed product copy. The selected drill is the card's block,
        # never an alternate session title supplied by structured conversion.
        display_title = spec.session_title
        session_title = _normalise(display_title)
        watch_sessions = [
            session
            for session in sessions
            if _normalise(session.get("title")) == session_title
        ]
        if len(watch_sessions) > 1:
            result.unresolved.append(
                LockedMergeIssue(
                    day_label,
                    name,
                    f"{spec.session_title} session not uniquely resolved",
                )
            )
            continue

        named_watch_sessions = [
            session
            for session in sessions
            if any(
                _is_named_variant(session.get("title"), candidate, session_title=display_title)
                for candidate in authoritative_names
            )
            and _normalise(session.get("title")) != session_title
        ]
        if len(named_watch_sessions) > 1:
            result.unresolved.append(
                LockedMergeIssue(
                    day_label,
                    name,
                    f"named {spec.session_title} session not uniquely resolved",
                )
            )
            continue
        named_watch_session = named_watch_sessions[0] if named_watch_sessions else None
        reusable_named_watch = (
            named_watch_session
            if named_watch_session
            and _is_safe_named_watch_shell(named_watch_session, authoritative_names)
            else None
        )

        targets = [
            (session, block)
            for session in sessions
            if _is_unstarted(session) or any(session is watch_session for watch_session in watch_sessions)
            for block in session.get("blocks") or []
            if isinstance(block, dict)
            and any(
                _is_named_variant(block.get("display_name"), candidate)
                for candidate in authoritative_names
            )
        ]
        exact_targets = [
            pair for pair in targets
            if _normalise(pair[1].get("display_name")) in authoritative_names
        ]
        if len(exact_targets) > 1:
            result.unresolved.append(
                LockedMergeIssue(day_label, name, "locked block not uniquely resolved")
            )
            continue

        # The converter can emit both "Tactical Picture mental rehearsal" and
        # the exact bank title, or only qualified copies. Keep the exact block,
        # else the first qualified one; every other copy is the same locked
        # prescription with invented duration and cues, and the kept block is
        # overwritten from the bank below.
        emptied_alias_owners: list[dict[str, Any]] = []
        kept_targets = exact_targets or targets[:1]
        if len(targets) > len(kept_targets):
            for owner, duplicate in targets:
                if _is_unstarted(owner) and all(
                    duplicate is not kept_block for _, kept_block in kept_targets
                ):
                    owner["blocks"] = [
                        item for item in owner.get("blocks") or [] if item is not duplicate
                    ]
                    if not owner["blocks"] and _is_safe_named_watch_shell(owner, authoritative_names):
                        emptied_alias_owners.append(owner)
        targets = kept_targets

        if watch_sessions:
            session = watch_sessions[0]
        elif reusable_named_watch:
            # The converter used the locked drill name as the session title.
            # Reuse it as the canonical Watch instead of creating a twin card.
            session = reusable_named_watch
        elif targets:
            # Keep unrelated same-day work intact. Create the governed session,
            # then move only the authoritative block into it below.
            session = _new_watch_session(
                day_label=day_label,
                title=display_title,
                name=name,
                watch=watch,
                spec=spec,
            )
            matching_days[0].setdefault("sessions", []).append(session)
            sessions.append(session)
        else:
            session = _new_watch_session(
                day_label=day_label,
                title=display_title,
                name=name,
                watch=watch,
                spec=spec,
            )
            matching_days[0].setdefault("sessions", []).append(session)
            sessions.append(session)

        if targets:
            owner, block = targets[0]
            if owner is not session:
                owner["blocks"] = [item for item in owner.get("blocks") or [] if item is not block]
                session.setdefault("blocks", []).append(block)
        else:
            # A generic mindset block is not proof that it represents this
            # governed drill. Preserve ambiguous/unrelated content and append
            # the authoritative block instead of destructively repurposing it.
            block = _new_watch_block(
                day_label=day_label, name=name, watch=watch, spec=spec
            )
            session.setdefault("blocks", []).append(block)

        mindset = watch.get("mindset")
        mindset = mindset if isinstance(mindset, Mapping) else {}
        anchor = _mindset_anchor(watch)
        session["title"] = display_title
        session["objective"] = watch.get("why")
        if watch.get("optional") is True:
            # Offered, not required: the flag drives logging and adherence
            # (api.optional_sessions); the prefix tells the athlete.
            session["optional"] = True
            session["objective"] = f"Optional. {watch.get('why') or ''}".strip()
        else:
            session.pop("optional", None)
        session["mindset_anchor"] = anchor
        # ``coaching_cues`` carries the bank's instructions. The Fight
        # Visualisation bank's trusted ``cue`` (and its optional immediate
        # pre-bout version) are part of the prescription, so they ride along
        # rather than being dropped on the floor.
        coaching_cues = [str(value) for value in watch.get("instructions") or []]
        for extra_field, prefix in (("cue", "Cue"), ("pre_bout", "Pre-bout")):
            extra = str(watch.get(extra_field) or "").strip()
            if extra:
                coaching_cues.append(f"{prefix}: {extra}")
        block.update(
            {
                "display_name": watch.get("name") or governance.get("selected_drill_name"),
                "duration": _duration(watch),
                "coaching_cues": coaching_cues,
                "purpose": mindset.get("context") or watch.get("why"),
            }
        )
        # Only the Tactical Watch bank carries a progression rule. Writing a
        # null for a system that has no such concept would just blank a field.
        if watch.get("progress"):
            block["progression_rule"] = watch["progress"]

        if emptied_alias_owners:
            matching_days[0]["sessions"] = [
                item
                for item in matching_days[0].get("sessions") or []
                if item is session or all(item is not owner for owner in emptied_alias_owners)
            ]

        if spec.content_field == "fight_visualization":
            matching_days[0]["sessions"] = [
                item
                for item in matching_days[0].get("sessions") or []
                if item is session or not _is_generic_visualization_shell(item, name)
            ]

        if (
            watch_sessions
            and reusable_named_watch is not None
            and reusable_named_watch is not session
        ):
            # Remove the old converter shell only after its authoritative
            # content has been repaired on the canonical Watch. The safety
            # check above protects completed or independently populated work.
            matching_days[0]["sessions"] = [
                item
                for item in matching_days[0].get("sessions") or []
                if item is not reusable_named_watch
            ]
        result.applied.append(LockedMergeApplication(day_label, str(block["display_name"])))

    return result


def merge_planner_owned_structured_content(
    structured_plan: dict[str, Any], planning_brief: Any
) -> LockedMergeResult:
    """Carry all planner-owned session and contact truth into one final card.

    Contact reconciliation must run after locked sessions are present. Otherwise
    adding Tactical Focus can turn a contact-only day into a session day while
    leaving its contact truth stranded in the now-hidden day headline.
    """
    result = merge_locked_structured_content(structured_plan, planning_brief)

    reconcile_coach_led_sparring_days(result.plan, planning_brief)
    return result

fightcamp/calendar_integrity.py:
"""Final deterministic calendar integrity governor.

Stage 3 consumes ``combat_load_policy`` after the current allocator, fillers and
scheduled-day dose morph have finished. It does not define combat-load doctrine.
Only placements the shared policy marks ``FORBID`` are repaired.

Ownership boundaries:
- ``hard_sparring_plan`` is the resolved contact source of truth;
- visible hard-sparring roles are mirrors, not a second contact source;
- ``DEPRIORITIZE`` remains legal;
- normal D-14+ app roles may relocate inside their existing planner week or be
  suppressed when no legal home exists;
- D-13 inward finished-tail state and D-0 are never re-planned here;
- the governor never creates replacement training;
- if relocation changes scheduled D-day, the canonical morph owner is called
  again before final normal-camp verification.
"""

from __future__ import annotations

from collections.abc import Callable
from typing import Any

from .physical_session_frequency import audit_physical_session_frequency

from .calendar_context import (
    ContactRef as _ContactRef,
    RoleRef as _RoleRef,
    _normalise as _normalise_day,
    authoritative_contact_positions as _adapter_contact_positions,
    build_events as _adapter_build_events,
    contact_refs as _adapter_contact_refs,
    role_refs as _adapter_role_refs,
)
from .combat_load_policy import (
    CONTACT_LOAD_CLASSES,
    CalendarEvent,
    DayOccupancy,
    LoadClass,
    PlacementDecision,
    PlacementDirective,
    evaluate_candidate_at_position,
)
from .normalization import clean_list


class CalendarIntegrityError(ValueError):
    """Raised when canonical authorities leave a forbidden normal-camp state."""


# The canonical planner-state -> CalendarEvent[] construction lives in
# calendar_context so the upstream fillers and this final governor read one
# calendar. The governor runs the construction in strict mode: an unclassifiable
# physical role is a hole in the shared classifier and must fail loudly here
# rather than silently drop out of the verified calendar.
def _role_refs(weekly_role_map: dict[str, Any]) -> list[_RoleRef]:
    return _adapter_role_refs(
        weekly_role_map, strict=True, error_cls=CalendarIntegrityError
    )


def _contact_refs(weekly_role_map: dict[str, Any]) -> list[_ContactRef]:
    return _adapter_contact_refs(weekly_role_map)


def _authoritative_contact_positions(weekly_role_map: dict[str, Any]) -> set[int]:
    return _adapter_contact_positions(weekly_role_map)


def _build_events(
    weekly_role_map: dict[str, Any],
    *,
    exclude_role: dict[str, Any] | None = None,
    exclude_contact: dict[str, Any] | None = None,
) -> list[CalendarEvent]:
    return _adapter_build_events(
        weekly_role_map,
        exclude_role=exclude_role,
        exclude_contact=exclude_contact,
        strict=True,
        error_cls=CalendarIntegrityError,
    )


def _is_immutable_role(ref: _RoleRef) -> bool:
    if (
        str(ref.role.get("role_key") or "").strip().lower() == "light_combat_day"
        and bool(ref.role.get("coach_owned"))
        and bool(ref.role.get("declared_day_locked"))
    ):
        return True
    if ref.d_day <= 13 or ref.role.get("late_fight_tail_owned"):
        return True
    governance = ref.role.get("governance")
    return bool(
        isinstance(governance, dict)
        and str(governance.get("authority") or "") == "finished_late_fight_tail"
    )


def _protection_rank(ref: _RoleRef) -> tuple[int, int]:
    load = ref.profile.load_class
    if load in {
        LoadClass.ZERO_LOAD,
        LoadClass.RECOVERY_ONLY,
        LoadClass.LOW_LOAD_PHYSICAL,
        LoadClass.LOW_LOAD_AEROBIC,
    }:
        rank = 0
    elif load is LoadClass.NEURAL_MICRODOSE:
        rank = 1
    else:
        rank = 2
    try:
        session_index = int(ref.role.get("session_index") or 0)
    except (TypeError, ValueError):
        session_index = 0
    return (rank, -session_index)


def _evaluate_role(weekly_role_map: dict[str, Any], ref: _RoleRef) -> PlacementDecision:
    return evaluate_candidate_at_position(
        ref.profile,
        candidate_position=-ref.d_day,
        events=_build_events(weekly_role_map, exclude_role=ref.role),
        candidate_scope=ref.scope,
    )


def _available_destination_days(ref: _RoleRef) -> list[tuple[str, int]]:
    # Keep every calendar occurrence: a planner week may span eight days and
    # therefore contain the same weekday twice.
    calendar_days = [
        (_normalise_day(day.get("weekday")), day.get("d_day"))
        for day in ref.week.get("calendar_days") or []
        if isinstance(day, dict)
        and _normalise_day(day.get("weekday"))
        and isinstance(day.get("d_day"), int)
    ]
    declared = [
        _normalise_day(day)
        for day in clean_list(ref.week.get("declared_training_days"))
        if _normalise_day(day)
    ] or [weekday for weekday, _d_day in calendar_days]
    tail_days = {
        int(value)
        for value in ref.week.get("late_fight_tail_days") or []
        if isinstance(value, int)
    }
    return [
        (weekday, d_day)
        for weekday in declared
        for calendar_weekday, d_day in calendar_days
        if calendar_weekday == weekday
        and d_day > 13
        and d_day != ref.d_day
        and d_day not in tail_days
    ]


def _destination_occupancy_rank(events: list[CalendarEvent], d_day: int) -> int:
    profiles = [event.profile for event in events if event.position == -d_day]
    if not profiles:
        return 0
    if all(profile.occupancy is DayOccupancy.COEXISTABLE for profile in profiles):
        return 1
    return 2


def _best_destination(
    weekly_role_map: dict[str, Any], ref: _RoleRef,
    *, excluded_d_days: set[int] | None = None,
) -> tuple[str, int, PlacementDecision] | None:
    events = _build_events(weekly_role_map, exclude_role=ref.role)
    ranked: list[tuple[tuple[int, int, int, int], str, int, PlacementDecision]] = []
    for weekday, d_day in _available_destination_days(ref):
        if excluded_d_days and d_day in excluded_d_days:
            continue
        decision = evaluate_candidate_at_position(
            ref.profile,
            candidate_position=-d_day,
            events=events,
            candidate_scope=ref.scope,
        )
        if decision.directive is PlacementDirective.FORBID:
            continue
        ranked.append(
            (
                (
                    0 if decision.directive is PlacementDirective.ALLOW else 1,
                    _destination_occupancy_rank(events, d_day),
                    abs(d_day - ref.d_day),
                    -d_day,
                ),
                weekday,
                d_day,
                decision,
            )
        )
    if not ranked:
        return None
    _score, weekday, d_day, decision = min(ranked, key=lambda item: item[0])
    return weekday, d_day, decision


def relocate_or_suppress_role_for_recovery(
    weekly_role_map: dict[str, Any],
    role: dict[str, Any],
    *,
    excluded_d_days: set[int],
    reason_code: str,
    require_clean_destination: bool = False,
) -> dict[str, Any] | None:
    """Reuse the canonical mover when exercise-level recovery blocks a day.

    ``require_clean_destination`` is for a caller whose conflict is
    ``DEPRIORITIZE`` rather than ``FORBID``: the placement is legal, so the role
    moves only to a strictly ``ALLOW`` destination and is never suppressed. With
    no such destination it stays where it is and this returns ``None``. That is
    what keeps a graded cross-day rule from becoming a mandatory rest day.
    """
    ref = next((item for item in _role_refs(weekly_role_map) if item.role is role), None)
    if ref is None or _is_immutable_role(ref):
        return None

    best = _best_destination(
        weekly_role_map,
        ref,
        excluded_d_days=excluded_d_days,
    )
    if require_clean_destination and (
        best is None or best[2].directive is not PlacementDirective.ALLOW
    ):
        return None
    if best is not None:
        weekday, d_day, destination_decision = best
        from_day = str(role.get("scheduled_day_hint") or role.get("real_weekday") or "")
        _stamp_relocation(
            role,
            weekday=weekday,
            d_day=d_day,
            reason_code=reason_code,
            directive=PlacementDirective.FORBID,
        )
        return {
            "action": "relocated",
            "from_day": from_day,
            "from_d_day": ref.d_day,
            "to_day": weekday.title(),
            "to_d_day": d_day,
            "reason_code": reason_code,
            "destination_directive": destination_decision.directive.value,
        }

    decision = PlacementDecision(
        PlacementDirective.FORBID,
        reason_code,
        "No compatible closed-membership strength workload or legal recovery-spaced day was available.",
    )
    suppression = _suppress_role(
        ref,
        decision=decision,
        attempted_days=[
            weekday.title()
            for weekday, d_day in _available_destination_days(ref)
            if d_day not in excluded_d_days
        ],
    )
    return {"action": "suppressed", **suppression}


def _stamp_relocation(
    role: dict[str, Any], *, weekday: str, d_day: int, reason_code: str,
    directive: PlacementDirective,
) -> None:
    previous_day = str(role.get("scheduled_day_hint") or role.get("real_weekday") or "")
    role["scheduled_day_hint"] = weekday.title()
    if "real_weekday" in role:
        role["real_weekday"] = weekday.title()
    role["scheduled_countdown_label"] = f"D-{d_day}"
    role["scheduled_d_day"] = d_day
    if "countdown_offset" in role:
        role["countdown_offset"] = d_day
    role["calendar_integrity_relocation"] = {
        "from_day": previous_day,
        "to_day": weekday.title(),
        "to_d_day": d_day,
        "reason_code": reason_code,
        "authority": "final_calendar_integrity",
    }
    role["day_assignment_reason"] = (
        f"Final calendar integrity relocated this role to {weekday.title()} (D-{d_day}) "
        f"because the original placement was {directive.value}: {reason_code}."
    )


def _stamp_week_reduction(week: dict[str, Any], reason_code: str) -> None:
    summary = week.get("session_count_summary")
    if not isinstance(summary, dict):
        return
    summary["reduced_from_planned"] = True
    reasons = [str(value) for value in summary.get("reduction_reasons") or []]
    reason = f"calendar_integrity:{reason_code}"
    if reason not in reasons:
        reasons.append(reason)
    summary["reduction_reasons"] = reasons


def _suppress_role(
    ref: _RoleRef, *, decision: PlacementDecision, attempted_days: list[str]
) -> dict[str, Any]:
    suppression = {
        "role_key": ref.role.get("role_key"),
        "calendar_integrity": True,
        "reason_code": decision.reason_code,
        "reason": decision.reason,
        "original_day": ref.role.get("scheduled_day_hint") or ref.role.get("real_weekday"),
        "original_d_day": ref.d_day,
        "attempted_legal_days": attempted_days,
        "authority": "final_calendar_integrity",
    }
    ref.week.setdefault("suppressed_roles", []).append(suppression)
    roles = ref.week.get("session_roles")
    if isinstance(roles, list):
        roles[:] = [role for role in roles if role is not ref.role]
    _stamp_week_reduction(ref.week, decision.reason_code)
    return suppression


def _repair_forbidden_roles(
    weekly_role_map: dict[str, Any],
) -> tuple[list[dict[str, Any]], int]:
    actions: list[dict[str, Any]] = []
    deprioritized_kept = 0
    refs = sorted(
        (ref for ref in _role_refs(weekly_role_map) if not _is_immutable_role(ref)),
        key=_protection_rank,
    )
    for ref in refs:
        if ref.role not in (ref.week.get("session_roles") or []):
            continue
        decision = _evaluate_role(weekly_role_map, ref)
        if decision.directive is PlacementDirective.ALLOW:
            continue
        if decision.directive is PlacementDirective.DEPRIORITIZE:
            best = _best_destination(weekly_role_map, ref)
            if best is None or best[2].directive is not PlacementDirective.ALLOW:
                deprioritized_kept += 1
                continue
            weekday, d_day, destination_decision = best
            from_day = str(
                ref.role.get("scheduled_day_hint") or ref.role.get("real_weekday") or ""
            )
            _stamp_relocation(
                ref.role,
                weekday=weekday,
                d_day=d_day,
                reason_code=decision.reason_code,
                directive=decision.directive,
            )
            actions.append(
                {
                    "role_key": ref.role.get("role_key"),
                    "action": "relocated",
                    "from_day": from_day,
                    "from_d_day": ref.d_day,
                    "to_day": weekday.title(),
                    "to_d_day": d_day,
                    "reason_code": decision.reason_code,
                    "destination_directive": destination_decision.directive.value,
                }
            )
            continue

        destinations = _available_destination_days(ref)
        best = _best_destination(weekly_role_map, ref)
        if best is None:
            suppression = _suppress_role(
                ref,
                decision=decision,
                attempted_days=[weekday.title() for weekday, _d_day in destinations],
            )
            actions.append({"action": "suppressed", **suppression})
            continue

        weekday, d_day, destination_decision = best
        from_day = str(ref.role.get("scheduled_day_hint") or ref.role.get("real_weekday") or "")
        _stamp_relocation(
            ref.role,
            weekday=weekday,
            d_day=d_day,
            reason_code=decision.reason_code,
            directive=decision.directive,
        )
        actions.append(
            {
                "role_key": ref.role.get("role_key"),
                "action": "relocated",
                "from_day": from_day,
                "from_d_day": ref.d_day,
                "to_day": weekday.title(),
                "to_d_day": d_day,
                "reason_code": decision.reason_code,
                "destination_directive": destination_decision.directive.value,
            }
        )
    return actions, deprioritized_kept


def _verify_normal_roles(weekly_role_map: dict[str, Any]) -> list[dict[str, Any]]:
    violations: list[dict[str, Any]] = []
    contact_positions = _authoritative_contact_positions(weekly_role_map)
    for ref in _role_refs(weekly_role_map):
        # Stage 3 does not re-judge the finished D-13 tail internally. Tail events
        # remain in context so they can still constrain D-14+ roles.
        if _is_immutable_role(ref):
            continue
        if ref.profile.load_class in CONTACT_LOAD_CLASSES and -ref.d_day in contact_positions:
            continue
        decision = _evaluate_role(weekly_role_map, ref)
        if decision.directive is PlacementDirective.FORBID:
            violations.append(
                {
                    "kind": "role",
                    "role_key": ref.role.get("role_key"),
                    "d_day": ref.d_day,
                    "day": ref.role.get("scheduled_day_hint") or ref.role.get("real_weekday"),
                    "reason_code": decision.reason_code,
                }
            )
    return violations


def _verify_normal_contacts(weekly_role_map: dict[str, Any]) -> list[dict[str, Any]]:
    violations: list[dict[str, Any]] = []
    for ref in _contact_refs(weekly_role_map):
        if ref.d_day <= 13:
            continue
        decision = evaluate_candidate_at_position(
            ref.profile,
            candidate_position=-ref.d_day,
            events=_build_events(weekly_role_map, exclude_contact=ref.entry),
            candidate_scope=ref.scope,
        )
        if decision.directive is PlacementDirective.FORBID:
            violations.append(
                {
                    "kind": "resolved_contact",
                    "day": ref.entry.get("day"),
                    "d_day": ref.d_day,
                    "load_class": ref.profile.load_class.value,
                    "reason_code": decision.reason_code,
                }
            )
    return violations


def apply_final_calendar_integrity(
    weekly_role_map: dict[str, Any],
    *,
    remorph_callback: Callable[[dict[str, Any]], dict[str, Any]] | None = None,
    athlete_model: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Repair forbidden D-14+ placements and verify the final normal calendar."""
    if not isinstance(weekly_role_map, dict):
        return weekly_role_map

    checked = len(_role_refs(weekly_role_map)) + len(_contact_refs(weekly_role_map))
    actions, deprioritized_kept = _repair_forbidden_roles(weekly_role_map)
    relocated = sum(action.get("action") == "relocated" for action in actions)
    suppressed = sum(action.get("action") == "suppressed" for action in actions)

    if relocated and remorph_callback is not None:
        remorph_callback(weekly_role_map)

    violations = [
        *_verify_normal_roles(weekly_role_map),
        *_verify_normal_contacts(weekly_role_map),
    ]
    # Structural QA, not a blocker: an unexplained empty declared training day is
    # reported so the sweep can see it, while the plan still ships.
    frequency_findings = audit_physical_session_frequency(weekly_role_map, athlete_model)
    weekly_role_map["physical_session_frequency_audit"] = {
        "schema_version": "physical_session_frequency_audit.v1",
        "warnings": frequency_findings,
    }
    weekly_role_map["calendar_integrity"] = {
        "schema_version": "calendar_integrity.v1",
        "checked_roles": checked,
        "relocated_roles": relocated,
        "suppressed_roles": suppressed,
        "deprioritized_kept": deprioritized_kept,
        "unresolved_forbidden": len(violations),
        "late_fight_tail_replanned": False,
        "actions": actions,
        "violations": violations,
    }

    if violations:
        codes = ", ".join(
            sorted({str(item.get("reason_code") or "unknown") for item in violations})
        )
        raise CalendarIntegrityError(
            "Final deterministic D-14+ calendar still contains forbidden placement(s): "
            f"{codes}. Fix the canonical allocator/policy owner; do not ask the AI finalizer to repair it."
        )
    return weekly_role_map


__all__ = [
    "CalendarIntegrityError",
    "apply_final_calendar_integrity",
    "relocate_or_suppress_role_for_recovery",
]

