    if label:
        return label
    role_key = str(role.get("role_key") or "countdown session").replace("_", " ").strip()
    return role_key.capitalize()


def _late_fight_role_countdown_label(role: dict[str, Any]) -> str:
    return (
        _normalise_countdown_label(role.get("scheduled_countdown_label"))
        or _normalise_countdown_label(role.get("countdown_label"))
        or _normalise_countdown_label(role.get("countdown_display_label"))
    )


def _late_fight_role_display_label(role: dict[str, Any], countdown_label: str) -> str:
    display = str(role.get("countdown_display_label") or "").strip()
    if display:
        return display
    weekday = str(
        role.get("real_weekday")
        or role.get("countdown_weekday")
        or role.get("scheduled_day_hint")
        or ""
    ).strip()
    return f"{countdown_label} ({weekday.title()})" if weekday else countdown_label


def _late_fight_role_is_hidden_context(role: dict[str, Any]) -> bool:
    role_key = str(role.get("role_key") or "").strip().lower()
    category = str(role.get("category") or "").strip().lower()
    return bool(role_key == "hard_sparring_day" or (category == "sparring" and role.get("coach_owned")))


def _late_fight_sequence_from_brief(planning_brief: dict[str, Any]) -> list[dict[str, Any]]:
    for key in ("late_fight_session_sequence", "session_sequence", "countdown_sessions"):
        value = planning_brief.get(key)
        if isinstance(value, list) and value:
            return [entry for entry in value if isinstance(entry, dict)]
    spec = planning_brief.get("late_fight_plan_spec") or {}
    if isinstance(spec, dict):
        for key in ("visible_session_sequence", "session_sequence", "countdown_sessions", "sessions"):
            value = spec.get(key)
            if isinstance(value, list) and value:
                return [entry for entry in value if isinstance(entry, dict)]
    return []


def _late_fight_window_for_role(role: dict[str, Any]) -> str:
    stage_key = str(role.get("composite_segment_stage_key") or "").strip().lower()
    if stage_key:
        return stage_key
    offset = None
    label = _late_fight_role_countdown_label(role)
    if label.startswith("D-"):
        try:
            offset = int(label[2:])
        except ValueError:
            offset = None
    if offset is None:
        return ""
    if 8 <= offset <= 13:
        return "d13_to_d8"
    if offset == 7:
        return "d7"
    if 5 <= offset <= 6:
        return "d6_to_d5"
    if 2 <= offset <= 4:
        return "d4_to_d2"
    if offset == 1:
        return "d1"
    return ""


def _late_fight_preferred_cue(role: dict[str, Any]) -> str:
    return {
        "d13_to_d8": "Mobility Reset Flow",
        "d7": "Mobility Reset Flow",
        "d6_to_d5": "Reactive Shuffle Repeats",
        "d4_to_d2": "Breathing Reset",
        "d1": "Breathing Reset",
    }.get(_late_fight_window_for_role(role), "Mobility Reset Flow")


def _candidate_names_from_slot(slot: dict[str, Any]) -> list[str]:
    names: list[str] = []
    selected = slot.get("selected") or {}
    if isinstance(selected, dict):
        selected_name = str(selected.get("name") or "").strip()
        if selected_name:
            names.append(selected_name)
    for alternate in slot.get("alternates", []) or []:
        if not isinstance(alternate, dict):
            continue
        alternate_name = str(alternate.get("name") or "").strip()
        if alternate_name:
            names.append(alternate_name)
    return list(dict.fromkeys(names))


def _slots_for_phase_requirement(phase_pool: dict[str, Any], requirement: str) -> list[dict[str, Any]]:
    strength_slots = [slot for slot in phase_pool.get("strength_slots", []) or [] if isinstance(slot, dict)]
    conditioning_slots = [slot for slot in phase_pool.get("conditioning_slots", []) or [] if isinstance(slot, dict)]
    rehab_slots = [slot for slot in phase_pool.get("rehab_slots", []) or [] if isinstance(slot, dict)]
    if requirement == "rehab":
        return rehab_slots
    if requirement in {"aerobic", "glycolytic", "alactic"}:
        return [slot for slot in conditioning_slots if slot.get("role") == requirement]
    if requirement == "primary_strength":
        return strength_slots[:1]
    if requirement == "extra_strength_accessory":
        return strength_slots[1:]
    return [
        slot
        for slot in conditioning_slots + strength_slots + rehab_slots
        if slot.get("role") == requirement
    ]


def _render_late_fight_phase_notes(planning_brief: dict[str, Any]) -> list[str]:
    candidate_pools = planning_brief.get("candidate_pools") or {}
    phase_strategy = planning_brief.get("phase_strategy") or {}
    lines: list[str] = []
    for phase, strategy in phase_strategy.items():
        must_keep = [
            str(item).strip()
            for item in (strategy.get("must_keep") or [])
            if str(item).strip()
        ]
        if not must_keep:
            continue
        phase_pool = candidate_pools.get(phase) or {}
        phase_lines: list[str] = []
        for requirement in must_keep:
            names: list[str] = []
            for slot in _slots_for_phase_requirement(phase_pool, requirement):
                names.extend(_candidate_names_from_slot(slot))
            if not names:
                continue
            phase_lines.append(
                f"- {requirement.replace('_', ' ').title()}: {', '.join(list(dict.fromkeys(names))[:4])}"
            )
        if phase_lines:
            lines.extend(["", f"## {str(phase).upper()}", *phase_lines])
    return lines


def _late_fight_terminal_d0_header(context: PlanRuntimeContext, planning_brief: dict[str, Any]) -> str:
    spec = planning_brief.get("late_fight_plan_spec") or {}
    countdown_map = spec.get("countdown_weekday_map") if isinstance(spec, dict) else {}
    weekday = ""
    if isinstance(countdown_map, dict):
        weekday = str(countdown_map.get("D-0") or "").strip()
    if not weekday:
        weekday = _resolve_fight_weekday(context) or ""
    label = f"D-0 ({weekday.title()})" if weekday else "D-0"
    return f"### {label} - Fight day protocol"


def _render_late_fight_stage1_draft(
    *,
    context: PlanRuntimeContext,
    planning_brief: dict[str, Any],
) -> str | None:
    spec = planning_brief.get("late_fight_plan_spec") or {}
    if not isinstance(spec, dict) or not spec:
        return None

    # Same-day roles follow the planner's stamped execution order.
    sequence = in_stamped_execution_order(
        _late_fight_sequence_from_brief(planning_brief),
        _late_fight_role_countdown_label,
    )
    lines = ["# LATE-FIGHT COUNTDOWN"]
    phase_notes = _render_late_fight_phase_notes(planning_brief)
    if phase_notes:
        lines.extend(phase_notes)
    lines.extend(["", "## Countdown Sessions", ""])
    seen: set[tuple[str, str]] = set()
    for role in sequence:
        if _late_fight_role_is_hidden_context(role):
            continue
        if role.get("render_mandatory") is False:
            continue
        countdown_label = _late_fight_role_countdown_label(role)
        if not countdown_label or countdown_label == "D-0":
            continue
        identity = (countdown_label, str(role.get("role_key") or ""))
        if identity in seen:
            continue
        seen.add(identity)
        display_label = _late_fight_role_display_label(role, countdown_label)
        lines.extend(
            [
                f"### {display_label} - {_late_fight_role_display(role)}",
                f"Cue: {_late_fight_preferred_cue(role)}.",
                "Purpose: hold the assigned taper job, protect freshness, and stop if sharpness drops.",
                "",
            ]
        )

    lines.extend(
        [
            _late_fight_terminal_d0_header(context, planning_brief),
            FIGHT_DAY_PROTOCOL_TEXT,
        ]
    )
    return "\n".join(lines).strip()


def _resolve_fight_weekday(context: PlanRuntimeContext) -> str | None:
    """Prefer the actual fight_date over runtime-clock weekday arithmetic.

    The renderer must not derive the fight weekday from ``_utc_now()`` — that
    drifts every time the plan is re-rendered after the original creation day.
    ``plan_input.next_fight_date`` is the only stable input.
    """
    fight_date = getattr(context.plan_input, "next_fight_date", "") or ""
    if fight_date:
        weekday = resolve_fight_weekday(fight_date=fight_date)
        if weekday is not None:
            return weekday
    # Conservative fallback: only attempt offset arithmetic when days are known.
    # We deliberately do NOT call _utc_now(); without a stable plan-creation
    # weekday we return None rather than risk a drifted answer.
    return None


def _sparring_adjustment_lines(context: PlanRuntimeContext) -> list[str]:
    hard_days = [str(day).strip() for day in (context.plan_input.hard_sparring_days or []) if str(day).strip()]
    support_days = [str(day).strip() for day in (context.plan_input.support_work_days or []) if str(day).strip()]

    lines = ["### Sparring & Conditioning Adjustments", ""]
    if hard_days:
        lines.append(
            f"- **Expected hard sparring days:** {', '.join(hard_days)} -> Let these days own the main collision-heavy combat load and cut same-day or next-day S&C volume by about 30%."
        )
    else:
        lines.append("- **If hard sparring lands today** -> Keep S&C but cut volume by about 30% and trim accessories first.")

    if support_days:
        lines.append(
            f"- **S&C-compatible slots:** {', '.join(support_days)} -> Use these for cleaner aerobic support, recovery, primers, or lower-noise strength support."
        )
    if not hard_days:
        lines.append("- **If no sparring is fixed this week** -> Add one clear fight-pace conditioning exposure before extra lifting.")

    fight_weekday = _resolve_fight_weekday(context)
    if fight_weekday:
        lines.append(
            f"- **Fight day ({fight_weekday.title()}):** {FIGHT_DAY_PROTOCOL_TEXT} "
            "This overrides every weekday role, including any declared hard sparring day that lands on the fight date."
        )
    lines.append("")
    return lines


def _sparring_nutrition_lines(context: PlanRuntimeContext) -> list[str]:
    hard_days = [str(day).strip() for day in (context.plan_input.hard_sparring_days or []) if str(day).strip()]
    header = "- **On Expected Hard Sparring Days:**"
    if hard_days:
        header = f"- **On Expected Hard Sparring Days ({', '.join(hard_days)}):**"
    return [
        header,
        "  - Increase intra-workout carbs (e.g., 30g HBCD during session).",
        "  - Post-session: 1.2g/kg carbs + 0.4g/kg protein within 30 mins.",
        "- **If Sparring Was Unexpectedly Hard:**",
        "  - Add 500mg sodium + 20oz electrolyte drink immediately.",
        "",
    ]

def _profile_weight_lines(context: PlanRuntimeContext) -> list[str]:
    """Weight/target lines that read honestly when a field was left blank.

    Interpolating a blank straight into the template produced a bare
    ``- Target Weight: kg``, which reads as a real value to both the athlete and
    Stage 2. Say "not provided" instead.
    """
    def _line(label: str, raw: object) -> str:
        value = parse_optional_weight_value(raw)
        return f"- {label}: not provided" if value is None else f"- {label}: {raw}kg"

    return [
        _line("Weight", context.plan_input.weight),
        _line("Target Weight", context.plan_input.target_weight),
    ]


def _week_str(weeks: int, days: int) -> str:
    return "~1" if weeks == 0 and days > 0 else str(weeks)


def _display_phase_text(context: PlanRuntimeContext, text: str) -> str:
    if context.apply_muay_thai_filters:
        return _apply_muay_thai_filters(text, allow_grappling=False)
    return text


def _build_phase_model(name: str, weeks: int, days: int, mindset: str, strength: str, conditioning: str, guardrails: str) -> PhaseBlock:
    mindset = sanitize_phase_text(mindset, SANITIZE_LABELS)
    strength = sanitize_phase_text(strength, SANITIZE_LABELS)
    conditioning = sanitize_phase_text(conditioning, SANITIZE_LABELS)
    guardrails = sanitize_phase_text(guardrails, SANITIZE_LABELS) if guardrails else guardrails
    mindset = sanitize_stage_output(mindset)
    strength = sanitize_stage_output(strength)
    conditioning = sanitize_stage_output(conditioning)
    guardrails = sanitize_stage_output(guardrails) if guardrails else guardrails
    return PhaseBlock(
        name=name,
        weeks=weeks,
        days=days,
        mindset=mindset,
        strength=strength,
        conditioning=conditioning,
        guardrails=guardrails,
    )


def _format_rationale_section(title: str, phases: dict[str, list[dict]]) -> list[str]:
    lines = [f"### {title}"]
    for phase, entries in phases.items():
        lines.append(f"#### {phase}")
        for entry in entries:
            name = entry.get("name", "Unnamed")
            explanation = entry.get("explanation", "")
            if explanation:
                lines.append(f"- {name}: {explanation}")
            else:
                lines.append(f"- {name}")
    return lines


def _build_coach_notes(context: PlanRuntimeContext, blocks: PlanBlocksBundle) -> str:
    sections: list[str] = []
    previous = set(context.training_context.prev_exercises)
    if previous:
        all_strength_names = [name for phase in PHASES for name in blocks.strength_names.get(phase, [])]
        all_conditioning_names = [name for phase in PHASES for name in blocks.conditioning_names.get(phase, [])]
        novel_strength = [name for name in all_strength_names if name not in previous]
        novel_conditioning = [name for name in all_conditioning_names if name not in previous]
        sections.append(
            f"Novelty Summary: {len(novel_strength)} new strength moves, {len(novel_conditioning)} new conditioning drills."
        )
    if blocks.coach_review_notes:
        sections.append(blocks.coach_review_notes)

    coach_notes = "\n\n".join(section for section in sections if section).strip()
    if not coach_notes:
        return ""
    if context.apply_muay_thai_filters:
        coach_notes = _apply_muay_thai_filters(coach_notes, allow_grappling=False)
    return sanitize_phase_text(coach_notes, context.sanitize_labels)


def render_plan_bundle(*, context: PlanRuntimeContext, blocks: PlanBlocksBundle, logger: logging.Logger) -> RenderedPlanBundle:
    week_str = {
        phase: _week_str(context.phase_weeks[phase], context.phase_weeks["days"][phase])
        for phase in PHASES
    }
    phase_split = f"{week_str['GPP']} / {week_str['SPP']} / {week_str['TAPER']}"
    phase_week_summary = f"{week_str['GPP']} GPP / {week_str['SPP']} SPP / {week_str['TAPER']} Taper"
    phase_day_summary = (
        f"{context.phase_weeks['days']['GPP']} GPP / {context.phase_weeks['days']['SPP']} SPP / "
        f"{context.phase_weeks['days']['TAPER']} Taper"
    )
    days_out_line = (
        f"- Days Out: {context.plan_input.days_until_fight}"
        if isinstance(context.plan_input.days_until_fight, int)
        else f"- Weeks Out: {context.plan_input.weeks_out}"
    )

    late_window = classify_late_selector_window(context.plan_input.days_until_fight)
    late_fight_active = is_active_late_selector_window(late_window)

    phase_num = 1
    fight_plan_lines = ["# LATE-FIGHT COUNTDOWN" if late_fight_active else "# FIGHT CAMP PLAN"]
    phase_models: dict[str, PhaseBlock] = {}

    if late_fight_active:
        fight_plan_lines += ["## Countdown Sessions", ""]

    for phase in PHASES:
        if not context.phase_active(phase):
            continue
        phase_name = (
            f"PHASE {phase_num}: {PHASE_PLAN_TITLES[phase]} - {week_str[phase]} WEEKS "
            f"({context.phase_weeks['days'][phase]} DAYS)"
        )
        mindset = _display_phase_text(context, blocks.phase_mindsets.get(phase, ""))
        strength = _display_phase_text(
            context,
            blocks.strength_blocks[phase]["block"] if blocks.strength_blocks.get(phase) else "",
        )
        conditioning = _display_phase_text(
            context,
            blocks.conditioning_blocks.get(phase, {}).get("block", ""),
        )
        guardrails = blocks.guardrails.get(phase, "") if blocks.has_injuries else ""

        if late_fight_active:
            for body in (mindset, strength, conditioning):
                if body:
                    fight_plan_lines += [body, ""]
            if blocks.has_injuries and guardrails:
                fight_plan_lines += [guardrails, ""]
        else:
            fight_plan_lines += [
                f"## {phase_name}",
                "",
                "### Mindset Focus",
                mindset,
                "",
                "### Strength & Power",
                strength,
                "",
                "### Conditioning",
                conditioning,
                "",
            ]
            if blocks.has_injuries:
                fight_plan_lines += ["### Injury Guardrails", f"Phase: {phase}", guardrails, ""]

        phase_models[phase] = _build_phase_model(
            phase_name,
            context.phase_weeks[phase],
            context.phase_weeks["days"][phase],
            mindset,
            strength,
            conditioning,
            guardrails,
        )
        phase_num += 1

    fight_plan_lines += [
        "## Nutrition",
        blocks.nutrition_block,
        "",
        "## Recovery",
        blocks.recovery_block,
        "",
    ]

    rehab_sections: list[str] = []
    if blocks.has_injuries:
        rehab_sections = ["## Rehab Protocols"]
        for phase in PHASES:
            rehab_block = blocks.rehab_blocks.get(phase, "")
            if rehab_block:
                rehab_sections += [f"### {phase}", rehab_block.strip(), ""]
        if blocks.support_notes:
            rehab_sections += ["", blocks.support_notes]
    if rehab_sections:
        fight_plan_lines += rehab_sections

    phase_breakdown_lines = (
        []
        if late_fight_active
        else [
            f"- Phase Weeks: {phase_week_summary}",
            f"- Phase Days: {phase_day_summary}",
        ]
    )
    fight_plan_lines += [
        "",
        "## Mindset Overview",
        f"Primary Block(s): {', '.join(context.training_context.mental_block).title()}",
        "",
        *_sparring_adjustment_lines(context),
        "---",
        "",
        *_sparring_nutrition_lines(context),
        "## Athlete Profile",
        f"- **Name:** {context.plan_input.full_name}",
        f"- Age: {context.plan_input.age}",
        *_profile_weight_lines(context),
        f"- Height: {context.plan_input.height}cm",
        f"- Combat sport: {context.plan_input.fighting_style_technical}",
        f"- Tactical Style: {context.plan_input.fighting_style_tactical}",
        f"- Stance: {context.plan_input.stance}",
        f"- Status: {context.plan_input.status}",
        f"- Record: {context.plan_input.record}",
        f"- Fight Format: {context.plan_input.rounds_format}",
        f"- Fight Date: {context.plan_input.next_fight_date}",
        days_out_line,
        *phase_breakdown_lines,
        f"- Fatigue Level: {context.plan_input.fatigue}",
        f"- Injuries: {context.injuries_display}",
        f"- Training Availability: {context.plan_input.available_days}",
        f"- Hard Sparring Days: {', '.join(context.plan_input.hard_sparring_days) if context.plan_input.hard_sparring_days else 'Not specified'}",
            f"- Support Work Days: {', '.join(context.plan_input.support_work_days) if context.plan_input.support_work_days else 'Not specified'}",
        f"- Equipment Access: {context.equipment_access_display}",
        f"- Weaknesses: {context.plan_input.weak_areas}",
        f"- Key Goals: {context.plan_input.key_goals}",
        f"- Mindset Challenges: {', '.join(context.training_context.mental_block)}",
        f"- Notes: {context.plan_input.notes}",
    ]

    rehab_html = ""
    if blocks.has_injuries:
        rehab_parts: list[str] = []
        for phase in PHASES:
            rehab_block = blocks.rehab_blocks.get(phase, "")
            if rehab_block:
                rehab_parts.append(f"<h3>{phase}</h3>")
                rehab_parts.append(_md_to_html(rehab_block.strip()))
        if blocks.support_notes:
            rehab_parts.append(_md_to_html(blocks.support_notes))
        rehab_html = "\n".join(rehab_parts)

    profile_lines = [
        f"- **Name:** {context.plan_input.full_name}",
        f"- Age: {context.plan_input.age}",
        *_profile_weight_lines(context),
        f"- Height: {context.plan_input.height}cm",
        f"- Combat sport: {context.plan_input.fighting_style_technical}",
        f"- Tactical Style: {context.plan_input.fighting_style_tactical}",
        f"- Stance: {context.plan_input.stance}",
        f"- Status: {context.plan_input.status}",
        f"- Record: {context.plan_input.record}",
        f"- Fight Format: {context.plan_input.rounds_format}",
        f"- Fight Date: {context.plan_input.next_fight_date}",
        days_out_line,
        *phase_breakdown_lines,
        f"- Fatigue Level: {context.plan_input.fatigue}",
        f"- Injuries: {context.injuries_display}",
        f"- Training Availability: {context.plan_input.available_days}",
        f"- Hard Sparring Days: {', '.join(context.plan_input.hard_sparring_days) if context.plan_input.hard_sparring_days else 'Not specified'}",
            f"- Support Work Days: {', '.join(context.plan_input.support_work_days) if context.plan_input.support_work_days else 'Not specified'}",
        f"- Equipment Access: {context.equipment_access_display}",
        f"- Weaknesses: {context.plan_input.weak_areas}",
        f"- Key Goals: {context.plan_input.key_goals}",
        f"- Mindset Challenges: {', '.join(context.training_context.mental_block)}",
        f"- Notes: {context.plan_input.notes}",
    ]
    athlete_profile_html = _md_to_html("\n".join(profile_lines))
    adjustments_table = _md_to_html("\n".join(line for line in _sparring_adjustment_lines(context) if line))
    sparring_nutrition_html = _md_to_html("\n".join(line for line in _sparring_nutrition_lines(context) if line))

    coach_notes = _build_coach_notes(context, blocks)

    selection_rationale_md = "\n\n".join(
        section
        for section in (
            "\n".join(_format_rationale_section("Strength Selection", blocks.strength_reason_log)),
            "\n".join(_format_rationale_section("Conditioning Selection", blocks.conditioning_reason_log)),
        )
        if section
    )
    if context.apply_muay_thai_filters:
        selection_rationale_md = _apply_muay_thai_filters(selection_rationale_md, allow_grappling=False)
    selection_rationale_md = sanitize_phase_text(selection_rationale_md, context.sanitize_labels)
    selection_rationale_md = sanitize_stage_output(selection_rationale_md)
    fight_plan_lines += ["## Selection Rationale", selection_rationale_md]

    fight_plan_text = "\n\n".join(fight_plan_lines)
    fight_plan_text = re.sub(r"\n{3,}", "\n\n", fight_plan_text)

    logger.info("plan generated locally (first 500 chars): %s", fight_plan_text[:500])

    html = build_html_document(
        full_name=context.plan_input.full_name,
        sport=context.canonical_sport,
        phase_split=phase_split,
        status=context.plan_input.status,
        record=context.plan_input.record,
        gpp=phase_models.get("GPP"),
        spp=phase_models.get("SPP"),
        taper=phase_models.get("TAPER"),
        nutrition_block=blocks.nutrition_block,
        recovery_block=blocks.recovery_block,
        rehab_html=rehab_html,
        include_injury_sections=blocks.has_injuries,
        mindset_overview=f"Primary Block(s): {', '.join(context.training_context.mental_block).title()}",
        adjustments_table=adjustments_table,
        sparring_nutrition_html=sparring_nutrition_html,
        athlete_profile_html=athlete_profile_html,
        coach_notes=coach_notes,
        selection_rationale_html=_md_to_html(selection_rationale_md),
        short_notice=context.short_notice,
    )

    return RenderedPlanBundle(
        fight_plan_text=fight_plan_text,
        coach_notes=coach_notes,
        reason_log={
            "strength": blocks.strength_reason_log,
            "conditioning": blocks.conditioning_reason_log,
        },
        html=html,
    )


def build_stage2_outputs(
    *,
    context: PlanRuntimeContext,
    blocks: PlanBlocksBundle,
    rendered: RenderedPlanBundle,
) -> tuple[dict, dict, str]:
    stage1_selection_summary = {
        "strength_names": blocks.strength_names,
        "conditioning_names": blocks.conditioning_names,
        "strength_reason_log": blocks.strength_reason_log,
        "conditioning_reason_log": blocks.conditioning_reason_log,
        "current_phase": blocks.current_phase,
    }

    stage2_payload = build_stage2_payload(
        training_context=context.training_context,
        mapped_format=context.mapped_format,
        record=context.plan_input.record,
        rounds_format=context.plan_input.rounds_format,
        camp_len=context.camp_len,
        short_notice=context.short_notice,
        restrictions=context.plan_input.restrictions,
        phase_weeks=context.phase_weeks,
        strength_blocks=blocks.strength_blocks,
        conditioning_blocks=blocks.conditioning_blocks,
        rehab_blocks=blocks.rehab_blocks,
    )

    if isinstance(stage2_payload, dict):
        stage2_payload["stage1_selection_summary"] = stage1_selection_summary
    active_phases = [phase for phase in PHASES if context.phase_active(phase)]
    computed_support = build_computed_support(
        flags=context.training_context.to_flags(),
        phases=active_phases or None,
    )
    planning_brief = build_planning_brief(
        athlete_model=stage2_payload["athlete_model"],
        restrictions=stage2_payload["restrictions"],
        phase_briefs=stage2_payload["phase_briefs"],
        candidate_pools=stage2_payload["candidate_pools"],
        omission_ledger=stage2_payload["omission_ledger"],
        rewrite_guidance=stage2_payload["rewrite_guidance"],
        plan_input=context.plan_input,
        computed_support=computed_support,
    )

    if isinstance(planning_brief, dict):
        planning_brief["stage1_selection_summary"] = stage1_selection_summary
        late_fight_draft = _render_late_fight_stage1_draft(
            context=context,
            planning_brief=planning_brief,
        )
        if late_fight_draft:
            rendered.fight_plan_text = late_fight_draft
    # Deterministic injury / weight-cut lead summary. The validator scans the
    # first plan lines for this context, so render it right after the title.
    lead_summary = render_lead_summary(planning_brief)
    if lead_summary:
        rendered.fight_plan_text = _insert_lead_summary(
            rendered.fight_plan_text, lead_summary
        )
    stage2_handoff_text = build_stage2_handoff_text(
        stage2_payload=stage2_payload,
        plan_text=rendered.fight_plan_text,
        coach_notes=rendered.coach_notes,
        planning_brief=planning_brief,
    )
    return stage2_payload, planning_brief, stage2_handoff_text

fightcamp/planner_authority_integrity.py:
from __future__ import annotations

from functools import wraps
from typing import Any, Iterable

from .bank_authority import original_bank_entries
from .late_selector_windows import late_window_allowed


_CANONICAL_PHASES = ("GPP", "SPP", "TAPER")

PLANNER_AUTHORITY_BLOCKER_CODES = frozenset(
    {
        "selected_exercise_phase_unresolved",
        "selected_exercise_phase_ineligible",
        "selected_exercise_late_window_ineligible",
        "selected_loaded_exercise_forbidden",
        "late_physical_role_missing_assignment",
    }
)

# The blocker above means "we cannot explain why this day is empty", which is a
# corrupt or incomplete pipeline state. One narrow case is different: an
# allocator role the existing policy marks OPTIONAL (``required`` False), whose
# selection was genuinely exhausted because governance rejected every candidate
# it considered. Holding an otherwise-valid plan for that strands the whole plan
# over a day that was legitimately left empty. It is reported under its own code,
# carrying the same rejection diagnostics, and is deliberately absent from
# PLANNER_AUTHORITY_BLOCKER_CODES.
#
# Everything else still blocks: required exposures (strength touch, alactic
# sharpness, neural primer, freshness), roles carrying no ``required`` verdict at
# all, and any absence governance cannot account for.
LATE_PHYSICAL_ROLE_SAFE_OMISSION_CODE = "late_physical_role_safely_omitted"

# Only a plan that SCHEDULED something unsafe is worth withholding from the
# athlete. The four codes below each describe exactly that: an exercise placed
# outside its permitted phase or late window, loaded work on a no-load day, or a
# dated exercise that cannot be mapped to a phase at all.
#
# A missing exposure is not in that class. An empty D-11, or a speed touch that
# found no legal candidate, leaves the rest of the plan correct and safe; holding
# the whole plan over it helps nobody and buries the real signal. Those findings
# still travel to the admin review surface -- they are simply not a reason to
# withhold an otherwise valid plan. This keeps the deliberate Stage-2 release
# policy ("validators are observational once usable plan text exists") intact for
# everything except genuinely unsafe output.
AUTHORITY_RELEASE_HOLD_CODES = frozenset(
    PLANNER_AUTHORITY_BLOCKER_CODES - {"late_physical_role_missing_assignment"}
)
_AUTHORITY_ADMIN_FLAG_CODES = frozenset(
    PLANNER_AUTHORITY_BLOCKER_CODES - AUTHORITY_RELEASE_HOLD_CODES
)

_ASSIGNMENT_REJECTION_KEYS = (
    "phase_window_rejected",
    "sport_rejected",
    "day_safety_rejected",
)


def _selection_was_exhausted(role: dict[str, Any]) -> bool:
    """True when governance recorded rejecting every candidate it considered.

    The assignment list is empty by the time this is asked, so any recorded
    rejection means nothing survived. No recorded rejection means no candidate
    was ever considered, which is a pipeline failure rather than an explanation.
    """
    diagnostics = role.get("late_assignment_diagnostics")
    if not isinstance(diagnostics, dict):
        return False
    for key in _ASSIGNMENT_REJECTION_KEYS:
        try:
            if int(diagnostics.get(key) or 0) > 0:
                return True
        except (TypeError, ValueError):
            continue
    return False


def _is_safely_omittable_role(role: dict[str, Any]) -> bool:
    """Optional by the allocator's own policy, and genuinely out of candidates."""
    return role.get("required") is False and _selection_was_exhausted(role)


# Clearly external-loaded strength equipment. This intentionally does not include
# bands: late-camp support work may legitimately use light band resistance even
# when loaded lifting is disabled.
_LOADED_STRENGTH_EQUIPMENT = frozenset(
    {
        "barbell",
        "dumbbell",
        "dumbbells",
        "kettlebell",
        "kettlebells",
        "trap_bar",
        "trap bar",
        "landmine",
        "sandbag",
        "log",
        "atlas_stone",
        "atlas stone",
        "weighted_vest",
        "weighted vest",
        "cable",
        "cables",
        "machine",
        "plate",
        "plates",
        "weight_plate",
        "weight plate",
        "smith_machine",
        "smith machine",
    }
)


def _normalise_phase(value: object) -> str:
    phase = str(value or "").strip().upper()
    return phase if phase in _CANONICAL_PHASES else ""


def _normalise_phase_list(value: object) -> set[str]:
    if isinstance(value, str):
        values = [value]
    elif isinstance(value, (list, tuple, set)):
        values = list(value)
    else:
        values = []
    return {
        phase
        for phase in (_normalise_phase(item) for item in values)
        if phase
    }


def _normalise_tokens(value: object) -> set[str]:
    """Normalise scalar/list metadata into comma-safe lower-case tokens."""
    if value is None:
        return set()

    values = list(value) if isinstance(value, (list, tuple, set)) else [value]
    raw: list[str] = []
    for item in values:
        text = str(item or "").strip()
        if not text:
            continue
        raw.extend(text.replace(",", " ").split())

    return {
        " ".join(token.strip().lower().replace("-", "_").split())
        for token in raw
        if token.strip()
    }


def _athlete_model(planning_brief: dict[str, Any]) -> dict[str, Any]:
    for key in ("athlete_model", "athlete_snapshot"):
        value = planning_brief.get(key)
        if isinstance(value, dict) and value:
            return value
    return {}


def _role_countdown_offset(role: dict[str, Any]) -> int | None:
    for key in (
        "countdown_offset",
        "scheduled_d_day",
        "scheduled_countdown_label",
        "countdown_label",
    ):
        value = role.get(key)
        if isinstance(value, int):
            return value if value >= 0 else None
        text = str(value or "").strip().upper()
        if text.startswith("D-"):
            try:
                return int(text[2:])
            except ValueError:
                continue
    return None


def _stage1_phase_for_offset(athlete_model: dict[str, Any], offset: int) -> str:
    """Independently resolve Stage 1 phase ownership for a D-day.

    Do not call the late-selector helper here. The release gate intentionally
    recomputes the mapping from the canonical Stage 1 ``phase_weeks.days`` data
    so a defect in selector phase resolution cannot automatically be repeated by
    the validator that is supposed to catch it.
    """
    phase_weeks = athlete_model.get("phase_weeks")
    if not isinstance(phase_weeks, dict):
        return ""
    phase_days = phase_weeks.get("days")
    if not isinstance(phase_days, dict):
        return ""

    normalised_days: dict[str, int] = {}
    for phase in _CANONICAL_PHASES:
        try:
            normalised_days[phase] = max(0, int(phase_days.get(phase, 0) or 0))
        except (TypeError, ValueError):
            return ""

    if not any(normalised_days.values()):
        return ""

    remaining = max(1, int(offset))
    for phase in ("TAPER", "SPP", "GPP"):
        days = normalised_days[phase]
        if days <= 0:
            continue
        if remaining <= days:
            return phase
        remaining -= days
    return ""


def _scheduled_phase(
    role: dict[str, Any],
    *,
    athlete_model: dict[str, Any],
    week_phase: object,
) -> str:
    offset = _role_countdown_offset(role)
    if offset is not None:
        # Dated roles are fail-closed. Never fall back to a stale week/role phase
        # when Stage 1 phase authority is missing or cannot own this D-day.
        return _stage1_phase_for_offset(athlete_model, offset)
    return _normalise_phase(week_phase) or _normalise_phase(role.get("phase"))


def _role_envelope(role: dict[str, Any]) -> dict[str, Any]:
    envelope = role.get("effective_strength_envelope")
    if isinstance(envelope, dict):
        return envelope
    cap = role.get("strength_dose_cap")
    return cap if isinstance(cap, dict) else {}


def _is_clearly_loaded_strength_item(
    item: dict[str, Any],
    *,
    role: dict[str, Any],
    assignment: dict[str, Any],
) -> bool:
    slot_group = str(assignment.get("slot_group") or "").strip()
    category = str(role.get("category") or "").strip().lower()
    if slot_group != "strength_slots" and category != "strength":
        return False
    equipment = _normalise_tokens(item.get("equipment"))
    return bool(equipment & _LOADED_STRENGTH_EQUIPMENT)


def _phase_compatible_entries(
    entries: list[dict[str, Any]],
    *,
    phase: str,
) -> list[dict[str, Any]]:
    return [
        item
        for item in entries
        if phase in _normalise_phase_list(item.get("phases"))
    ]


def _iter_scheduled_roles(
    planning_brief: dict[str, Any],
) -> Iterable[tuple[str, dict[str, Any]]]:
    role_map = planning_brief.get("weekly_role_map")
    if not isinstance(role_map, dict):
        return
    for week in role_map.get("weeks", []) or []:
        if not isinstance(week, dict):
            continue
        week_phase = _normalise_phase(week.get("phase"))
        for role in week.get("session_roles", []) or []:
            if isinstance(role, dict):
                yield week_phase, role


def planner_authority_findings(planning_brief: dict[str, Any]) -> list[dict[str, Any]]:
    """Validate selected physical assignments against original bank authority."""
    if not isinstance(planning_brief, dict):
        return []

    athlete_model = _athlete_model(planning_brief)
    findings: list[dict[str, Any]] = []
    seen: set[tuple[str, str, str]] = set()

    for week_phase, role in _iter_scheduled_roles(planning_brief):
        assignments = role.get("selected_exercise_assignments")
        category = str(role.get("category") or "").strip().lower()
        if (
            role.get("late_fight_tail_owned")
            and category in {"strength", "conditioning"}
            and (not isinstance(assignments, list) or not assignments)
        ):
            explained = _is_safely_omittable_role(role)
            findings.append(
                {
                    "code": (
                        LATE_PHYSICAL_ROLE_SAFE_OMISSION_CODE
                        if explained
                        else "late_physical_role_missing_assignment"
                    ),
                    "severity": "info" if explained else "blocker",
                    "message": (
                        "An optional dated role exhausted its candidates: every one was rejected "
                        "by phase, window, sport or day-safety governance, so the day is empty."
                        if explained
                        else "A dated app-owned physical role has no deterministic exercise assignment."
                    ),
                    "countdown_label": str(
                        role.get("scheduled_countdown_label")
                        or role.get("countdown_label")
                        or ""
                    ).strip(),
                    "role_key": role.get("role_key"),
                    "scheduled_phase": _scheduled_phase(role, athlete_model=athlete_model, week_phase=week_phase),
                    "attempted_slot_groups": ["strength_slots", "conditioning_slots"],
                    "rejection_summary": role.get("late_assignment_diagnostics") or {},
                }
            )
            continue
        if not isinstance(assignments, list) or not assignments:
            continue

        offset = _role_countdown_offset(role)
        scheduled_phase = _scheduled_phase(
            role,
            athlete_model=athlete_model,
            week_phase=week_phase,
        )
        envelope = _role_envelope(role)
        loaded_allowed = envelope.get("loaded_allowed") is not False
        countdown_label = str(
            role.get("scheduled_countdown_label")
            or role.get("countdown_label")
            or (f"D-{offset}" if offset is not None else "")
        ).strip()

        for assignment in assignments:
            if not isinstance(assignment, dict):
                continue
            name = str(assignment.get("name") or "").strip()
            if not name:
                continue

            entries = original_bank_entries(assignment)
            if not entries:
                # Only original-bank-backed physical assignments are in scope.
                continue

            identity = (
                countdown_label,
                str(role.get("role_key") or ""),
                name,
            )
            if identity in seen:
                continue
            seen.add(identity)

            if offset is not None and not scheduled_phase:
                findings.append(
                    {
                        "code": "selected_exercise_phase_unresolved",
                        "severity": "blocker",
                        "message": "A dated selected exercise could not be mapped to the canonical Stage 1 phase allocation.",
                        "exercise": name,
                        "countdown_label": countdown_label,
                        "role_key": role.get("role_key"),
                        "source_phase": assignment.get("source_phase"),
                    }
                )
                continue

            allowed_phases = sorted(
                {
                    phase
                    for item in entries
                    for phase in _normalise_phase_list(item.get("phases"))
                }
            )
            phase_entries = (
                _phase_compatible_entries(entries, phase=scheduled_phase)
                if scheduled_phase
                else entries
            )

            if scheduled_phase and allowed_phases and not phase_entries:
                findings.append(
                    {
                        "code": "selected_exercise_phase_ineligible",
                        "severity": "blocker",
                        "message": "Selected exercise is not permitted by its original bank metadata for the scheduled Stage 1 phase.",
                        "exercise": name,
                        "scheduled_phase": scheduled_phase,
                        "allowed_phases": allowed_phases,
                        "countdown_label": countdown_label,
                        "role_key": role.get("role_key"),
                        "source_phase": assignment.get("source_phase"),
                    }
                )
                continue

            if (
                # Countdown proximity does not transfer exercise authority from
                # the normal camp planner to the dedicated late-tail selector.
                role.get("late_fight_tail_owned")
                and offset is not None
                and phase_entries
                and not late_window_allowed(phase_entries, offset=offset)
            ):
                findings.append(
                    {
                        "code": "selected_exercise_late_window_ineligible",
                        "severity": "blocker",
                        "message": "Selected exercise is outside every explicit late-window permission declared by its original bank metadata.",
                        "exercise": name,
                        "scheduled_phase": scheduled_phase,
                        "countdown_label": countdown_label,
                        "role_key": role.get("role_key"),
                    }
                )

            if not loaded_allowed and any(
                _is_clearly_loaded_strength_item(
                    item,
                    role=role,
                    assignment=assignment,
                )
                for item in phase_entries
            ):
                findings.append(
                    {
                        "code": "selected_loaded_exercise_forbidden",
                        "severity": "blocker",
                        "message": "A clearly loaded strength exercise was selected while the scheduled strength envelope forbids loaded work.",
                        "exercise": name,
                        "scheduled_phase": scheduled_phase,
                        "countdown_label": countdown_label,
                        "role_key": role.get("role_key"),
                    }
                )

    return findings


def late_physical_planner_preflight(planning_brief: dict[str, Any]) -> list[dict[str, Any]]:
    """Fail before model rendering for canonically late-tail-owned physical roles only."""
    from .goal_preservation import _effective_map

    weeks = []
    for week in _effective_map(planning_brief).get("weeks", []) or []:
        roles = []
        for role in week.get("session_roles", []) or []:
            if (
                not role.get("late_fight_tail_owned")
                or role.get("category") not in {"strength", "conditioning"}
                or role.get("nonphysical")
                or role.get("preferred_pool") == "rehab_slots_or_recovery_only"
                or role.get("role_key") in {"hard_sparring_day", "light_combat_day"}
            ):
                continue
            assignments = role.get("selected_exercise_assignments")
            valid_members = [
                item
                for item in assignments or []
                if isinstance(item, dict)
                and item.get("name")
                and original_bank_entries(item)
            ] if isinstance(assignments, list) else []
            roles.append({**role, "selected_exercise_assignments": valid_members})
        weeks.append({**week, "session_roles": roles})
    return planner_authority_findings({**planning_brief, "weekly_role_map": {"weeks": weeks}})


def _authority_findings_from_report(
    report: dict[str, Any],
    *,
    codes: frozenset[str] = PLANNER_AUTHORITY_BLOCKER_CODES,
) -> list[dict[str, Any]]:
    findings: list[dict[str, Any]] = []
    seen: set[tuple[str, str, str]] = set()
    for field in ("errors", "blocking_warnings", "warnings", "review_flags"):
        # A malformed collection (anything but a list) must not crash the gate.
        # The release policy already records it via release_policy_malformed_fields.
        collection = report.get(field)
        if not isinstance(collection, list):
            continue
        for item in collection:
            if not isinstance(item, dict):
                continue
            code = str(item.get("code") or "").strip()
            if code not in codes:
                continue
            identity = (
                code,
                str(item.get("exercise") or ""),
                str(item.get("countdown_label") or ""),
            )
            if identity in seen:
                continue
            seen.add(identity)
            findings.append(dict(item))
    return findings


# An independent planner-authority gate before athlete release.
# ``fightcamp.stage2_pipeline`` and ``fightcamp.stage2_policy`` apply these
# wrappers where they define the functions, so every importer gets the governed
# version.


def governed_validator_report_builder(original_report_builder):
    """Validator reports carry planner-authority findings as errors."""

    @wraps(original_report_builder)
    def authority_report_builder(*, planning_brief: dict, final_plan_text: str):
        report = original_report_builder(
            planning_brief=planning_brief,
            final_plan_text=final_plan_text,
        )
        findings = planner_authority_findings(planning_brief)
        if not findings:
            return report

        errors = [
            dict(item)
            for item in report.get("errors", []) or []
            if isinstance(item, dict)
        ]
        existing = {
            (
                str(item.get("code") or ""),
                str(item.get("exercise") or ""),
                str(item.get("countdown_label") or ""),
            )
            for item in errors
        }
        for finding in findings:
            identity = (
                str(finding.get("code") or ""),
                str(finding.get("exercise") or ""),
                str(finding.get("countdown_label") or ""),
            )
            if identity not in existing:
                errors.append(finding)
                existing.add(identity)

        return {
            **report,
            "errors": errors,
            "is_valid": False,
            "planner_authority_integrity_findings": findings,
            "planner_authority_integrity_finding_count": len(findings),
        }

    return authority_report_builder


def governed_release_policy(original_release_policy):
    """Authority blockers hold release; missing exposures are flagged for admin review."""

    @wraps(original_release_policy)
    def authority_release_policy(validator_report: dict):
        # Capture integrity blockers before the ordinary policy transforms the
        # report, then also inspect its result. This gate must not depend on the
        # observational policy preserving a particular field layout.
        blockers = _authority_findings_from_report(
            validator_report, codes=AUTHORITY_RELEASE_HOLD_CODES
        )
        report = original_release_policy(validator_report)
        if not blockers:
            blockers = _authority_findings_from_report(
                report, codes=AUTHORITY_RELEASE_HOLD_CODES
            )

        # Missing exposures are surfaced for admin review, never held.
        missing = _authority_findings_from_report(
            validator_report, codes=_AUTHORITY_ADMIN_FLAG_CODES
        ) or _authority_findings_from_report(report, codes=_AUTHORITY_ADMIN_FLAG_CODES)
        if missing:
            admin_flags = [
                *(report.get("admin_review_blocking_flags") or []),
                *missing,
            ]
            report = {
                **report,
                "admin_review_blocking_flags": admin_flags,
                "admin_review_blocking_flag_count": len(admin_flags),
                "planner_authority_missing_exposure_findings": missing,
                "planner_authority_missing_exposure_count": len(missing),
            }
            if not blockers and report.get("release_decision") == "publish":
                report = {**report, "release_decision": "publish_with_flags"}

        if not blockers:
            return report

        return {
            **report,
            "planner_authority_integrity_findings": blockers,
            "planner_authority_integrity_finding_count": len(blockers),
            "planner_authority_integrity_hold": True,
            "release_decision": "hold",
            "is_athlete_releasable": False,
            "is_publishable": False,
        }

    return authority_release_policy


def governed_build_stage2_retry(original_build_retry):
    """A retry cannot repair an authority violation: it requires planner regeneration."""

    @wraps(original_build_retry)
    def authority_build_stage2_retry(*args, **kwargs):
        result = original_build_retry(*args, **kwargs)
        report = result.get("validator_report") if isinstance(result, dict) else None
        blockers = (
            _authority_findings_from_report(report)
            if isinstance(report, dict)
            else []
        )
        if not blockers:
            return result

        # Renderer/LLM repair cannot make an upstream illegal candidate legal.
        # Keep the plan held and require deterministic planner regeneration.
        return {
            **result,
            "needs_retry": False,
            "requires_planner_regeneration": True,
            "repair_prompt": None,
            "summary": "FAIL: selected exercise authority requires deterministic planner regeneration.",
            "summary_lines": [
                str(item.get("message") or "Planner authority violation.")
                for item in blockers
            ],
        }

    return authority_build_stage2_retry

fightcamp/session_composition.py:
"""Authoritative exercise composition for scheduled physical sessions.

Candidate pools remain planning evidence. This module records the smaller,
deterministic set that the calendar actually assigns to each session; dose
resolution remains downstream of this boundary.

Normal strength composition is deliberately reduce-only:
- Stage 1's selected slots are the only candidates considered.
- session role sets the fresh-state exercise ceiling;
- fatigue, weight-cut severity, and injury state can only tighten that ceiling;
- existing exercise tags/classification prevent redundant same-quality loading;
- Stage 2 receives the final closed membership and never chooses replacements.
"""

from __future__ import annotations

import re
from collections.abc import Callable
from typing import Any

from .exercise_identity import stamp_exercise_key
from .normalization import normalize_fatigue_level
from .planner_context import get_planner_athlete_model
