)


_NORMAL_STRENGTH_ROLE_CAPS: dict[str, int] = {
    "primary_strength_day": 4,
    "structural_strength_day": 4,
    "secondary_strength_day": 3,
    "neural_plus_strength_day": 3,
    "transfer_strength_day": 3,
    "strength_touch_day": 2,
