                        "Reactive Shuffle Repeats",
                        "Mobility Reset Flow",
                        "Breathing Reset",
                    ],
                    "reason": "D-13 may keep low-damage sharpness but must not render SPP-only sprint-start or resisted acceleration work.",
                }
            )
        elif day == 6:
            rules.append(
                {
                    "countdown_label": "D-6",
                    "blocked_drills": [
