                    onClick={() => goToPlansPage(1)}
                    disabled={isDirectoryLoading || !plansHasMore}
                  >
                    Next
                  </button>
                </div>
              </>
            )}
          </AdminQueue>
        </div>
      </section>
    </RequireAuth>
  );
}

