"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useTranslations } from "next-intl";
import {
  useCallback,
  useEffect,
  useRef,
  useState,
  useTransition,
  type FormEvent,
  type ReactNode,
} from "react";

import { useAppSession } from "@/components/auth-provider";
import { PasswordStrengthMeter } from "@/components/password-strength-meter";
import { isTurnstileConfigured, TurnstileChallenge } from "@/components/turnstile-challenge";
import { getMe } from "@/lib/api";
import { AUTH_FEEDBACK, getLoginErrorMessage, getMagicLinkErrorMessage } from "@/lib/auth-feedback";
import { clearAuthLinkParams, readAuthLinkStatus } from "@/lib/auth-link";
import { getAuthenticatedLandingHref } from "@/lib/auth-routing";
import {
  TERMS_CONSENT_LEAD,
  TERMS_LINK_LABEL,
  consentCopyForBand,
  provisionalAgeBand,
  signupConsentBlockReason,
} from "@/lib/compliance";
import { PRIVACY_HREF, TERMS_HREF } from "@/lib/legal-documents";
import { recordCompliance } from "@/lib/api";
import { evaluatePasswordStrength } from "@/lib/password-strength";
import { ATHLETE_FULL_NAME_MAX } from "@/lib/input-limits";
import { buildAuthRedirectUrl } from "@/lib/site-url";
import { getSupabaseBrowserClient } from "@/lib/supabase";
import type { UserRole } from "@/lib/types";

/** How long Turnstile gets to pass on its own before the hint explains the disabled button. */
const CAPTCHA_HINT_DELAY_MS = 2500;

const SIGNUP_ROLE_LABELS: Partial<Record<UserRole, string>> = {
  athlete: "Athlete",
};

const CAPTCHA_REQUIRED_MESSAGE = "Complete the security check, then try again.";
const CAPTCHA_UNAVAILABLE_MESSAGE = "The security check could not load. Refresh the page and try again.";

export function AuthForm({
  mode,
  role,
  onChangeRole,
  footerSlot,
}: {
  mode: "signup" | "login";
  role?: UserRole;
  onChangeRole?: () => void;
  footerSlot?: ReactNode;
}) {
  const t = useTranslations("Auth");
  const router = useRouter();
  const { isReady, session, me } = useAppSession();
  const emailInputRef = useRef<HTMLInputElement | null>(null);
  const [fullName, setFullName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [dateOfBirth, setDateOfBirth] = useState("");
  const [acceptedTerms, setAcceptedTerms] = useState(false);
  const [healthDataConsent, setHealthDataConsent] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [captchaToken, setCaptchaToken] = useState<string | null>(null);
  const [captchaResetKey, setCaptchaResetKey] = useState(0);
  const [isPending, startTransition] = useTransition();
  const [isMagicLinkPending, startMagicLinkTransition] = useTransition();
  const passwordStrength = evaluatePasswordStrength(password, { fullName, email });
  const requiresCaptcha = isTurnstileConfigured();
  const isSignupPasswordBlocked = mode === "signup" && !passwordStrength.isAcceptable;
  const isCaptchaBlocked = requiresCaptcha && !captchaToken;
  // Turnstile usually passes on its own within a few seconds; only explain the
  // disabled button once it has clearly stalled, so an auto-pass never flashes
  // the hint. Once due it stays due, so a later expiry explains itself at once.
  const [captchaHintDue, setCaptchaHintDue] = useState(false);
  useEffect(() => {
    if (!isCaptchaBlocked || captchaHintDue) return;
    const timer = window.setTimeout(() => setCaptchaHintDue(true), CAPTCHA_HINT_DELAY_MS);
    return () => window.clearTimeout(timer);
  }, [isCaptchaBlocked, captchaHintDue]);
  // Client-side courtesy checks only. The backend and a Postgres trigger both
  // reject an under-13 signup, and the server stamps every consent record, so
  // disabling the button here is about giving a clear message — not about being
  // the control.
  const signupBlockReason =
    mode === "signup" ? signupConsentBlockReason({ dateOfBirth, acceptedTerms }) : null;
  // Health-data consent is deliberately NOT part of this condition. Making it a
  // precondition of creating an account would make it conditional, and consent
  // that is a condition of the service is not freely given (UK GDPR Art. 7(4)) —
  // which would invalidate the very Article 9 basis it exists to establish. An
  // athlete can decline it, keep their account, and give it later from Settings.
  const isSignupConsentBlocked = signupBlockReason !== null;
  // Wording only. The band is derived locally from the date being typed so the
  // explanation matches the reader before the profile exists; the server
  // re-derives it from the stored date and owns every actual consequence.
  const consentCopy = consentCopyForBand(provisionalAgeBand(dateOfBirth));

  const handleCaptchaUnavailable = useCallback(() => {
    setError(CAPTCHA_UNAVAILABLE_MESSAGE);
  }, []);

  function resetCaptcha() {
    if (!requiresCaptcha) {
      return;
    }
    setCaptchaToken(null);
    setCaptchaResetKey((current) => current + 1);
  }

  useEffect(() => {
    if (!isReady) {
      return;
    }
    if (session && me) {
      router.replace(getAuthenticatedLandingHref(me));
    }
  }, [isReady, me, router, session]);

  useEffect(() => {
    if (mode === "login" && window.matchMedia("(min-width: 721px)").matches) {
      emailInputRef.current?.focus();
    }
  }, [mode]);

  useEffect(() => {
    const linkStatus = readAuthLinkStatus({
      hash: window.location.hash,
      search: window.location.search,
    });
    if (linkStatus.kind === "error") {
      setError(linkStatus.message);
      clearAuthLinkParams();
    }
  }, []);

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setMessage(null);
    setError(null);

    if (mode === "signup" && !passwordStrength.isAcceptable) {
      setError(passwordStrength.feedback);
      return;
    }

    if (signupBlockReason) {
      setError(signupBlockReason);
      return;
    }

    const captchaTokenForRequest = requiresCaptcha ? captchaToken ?? undefined : undefined;
    if (requiresCaptcha && !captchaTokenForRequest) {
      setError(CAPTCHA_REQUIRED_MESSAGE);
      return;
    }

    startTransition(async () => {
      let client;
      try {
        client = getSupabaseBrowserClient();
      } catch {
        setError(AUTH_FEEDBACK.connectionFailure);
        return;
      }

      if (mode === "signup") {
        const selectedRole: UserRole = role ?? "athlete";
        let signUpResult;
        try {
          signUpResult = await client.auth.signUp({
            email,
            password,
            options: {
              captchaToken: captchaTokenForRequest,
              emailRedirectTo: buildAuthRedirectUrl("/login"),
              data: {
                full_name: fullName,
                // Seeds the profile's date of birth on first sign-in and lets a
                // Postgres trigger reject an under-13 signup even when the
                // caller bypasses this form. The server re-reads and re-derives
                // the age band; nothing trusts this value as an age claim.
                date_of_birth: dateOfBirth,
                role: selectedRole,
              },
            },
          });
        } catch {
          resetCaptcha();
          setError(AUTH_FEEDBACK.connectionFailure);
          return;
        }

        const { data, error: signUpError } = signUpResult;
        if (signUpError) {
          resetCaptcha();
          setError(signUpError.message);
          return;
        }
        // A Turnstile token is single-use, so the widget must be reset whenever
        // the athlete stays on this form and may submit again. It is NOT reset
        // when a session came back: the form is about to navigate away, and
        // resetting there re-runs the human check on screen while the redirect
        // is still in flight.
        if (data.session) {
          // Record the acceptances against the new session so the evidence is
          // server-stamped and versioned. If this call fails the account still
          // exists but is not consented, and the compliance gate catches it on
          // the next screen — so a failure here is surfaced, not swallowed.
          try {
            await recordCompliance(data.session.access_token, {
              date_of_birth: dateOfBirth,
              accept_terms: true,
              // Only sent when ticked. Sending `false` would record a
              // withdrawal, and someone who never consented has not withdrawn —
              // those are different facts and the audit trail keeps them apart.
              ...(healthDataConsent ? { health_data_consent: true } : {}),
            });
          } catch (complianceError) {
            setError(
              complianceError instanceof Error
                ? complianceError.message
                : "Your account was created but your consent could not be saved. Sign in to finish setup.",
            );
            return;
          }
          router.replace("/onboarding");
          return;
        }
        resetCaptcha();
        setMessage("Check your email to confirm your account, then log in.");
        return;
      }

      let loginResult;
      try {
        loginResult = await client.auth.signInWithPassword({
          email,
          password,
          options: { captchaToken: captchaTokenForRequest },
        });
      } catch {
        resetCaptcha();
        setError(AUTH_FEEDBACK.connectionFailure);
        return;
      }

      const { data, error: loginError } = loginResult;
      if (loginError) {
        resetCaptcha();
        setError(getLoginErrorMessage(loginError));
        return;
      }
      // Signed in: leave the widget alone. Resetting here made it verify a
      // second time, with the "complete the human check" hint back on screen,
      // for as long as the profile lookup and redirect below took.

      const accessToken = data.session?.access_token ?? null;
      if (!accessToken) {
        router.replace("/plans");
        return;
      }

      const nextMe = await getMe(accessToken).catch(() => null);
      router.replace(nextMe ? getAuthenticatedLandingHref(nextMe) : "/plans");
    });
  }

  function handleMagicLink() {
    setMessage(null);
    setError(null);
    const trimmedEmail = email.trim();
    if (!trimmedEmail) {
      setError("Enter your email above, then request a sign-in link.");
      return;
    }

    const captchaTokenForRequest = requiresCaptcha ? captchaToken ?? undefined : undefined;
    if (requiresCaptcha && !captchaTokenForRequest) {
      setError(CAPTCHA_REQUIRED_MESSAGE);
      return;
    }

    startMagicLinkTransition(async () => {
      let client;
      try {
        client = getSupabaseBrowserClient();
      } catch {
        setError(AUTH_FEEDBACK.connectionFailure);
        return;
      }
      const redirectTo = buildAuthRedirectUrl("/login");
      let magicLinkResult;
      try {
        magicLinkResult = await client.auth.signInWithOtp({
          email: trimmedEmail,
          options: {
            captchaToken: captchaTokenForRequest,
            shouldCreateUser: mode === "signup",
            emailRedirectTo: redirectTo,
          },
        });
      } catch {
        resetCaptcha();
        setError(AUTH_FEEDBACK.connectionFailure);
        return;
      }
      resetCaptcha();

      const { error: otpError } = magicLinkResult;
      if (otpError) {
        setError(getMagicLinkErrorMessage(otpError));
        return;
      }
      setMessage(AUTH_FEEDBACK.magicLinkSent);
    });
  }

  return (
    <section className="auth-layout">
      <div className="auth-card">
        <div className="auth-header">
          <div>
            <p className="kicker">{mode === "signup" ? t("createAccount") : t("welcomeBack")}</p>
            <h2>{mode === "signup" ? t("startIntake") : t("continueCamp")}</h2>
            {mode === "signup" && role ? (
              <p className="auth-selected-role muted">
                {t("signingUpAs", { role: role === "athlete" ? t("athlete") : SIGNUP_ROLE_LABELS[role] ?? role })}
                {onChangeRole ? (
                  <>
                    {" · "}
                    <button type="button" className="auth-text-link auth-inline-link" onClick={onChangeRole}>
                      {t("change")}
                    </button>
                  </>
                ) : null}
              </p>
            ) : null}
          </div>
          {mode === "signup" ? <span className="badge status-badge-neutral">{t("beta")}</span> : null}
        </div>

        {message ? (
          <div className="success-banner" role="status" aria-live="polite" aria-atomic="true">
            {message}
          </div>
        ) : null}
        {error ? (
          <div className="error-banner" role="alert" aria-live="assertive" aria-atomic="true">
            {error}
          </div>
        ) : null}

        <form onSubmit={handleSubmit} className="auth-form-grid">
          {mode === "signup" ? (
            <div className="field">
              <label htmlFor="fullName">{t("fullName")}</label>
              <input
                id="fullName"
                name="name"
                autoComplete="name"
                value={fullName}
                onChange={(event) => setFullName(event.target.value)}
                maxLength={ATHLETE_FULL_NAME_MAX}
                required
              />
            </div>
          ) : null}
          <div className="field">
            <label htmlFor="email">{t("email")}</label>
            <input
              id="email"
              name="email"
              type="email"
              inputMode="email"
              autoComplete="email"
              autoCapitalize="none"
              autoCorrect="off"
              spellCheck={false}
              ref={emailInputRef}
              value={email}
              onChange={(event) => setEmail(event.target.value)}
              required
            />
          </div>
          <div className="field">
            <label htmlFor="password">{t("password")}</label>
            <div className="password-field">
              <input
                id="password"
                name="password"
                type={showPassword ? "text" : "password"}
                autoComplete={mode === "signup" ? "new-password" : "current-password"}
                value={password}
                onChange={(event) => setPassword(event.target.value)}
                required
                minLength={8}
              />
              <button
                type="button"
                className="password-toggle"
                onClick={() => setShowPassword((prev) => !prev)}
                aria-label={showPassword ? t("hidePassword") : t("showPassword")}
                aria-pressed={showPassword}
              >
                {showPassword ? t("hide") : t("show")}
              </button>
            </div>
            {mode === "signup" ? <PasswordStrengthMeter strength={passwordStrength} /> : null}
          </div>

          {mode === "signup" ? (
            <>
              <div className="field">
                <label htmlFor="dateOfBirth">{t("dateOfBirth")}</label>
                <input
                  id="dateOfBirth"
                  name="bday"
                  type="date"
                  autoComplete="bday"
                  value={dateOfBirth}
                  onChange={(event) => setDateOfBirth(event.target.value)}
                  required
                />
              </div>

              <div className="field auth-consent-field">
                <label className="auth-consent-row" htmlFor="acceptTerms">
                  <input
                    id="acceptTerms"
                    name="acceptTerms"
                    type="checkbox"
                    checked={acceptedTerms}
                    onChange={(event) => setAcceptedTerms(event.target.checked)}
                    required
                  />
                  <span>
                    {TERMS_CONSENT_LEAD}{" "}
                    <Link href={TERMS_HREF} className="auth-text-link" target="_blank">
                      {TERMS_LINK_LABEL}
                    </Link>
                    .
                  </span>
                </label>
              </div>

              {/* Kept as its own affirmative tick, never folded into the Terms:
                  UK GDPR Art. 9(2)(a) consent has to be specific and separate,
                  and a bundled tick would not be valid consent at all. It is
                  also optional — see signupConsentBlockReason. */}
              <div className="field auth-consent-field">
                <label className="auth-consent-row" htmlFor="healthDataConsent">
                  <input
                    id="healthDataConsent"
                    name="healthDataConsent"
                    type="checkbox"
                    checked={healthDataConsent}
                    onChange={(event) => setHealthDataConsent(event.target.checked)}
                    aria-describedby="healthDataConsentHelp"
                  />
                  <span>{consentCopy.signupHealthConsentLabel}</span>
                </label>
                {/* The full explanation — what each category is used for, that
                    it is never shown to other users, what declining costs —
                    lives in the Privacy Notice linked here and in Settings →
                    Privacy. Repeating it inline buried the form on a phone. */}
                <p id="healthDataConsentHelp" className="muted auth-consent-help auth-consent-meta">
                  {consentCopy.signupHealthConsentHelp} ·{" "}
                  <Link href={PRIVACY_HREF} className="auth-text-link" target="_blank">
                    {t("privacyNotice")}
                  </Link>
                </p>
              </div>
            </>
          ) : null}

          <TurnstileChallenge
            action={mode}
            onTokenChange={setCaptchaToken}
            onUnavailable={handleCaptchaUnavailable}
            resetKey={captchaResetKey}
          />
          {isCaptchaBlocked && captchaHintDue ? (
            <p id="captchaHint" className="muted auth-captcha-hint" role="status">
              {t("captchaHint")}
            </p>
          ) : null}

          <div className="form-actions auth-form-actions">
            <button
              type="submit"
              className="cta"
              aria-describedby={isCaptchaBlocked && captchaHintDue ? "captchaHint" : undefined}
              disabled={
                isPending || isSignupPasswordBlocked || isSignupConsentBlocked || isCaptchaBlocked
              }
            >
              {isPending
                ? mode === "signup"
                  ? t("creatingAccount")
                  : t("signingIn")
                : mode === "signup"
                  ? t("createAccount")
                  : t("login")}
            </button>
            <button
              type="button"
              className="auth-text-link auth-magic-link-action"
              onClick={handleMagicLink}
              disabled={isPending || isMagicLinkPending || isCaptchaBlocked}
            >
              {isMagicLinkPending ? t("sendingLink") : t("emailLink")}
            </button>
            <div className="auth-secondary-links" aria-label={t("accountHelp")}>
              <Link href={mode === "signup" ? "/login" : "/signup"} className="auth-text-link">
                {mode === "signup" ? t("alreadyAccount") : t("joinBeta")}
              </Link>
              {mode === "login" ? (
                <Link href="/forgot-password" className="auth-text-link">
                  {t("forgotPassword")}
                </Link>
              ) : null}
            </div>
          </div>
        </form>

        {footerSlot}
      </div>

      <div className="auth-rail">
        <div className="hero-panel-copy">
          <p className="eyebrow">{mode === "signup" ? t("privateBeta") : t("athleteAccess")}</p>
          <h1>{mode === "signup" ? t("signupTitle") : t("loginTitle")}</h1>
          {mode === "signup" ? (
            <p>{t("signupSummary")}</p>
          ) : null}
        </div>
        {mode === "signup" ? (
          <div className="auth-signup-proof">
            <p className="kicker">{t("whatYouGet")}</p>
            <ul className="summary-list">
              <li>{t("benefit1")}</li>
              <li>{t("benefit2")}</li>
              <li>{t("benefit3")}</li>
            </ul>
            <p className="muted auth-signup-note">{t("noPayment")}</p>
          </div>
        ) : null}
      </div>
    </section>
  );
}

web/components/auth-guard.tsx:
"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";

import { useAppSession } from "@/components/auth-provider";

function LoadingCard({ label }: { label: string }) {
  return (
    <section className="panel loading-card">
      <p className="kicker">Loading</p>
      <h1>{label}</h1>
      <p className="muted">We are checking your session and restoring the correct athlete workspace.</p>
    </section>
  );
}

function ConnectionLostBanner({
  isRetrying,
  onRetry,
}: {
  isRetrying: boolean;
  onRetry: () => void;
}) {
  return (
    <div className="connection-lost-banner" role="status" aria-live="polite">
      <span className="connection-lost-dot" aria-hidden="true" />
      <span className="connection-lost-text">
        {isRetrying ? "Reconnecting…" : "No internet connection"}
      </span>
      <button
        type="button"
        className="connection-lost-retry"
        onClick={onRetry}
        disabled={isRetrying}
      >
        {isRetrying ? "Retrying…" : "Retry"}
      </button>
    </div>
  );
}

export function RequireAuth({
  children,
  adminOnly = false,
}: Readonly<{ children: React.ReactNode; adminOnly?: boolean }>) {
  const router = useRouter();
  const { isReady, isMeHydrated, hasTransientMeError, isAccessPending, session, me, refreshMe, signOut } = useAppSession();
  const [isRetryingRecovery, setIsRetryingRecovery] = useState(false);
  const role = me?.profile.role;

  useEffect(() => {
    if (!isReady) {
      return;
    }
    if (!session) {
      router.replace("/login");
      return;
    }
    if (adminOnly && !isMeHydrated) {
      return;
    }
    if (isMeHydrated && !me && !isAccessPending) {
      router.replace("/login");
      return;
    }
    if (adminOnly && role && role !== "admin") {
      router.replace("/plans");
    }
  }, [adminOnly, hasTransientMeError, isAccessPending, isMeHydrated, isReady, me, role, router, session]);

  useEffect(() => {
    if (!hasTransientMeError) {
      setIsRetryingRecovery(false);
    }
  }, [hasTransientMeError]);

  async function handleRetryRecovery() {
    if (isRetryingRecovery) {
      return;
    }
    setIsRetryingRecovery(true);
    try {
      await refreshMe();
    } finally {
      setIsRetryingRecovery(false);
    }
  }

  // The connection banner is a small, persistent overlay shown on every guarded
  // page (admin and athlete alike) whenever profile access could not be reached.
  // It reads as a plain "no internet" indicator rather than an app-specific
  // failure, and the provider keeps auto-retrying in the background.
  const connectionBanner =
    isReady && session && hasTransientMeError ? (
      <ConnectionLostBanner
        isRetrying={isRetryingRecovery}
        onRetry={() => void handleRetryRecovery()}
      />
    ) : null;

  let body: React.ReactNode;
  if (!isReady) {
    body = <LoadingCard label="Checking your access" />;
  } else if (!session) {
    body = <LoadingCard label="Redirecting to login" />;
  } else if (isAccessPending) {
    body = (
      <section className="panel loading-card">
        <p className="kicker">Access pending</p>
        <h1>Your account is in the approval queue.</h1>
        <p className="muted">An UNLXCK admin must approve your account before you can enter the app.</p>
        <button type="button" className="ghost-button" onClick={() => void signOut()}>
          Sign out
        </button>
      </section>
    );
  } else if (adminOnly && hasTransientMeError && !me) {
    body = <LoadingCard label="Restoring admin access" />;
  } else if (adminOnly && !isMeHydrated) {
    body = <LoadingCard label="Restoring admin access" />;
  } else if (isMeHydrated && !me) {
    body = <LoadingCard label="Redirecting to login" />;
  } else if (adminOnly && role !== "admin") {
    body = <LoadingCard label="Redirecting to your athlete view" />;
  } else {
    body = children;
  }

  return (
    <>
      {connectionBanner}
      {body}
    </>
  );
}

web/components/auth-provider.tsx:
"use client";

import { createContext, useCallback, useContext, useEffect, useRef, useState, type Dispatch, type ReactNode, type SetStateAction } from "react";

import { ApiError, getMe } from "@/lib/api";
import { getSupabaseBrowserClient } from "@/lib/supabase";
import { APPEARANCE_STORAGE_KEY, type AppearanceMode, type MeResponse } from "@/lib/types";

const ME_RETRY_ATTEMPTS = 3;
const ME_RETRY_DELAY_MS = 1_200;

async function sleep(ms: number): Promise<void> {
  await new Promise((resolve) => globalThis.setTimeout(resolve, ms));
}

type AppSession = {
  access_token: string;
  email?: string | null;
  user_id?: string | null;
};

type LoadMe = (
  nextSession: AppSession | null,
  options?: { allowRefresh?: boolean; force?: boolean },
) => Promise<void>;


type AppSessionValue = {
  isReady: boolean;
  isMeHydrated: boolean;
  hasTransientMeError: boolean;
  isAccessPending?: boolean;
  session: AppSession | null;
  me: MeResponse | null;
  previewAppearanceMode: Dispatch<SetStateAction<AppearanceMode | null>>;
  refreshMe: () => Promise<void>;
  replaceMe: (nextMe: MeResponse | null) => void;
  signOut: () => Promise<void>;
};

// Exported so component tests can mount a subtree that consumes the session
// without standing up the whole auth provider (and its network calls).
export const AppSessionContext = createContext<AppSessionValue | undefined>(undefined);

function applyAppearanceMode(mode: AppearanceMode) {
  if (typeof document === "undefined") {
    return;
  }
  document.documentElement.dataset.theme = mode;
  document.documentElement.style.colorScheme = mode;
  // Persist so the pre-paint script in the document head can restore this theme
  // on the next load before React hydrates — otherwise a light-theme user sees a
  // black flash while the dark SSR default is swapped out.
  try {
    window.localStorage.setItem(APPEARANCE_STORAGE_KEY, mode);
  } catch {
    // Ignore storage failures (private mode, disabled storage) — the theme still
    // applies for this session; only the next-load flash prevention is lost.
  }
}

export function AuthProvider({ children }: Readonly<{ children: ReactNode }>) {
  const [isReady, setIsReady] = useState(false);
  const [isMeHydrated, setIsMeHydrated] = useState(false);
  const [session, setSession] = useState<AppSession | null>(null);
  const [me, setMe] = useState<MeResponse | null>(null);
  const [hasTransientMeError, setHasTransientMeError] = useState(false);
  const [isAccessPending, setIsAccessPending] = useState(false);
  const [appearancePreview, setAppearancePreview] = useState<AppearanceMode | null>(null);
  const handledAccessTokenRef = useRef<string | null>(null);
  const hydratedAccessTokenRef = useRef<string | null>(null);
  const loadGenerationRef = useRef(0);
  const retryTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const latestMeRef = useRef<MeResponse | null>(me);
  const loadMeRef = useRef<LoadMe | null>(null);

  useEffect(() => {
    latestMeRef.current = me;
  }, [me]);

  const clearRetryTimer = useCallback(() => {
    if (retryTimerRef.current !== null) {
      clearTimeout(retryTimerRef.current);
      retryTimerRef.current = null;
    }
  }, []);

  useEffect(() => {
    return () => {
      clearRetryTimer();
    };
  }, [clearRetryTimer]);

  const loadMe = useCallback<LoadMe>(async (nextSession, options = {}) => {
    const allowRefresh = options.allowRefresh ?? true;
    const force = options.force ?? false;
    const currentLoadId = loadGenerationRef.current + 1;
    loadGenerationRef.current = currentLoadId;
    let shouldHoldHydration = false;

    if (!nextSession?.access_token) {
      if (loadGenerationRef.current === currentLoadId) {
        clearRetryTimer();
        setHasTransientMeError(false);
        setIsAccessPending(false);
        setAppearancePreview(null);
        setMe(null);
        hydratedAccessTokenRef.current = null;
        setIsMeHydrated(true);
        setIsReady(true);
      }
      return;
    }

    setSession(nextSession);
    setIsReady(true);

    if (!force && hydratedAccessTokenRef.current === nextSession.access_token && latestMeRef.current) {
      setIsMeHydrated(true);
      return;
    }

    if (hydratedAccessTokenRef.current !== nextSession.access_token) {
      setMe(null);
    }
    setIsMeHydrated(false);

    try {
      let nextMe: MeResponse | null = null;
      let lastError: unknown = null;

      for (let attempt = 1; attempt <= ME_RETRY_ATTEMPTS; attempt += 1) {
        try {
          nextMe = await getMe(nextSession.access_token);
          break;
        } catch (err) {
          lastError = err;
          if (
            err instanceof ApiError &&
            (err.status === 401 || err.code === "account_pending_approval")
          ) {
            throw err;
          }
          if (attempt < ME_RETRY_ATTEMPTS) {
            await sleep(ME_RETRY_DELAY_MS * attempt);
          }
        }
      }

      if (nextMe === null && lastError) {
        throw lastError;
      }
      if (loadGenerationRef.current !== currentLoadId) {
        return;
      }
      clearRetryTimer();
      setHasTransientMeError(false);
      setIsAccessPending(false);
      setMe(nextMe);
      hydratedAccessTokenRef.current = nextSession.access_token;
      setSession(nextSession);
    } catch (err) {
      if (loadGenerationRef.current !== currentLoadId) {
        return;
      }

      if (err instanceof ApiError && err.status === 403 && err.code === "account_pending_approval") {
        clearRetryTimer();
        setHasTransientMeError(false);
        setIsAccessPending(true);
        setMe(null);
        hydratedAccessTokenRef.current = nextSession.access_token;
        return;
      }

      if (err instanceof ApiError && err.status === 401 && allowRefresh) {
        try {
          const client = getSupabaseBrowserClient();
          const refreshResult = await client.auth.refreshSession();
          const refreshedAccessToken = refreshResult.data.session?.access_token ?? null;
          if (refreshedAccessToken) {
            const refreshedSession = {
              access_token: refreshedAccessToken,
              email: refreshResult.data.session?.user.email ?? nextSession.email ?? null,
              user_id: refreshResult.data.session?.user.id ?? nextSession.user_id ?? null,
            };
            handledAccessTokenRef.current = refreshedAccessToken;
            await loadMeRef.current?.(refreshedSession, { allowRefresh: false, force });
            return;
          }
        } catch {
          // Treat refresh failures as a genuine session expiry below only when no session remains.
        }

        try {
          const client = getSupabaseBrowserClient();
          const currentSession = await client.auth.getSession();
          const liveAccessToken = currentSession.data.session?.access_token ?? null;
          if (liveAccessToken) {
            const liveSession = {
              access_token: liveAccessToken,
              email: currentSession.data.session?.user.email ?? nextSession.email ?? null,
              user_id: currentSession.data.session?.user.id ?? nextSession.user_id ?? null,
            };
            setHasTransientMeError(true);
            setIsMeHydrated(false);
            shouldHoldHydration = true;
            setSession(liveSession);
            clearRetryTimer();
            retryTimerRef.current = setTimeout(() => {
              retryTimerRef.current = null;
              void loadMeRef.current?.(liveSession, { allowRefresh: false, force });
            }, ME_RETRY_DELAY_MS);
            return;
          }
        } catch {
          // If we cannot confirm auth state, keep the current session and retry later.
          setHasTransientMeError(true);
          setIsMeHydrated(false);
          shouldHoldHydration = true;
          clearRetryTimer();
          retryTimerRef.current = setTimeout(() => {
            retryTimerRef.current = null;
            void loadMeRef.current?.(nextSession, { allowRefresh: false, force });
          }, ME_RETRY_DELAY_MS);
          return;
        }
      }

      if (err instanceof ApiError && err.status === 401) {
        clearRetryTimer();
        setHasTransientMeError(false);
        setIsAccessPending(false);
        setAppearancePreview(null);
        setSession(null);
        setMe(null);
        hydratedAccessTokenRef.current = null;
        return;
      }

      setHasTransientMeError(true);
      setIsMeHydrated(false);
      shouldHoldHydration = true;
      clearRetryTimer();
      retryTimerRef.current = setTimeout(() => {
        retryTimerRef.current = null;
        void loadMeRef.current?.(nextSession, { allowRefresh: false, force });
      }, ME_RETRY_DELAY_MS);
    } finally {
      if (loadGenerationRef.current === currentLoadId) {
        setIsReady(true);
        if (!shouldHoldHydration) {
          setIsMeHydrated(true);
        }
      }
    }
  }, [clearRetryTimer]);
  useEffect(() => {
    loadMeRef.current = loadMe;
  }, [loadMe]);

  useEffect(() => {
    let active = true;
    let subscription: { unsubscribe: () => void } | null = null;

    let client;
    try {
      client = getSupabaseBrowserClient();
    } catch {
      setIsReady(true);
      setIsMeHydrated(true);
      return () => {
        active = false;
      };
    }

    client.auth
      .getSession()
      .then(({ data }) => {
        if (!active) {
          return;
        }
        const nextSession = data.session
          ? {
              access_token: data.session.access_token,
              email: data.session.user.email ?? null,
              user_id: data.session.user.id ?? null,
            }
          : null;
        handledAccessTokenRef.current = nextSession?.access_token ?? null;
        setSession(nextSession);
        void loadMe(nextSession);
      })
      .catch(async () => {
        if (!active) {
          return;
        }
        try {
          await client.auth.signOut();
        } catch {
          // Ignore cleanup failures after a stale browser auth session.
        }
        handledAccessTokenRef.current = null;
        clearRetryTimer();
        setHasTransientMeError(false);
        setIsAccessPending(false);
        setAppearancePreview(null);
        setSession(null);
        setMe(null);
        hydratedAccessTokenRef.current = null;
        setIsMeHydrated(true);
        setIsReady(true);
      });

    const authState = client.auth.onAuthStateChange((_event, nextSession) => {
      if (!active) {
        return;
      }
      const mappedSession = nextSession
        ? {
            access_token: nextSession.access_token,
            email: nextSession.user.email ?? null,
            user_id: nextSession.user.id ?? null,
          }
        : null;
      const nextToken = mappedSession?.access_token ?? null;
      if (handledAccessTokenRef.current === nextToken) {
        return;
      }
      handledAccessTokenRef.current = nextToken;
      setSession(mappedSession);
      void loadMe(mappedSession);
    });
    subscription = authState.data.subscription;

    return () => {
      active = false;
      subscription?.unsubscribe();
    };
  }, [clearRetryTimer, loadMe]);

  useEffect(() => {
    if (!isReady) {
      return;
    }
    if (appearancePreview) {
      applyAppearanceMode(appearancePreview);
      return;
    }
    // An authenticated session can be ready before /me (and its appearance_mode)
    // has loaded. Forcing "dark" here would overwrite the theme the pre-paint
    // script already restored from localStorage and cause a flash, so hold the
    // current theme until the profile arrives.
    if (session && !me) {
      return;
    }
    applyAppearanceMode(session && me?.profile.appearance_mode === "light" ? "light" : "dark");
  }, [appearancePreview, isReady, session, me]);

  async function refreshMe() {
    await loadMe(session, { force: true });
  }

  function replaceMe(nextMe: MeResponse | null) {
    setMe(nextMe);
    hydratedAccessTokenRef.current = nextMe && session?.access_token ? session.access_token : null;
    setIsMeHydrated(true);
  }

  async function signOut() {
    try {
      await getSupabaseBrowserClient().auth.signOut();
    } catch {
      // Ignore missing client during sign-out cleanup.
    }
    handledAccessTokenRef.current = null;
    hydratedAccessTokenRef.current = null;
    clearRetryTimer();
    setHasTransientMeError(false);
    setIsAccessPending(false);
    setAppearancePreview(null);
    setSession(null);
    setMe(null);
    setIsReady(true);
    setIsMeHydrated(true);
    applyAppearanceMode("dark");
  }

  return (
    <AppSessionContext.Provider
      value={{
        isReady,
        isMeHydrated,
        hasTransientMeError,
        isAccessPending,
        session,
        me,
        previewAppearanceMode: setAppearancePreview,
        refreshMe,
        replaceMe,
        signOut,
      }}
    >
      {children}
    </AppSessionContext.Provider>
  );
}

export function useAppSession() {
  const context = useContext(AppSessionContext);
  if (!context) {
    throw new Error("useAppSession must be used within AuthProvider.");
  }
  return context;
}

web/components/compliance-gate-screen.ts:
"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useEffect, useId, useState } from "react";

import { RequireAuth } from "@/components/auth-guard";
import { useAppSession } from "@/components/auth-provider";
import { recordCompliance } from "@/lib/api";
import { getAuthenticatedLandingHref } from "@/lib/auth-routing";
import {
  hasHealthDataConsent,
  requiresComplianceAcceptance,
  validateDateOfBirth,
} from "@/lib/compliance";

/**
 * The consent step for an account that does not already have one on record.
 *
 * A signup completed through the current form arrives here already satisfied and
 * passes straight through. It exists for the accounts that predate the consent
 * fields, and for a session that lost its acceptance mid-signup — those athletes
 * would otherwise be stuck against a 403 from the onboarding gate with no way to
 * clear it.
 *
 * Deliberately shaped like the private-trial gate it sits next to: same profile-
 * backed marker, same "redirect once satisfied" fail-safe.
 */
function ComplianceAcceptance() {
  const router = useRouter();
  const { me, session, refreshMe } = useAppSession();
  const headingId = useId();
  const [dateOfBirth, setDateOfBirth] = useState("");
  const [acceptedTerms, setAcceptedTerms] = useState(false);
  const [healthDataConsent, setHealthDataConsent] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const token = session?.access_token ?? "";
  const role = me?.profile.role;
  const needsDateOfBirth = !me?.profile.date_of_birth || !me?.profile.meets_minimum_age;
  const needsTerms = !me?.profile.terms_accepted;
  const needsHealthConsent = !hasHealthDataConsent(me);
  const isPending = requiresComplianceAcceptance(me);
  const dateOfBirthError = needsDateOfBirth ? validateDateOfBirth(dateOfBirth) : null;
  const canContinue =
    !isSubmitting &&
    !dateOfBirthError &&
    (!needsTerms || acceptedTerms);

  // A non-athlete has no onboarding to gate; send them to their own workspace
  // rather than stranding them on a screen whose only action does not apply.
  useEffect(() => {
    if (role && role !== "athlete") {
      router.replace("/");
    }
  }, [role, router]);

  // Once the durable profile markers exist this route must never gate again —
  // protecting against stale links, bookmarks and a double submit.
  useEffect(() => {
    if (role === "athlete" && !isPending && !needsHealthConsent) {
      router.replace(getAuthenticatedLandingHref(me));
    }
  }, [isPending, me, needsHealthConsent, role, router]);

  async function submit() {
    if (isSubmitting) {
      return;
    }
    if (dateOfBirthError) {
      setError(dateOfBirthError);
      return;
    }
    if (needsTerms && !acceptedTerms) {
      setError("Accept the Terms of Use to continue.");
      return;
    }
    setIsSubmitting(true);
    setError(null);
    try {
      await recordCompliance(token, {
        ...(needsDateOfBirth ? { date_of_birth: dateOfBirth } : {}),
        ...(needsTerms ? { accept_terms: acceptedTerms } : {}),
        // Only sent when ticked. Leaving it unticked must not be recorded as a
        // withdrawal — the athlete has not consented yet, which is a different
        // fact from having consented and changed their mind.
        ...(needsHealthConsent && healthDataConsent ? { health_data_consent: true } : {}),
      });
      await refreshMe();
      router.replace("/onboarding");
    } catch (submitError) {
      setError(
        submitError instanceof Error
          ? submitError.message
          : "Your details could not be saved. Try again.",
      );
      setIsSubmitting(false);
    }
  }

  return (
    <section className="panel private-trial-panel" aria-labelledby={headingId}>
      <p className="kicker">Before you start</p>
      <h1 id={headingId}>Athlete Profile Verification</h1>
      <p className="muted">
        Set your baseline to unlock personalized camp programming and safety protocols.
      </p>

      {error ? (
        <p className="error-banner" role="alert">
          {error}
        </p>
      ) : null}

      {needsDateOfBirth ? (
        <div className="field">
          <label htmlFor="complianceDateOfBirth">Date of birth</label>
          <input
            id="complianceDateOfBirth"
            type="date"
            autoComplete="bday"
            value={dateOfBirth}
            onChange={(event) => setDateOfBirth(event.target.value)}
            required
          />
        </div>
      ) : null}

      {needsTerms ? (
        <div className="field auth-consent-field">
          <label className="auth-consent-row" htmlFor="complianceTerms">
            <input
              id="complianceTerms"
              type="checkbox"
              checked={acceptedTerms}
              onChange={(event) => setAcceptedTerms(event.target.checked)}
            />
            <span>
              I accept the{" "}
              <Link href="/terms" className="auth-text-link" target="_blank">
                Terms of Use
              </Link>
              .
            </span>
          </label>
          <div className="auth-consent-help">
            <Link href="/privacy" className="auth-text-link" target="_blank">
              Privacy Notice
            </Link>
          </div>
        </div>
      ) : null}

      {needsHealthConsent ? (
        <div className="field auth-consent-field">
          <label className="auth-consent-row" htmlFor="complianceHealthConsent">
            <input
              id="complianceHealthConsent"
              type="checkbox"
              checked={healthDataConsent}
              onChange={(event) => setHealthDataConsent(event.target.checked)}
            />
            <span>Allow UNLXCK to process health and recovery metrics to adapt my camp.</span>
          </label>
        </div>
      ) : null}

      <div className="private-trial-actions">
        <button type="button" className="cta" onClick={() => void submit()} disabled={!canContinue}>
          {isSubmitting ? "Saving…" : "CONTINUE"}
        </button>
      </div>
    </section>
  );
}

export function ComplianceGateScreen() {
  return (
    <RequireAuth>
      <ComplianceAcceptance />
    </RequireAuth>
  );
}

web/components/compliance-guard.tsx:
"use client";

import { useRouter } from "next/navigation";
import { useEffect } from "react";

import { useAppSession } from "@/components/auth-provider";
import { requiresComplianceAcceptance } from "@/lib/compliance";

/**
 * Keeps the intake routes behind age and Terms acceptance.
 *
 * The backend already refuses to save an onboarding draft without them, so this
 * is not the control — it is what turns that refusal into a screen the athlete
 * can act on instead of an error banner. Mirrors RequirePrivateTrialAck, and
 * runs outside it so the Terms are settled before the trial briefing.
 */
export function RequireComplianceAcceptance({ children }: Readonly<{ children: React.ReactNode }>) {
  const router = useRouter();
  const { isMeHydrated, me } = useAppSession();
  // An unhydrated `me` is "not known yet", not "not accepted" — redirecting on
  // it would bounce every athlete through the gate on every cold load.
  const mustAccept = isMeHydrated && requiresComplianceAcceptance(me);

  useEffect(() => {
    if (mustAccept) {
      router.replace("/consent");
    }
  }, [mustAccept, router]);

  return <>{children}</>;
}

web/components/exercise-demo.tsx:
"use client";

import {
  createContext,
  useContext,
  useEffect,
  useRef,
  useState,
  useSyncExternalStore,
  type ReactNode,
} from "react";

import {
  YOUTUBE_NOCOOKIE_HOST,
  demoFullVideoUrl,
  demoSegmentLabel,
  demoThumbnailUrl,
  hasWatchedDemo,
  loadYouTubeIframeApi,
  markDemoWatched,
  subscribeDemoWatched,
  type YouTubePlayer,
} from "@/lib/exercise-demo";
import type { ExerciseMedia } from "@/lib/types";

// ---------------------------------------------------------------------------
// Plan-level media map, relayed to the exercise rows like the rehab label
// policy: Plan Detail mounts it through StructuredPlanRenderer, Today mounts it
// around its standalone SessionCards.
// ---------------------------------------------------------------------------

const ExerciseMediaContext = createContext<Record<string, ExerciseMedia> | null>(null);

export function ExerciseMediaProvider({
  media,
  children,
}: {
  media?: Record<string, ExerciseMedia> | null;
  children: ReactNode;
}) {
  return <ExerciseMediaContext.Provider value={media ?? null}>{children}</ExerciseMediaContext.Provider>;
}

/** Response-map prefix for blocks resolved on canonical identity (server: EXERCISE_KEY_MEDIA_PREFIX). */
export const EXERCISE_KEY_MEDIA_PREFIX = "exercise:";

/**
 * The block's demo. A block with a canonical `exercise_key` resolves on that
 * identity only, so rewording its display name never loses or swaps its video;
 * a legacy block without one falls back to its display name.
 */
export function useExerciseMedia(
  displayName: string | null | undefined,
  exerciseKey?: string | null,
): ExerciseMedia | null {
  const map = useContext(ExerciseMediaContext);
  if (!map) return null;
  const key = exerciseKey?.trim();
  const media = key ? map[`${EXERCISE_KEY_MEDIA_PREFIX}${key}`] : displayName ? map[displayName] : undefined;
  return media && typeof media.video_id === "string" && media.video_id ? media : null;
}

// ---------------------------------------------------------------------------
// Demo player
// ---------------------------------------------------------------------------

type DemoMode = "facade" | "loading" | "playing" | "paused" | "error";

/** How often the loop guard checks the playhead against the segment end. */
const LOOP_POLL_MS = 250;

export function ExerciseDemo({
  media,
  exerciseName,
  leadCue,
  onLeadCuePinnedChange,
}: {
  media: ExerciseMedia;
  exerciseName: string;
  /** First coaching cue, pinned under the video while the demo leads the row. */
  leadCue?: string | null;
  /** Tells the row whether the lead cue is shown here, so the cue list below
   * does not print it twice. */
  onLeadCuePinnedChange?: (pinned: boolean) => void;
}) {
  const [mode, setMode] = useState<DemoMode>("facade");
  // Server snapshot is "not watched", so SSR and hydration agree; the client
  // then reads this device's memory.
  const watched = useSyncExternalStore(
    subscribeDemoWatched,
    () => hasWatchedDemo(media.video_id),
    () => false,
  );
  const [slow, setSlow] = useState(false);
  const [muted, setMuted] = useState(true);
  const [thumbFailed, setThumbFailed] = useState(false);
  // iPhone Safari cannot fullscreen an iframe, so the control only shows
  // where the browser supports it.
  const [canFullscreen] = useState(
    () => typeof document !== "undefined" && document.fullscreenEnabled === true,
  );
  const mountRef = useRef<HTMLDivElement | null>(null);
  const playerRef = useRef<YouTubePlayer | null>(null);
  const loopTimerRef = useRef<number | null>(null);
  // PLAYING fires again on every loop restart; record the watch once.
  const watchRecordedRef = useRef(false);

  const start = Math.max(0, Math.floor(media.start_s || 0));
  const end = media.end_s != null && media.end_s > start ? Math.floor(media.end_s) : null;
  const segment = demoSegmentLabel(media);
  const isCoach = media.source === "coach";
  const channel = media.channel_title?.trim() || null;
  // Only an explicit "portrait" changes the frame: null, undefined and
  // "landscape" all render the existing 16:9 layout untouched.
  const portrait = media.orientation === "portrait";
  const playerActive = mode === "loading" || mode === "playing" || mode === "paused";
  const compact = watched && mode === "facade";
  const pinLeadCue = Boolean(leadCue) && !compact && mode !== "error";

  useEffect(() => {
    onLeadCuePinnedChange?.(pinLeadCue);
  }, [onLeadCuePinnedChange, pinLeadCue]);

  useEffect(() => {
    if (!playerActive || playerRef.current || !mountRef.current) return;
    let cancelled = false;
    const host = mountRef.current;

    loadYouTubeIframeApi()
      .then((YT) => {
        if (cancelled) return;
        const target = document.createElement("div");
        host.replaceChildren(target);
        playerRef.current = new YT.Player(target, {
          host: YOUTUBE_NOCOOKIE_HOST,
          videoId: media.video_id,
          width: "100%",
          height: "100%",
          playerVars: {
            autoplay: 1,
            // Muted so autoplay after the tap is allowed on iOS; the athlete
            // can turn sound on for coach demos that talk through the rep.
            mute: 1,
            playsinline: 1,
            controls: 0,
            // Keyboard shortcuts and fullscreen stay enabled; only the control
            // bar is swapped for the row's own controls below the frame.
            fs: 1,
            rel: 0,
            iv_load_policy: 3,
            start,
            ...(end != null ? { end } : {}),
          },
          events: {
            onReady: (event) => {
              if (cancelled) return;
              event.target.playVideo();
            },
            onStateChange: (event) => {
              if (cancelled) return;
              if (event.data === YT.PlayerState.PLAYING) {
                setMode("playing");
                if (!watchRecordedRef.current) {
                  watchRecordedRef.current = true;
                  markDemoWatched(media.video_id);
                }
              } else if (event.data === YT.PlayerState.PAUSED) {
                setMode("paused");
              } else if (event.data === YT.PlayerState.ENDED) {
                // Loop the segment rather than falling through to YouTube's
                // end screen of unrelated videos.
                event.target.seekTo(start, true);
                event.target.playVideo();
              }
            },
            onError: () => {
              if (cancelled) return;
              // The error state drops the frame, so release the player now
              // rather than when the row collapses.
              try {
                playerRef.current?.destroy();
              } catch {
                // Already torn down.
              }
              playerRef.current = null;
              setMode("error");
            },
          },
        });
      })
      .catch(() => {
        if (!cancelled) setMode("error");
      });

    return () => {
      cancelled = true;
    };
  }, [end, media.video_id, playerActive, start]);

  // Segment loop guard: `end` only fires ENDED on the first pass, and a seek
  // (Replay) can clear it, so the playhead is also checked while playing.
  useEffect(() => {
    if (mode !== "playing" || end == null) return;
    loopTimerRef.current = window.setInterval(() => {
      const player = playerRef.current;
      if (player && player.getCurrentTime() >= end - 0.15) {
        player.seekTo(start, true);
      }
    }, LOOP_POLL_MS);
    return () => {
      if (loopTimerRef.current != null) window.clearInterval(loopTimerRef.current);
      loopTimerRef.current = null;
    };
  }, [end, mode, start]);

  // Collapsing the row unmounts the demo: stop and release the player.
  useEffect(
    () => () => {
      try {
        playerRef.current?.destroy();
      } catch {
        // The frame may already be gone (error state removed it).
      }
      playerRef.current = null;
    },
    [],
  );

  const replay = () => {
    const player = playerRef.current;
    if (!player) return;
    player.seekTo(start, true);
    player.playVideo();
  };

  const togglePlay = () => {
    const player = playerRef.current;
    if (!player) return;
    if (mode === "playing") player.pauseVideo();
    else player.playVideo();
  };

  const toggleSlow = () => {
    const next = !slow;
    playerRef.current?.setPlaybackRate(next ? 0.5 : 1);
    setSlow(next);
  };

  const enterFullscreen = () => {
    const frame = mountRef.current?.querySelector("iframe");
    frame?.requestFullscreen?.().catch(() => {
      // Refused (no user activation, or the browser blocks it): stay inline.
    });
  };

  const toggleSound = () => {
    const player = playerRef.current;
    if (!player) return;
    if (muted) player.unMute();
    else player.mute();
    setMuted(!muted);
  };

  if (mode === "error") {
    return (
      <div className="ex-demo-unavailable" role="status">
        <span>Video unavailable here. Use the cues below.</span>
        <a href={demoFullVideoUrl(media)} target="_blank" rel="noopener noreferrer">
          Watch on YouTube
        </a>
      </div>
    );
  }

  if (compact) {
    return (
      <button
        type="button"
        className="ex-demo-replay-strip"
        onClick={() => setMode("loading")}
        aria-label={`Replay ${exerciseName} demo`}
      >
        <span className="ex-demo-replay-thumb" aria-hidden="true">
          {thumbFailed ? null : (
            // eslint-disable-next-line @next/next/no-img-element -- remote YouTube thumbnail, not a local asset
            <img src={demoThumbnailUrl(media.video_id, "mq")} alt="" loading="lazy" onError={() => setThumbFailed(true)} />
          )}
          <span className="ex-demo-play-glyph ex-demo-play-glyph-sm" />
        </span>
        <span className="ex-demo-replay-label">Replay demo</span>
        <span className="ex-demo-replay-meta">Watched</span>
      </button>
    );
  }

  return (
    <div className="ex-demo" data-mode={mode} data-orientation={portrait ? "portrait" : undefined}>
      <div className="ex-demo-frame">
        {playerActive ? (
          <div ref={mountRef} className="ex-demo-player" />
        ) : (
          <button
            type="button"
            className="ex-demo-facade"
            onClick={() => setMode("loading")}
            aria-label={`Play ${exerciseName} demo`}
          >
            {thumbFailed ? null : (
              // eslint-disable-next-line @next/next/no-img-element -- remote YouTube thumbnail, not a local asset
              <img
                src={demoThumbnailUrl(media.video_id)}
                alt=""
                loading="lazy"
                className="ex-demo-thumb"
                onError={() => setThumbFailed(true)}
              />
            )}
            <span className="ex-demo-play-glyph" aria-hidden="true" />
          </button>
        )}
      </div>

      {/* Nothing is drawn over the frame: labels and attribution sit under
          it, and the full video is one tap away before and during playback. */}
      <div className="ex-demo-caption">
        {isCoach ? <span className="ex-demo-badge">Coach demo</span> : null}
        <span className="ex-demo-meta">
          {["Demo", segment, channel].filter(Boolean).join(" · ")}
        </span>
        <a className="ex-demo-external" href={demoFullVideoUrl(media)} target="_blank" rel="noopener noreferrer">
          Watch on YouTube
        </a>
      </div>

      {playerActive ? (
        <div className="ex-demo-controls" role="group" aria-label="Demo controls">
          <button type="button" className="ex-demo-control" onClick={togglePlay} disabled={mode === "loading"}>
            {mode === "playing" ? "Pause" : "Play"}
          </button>
          <button type="button" className="ex-demo-control" onClick={replay} disabled={mode === "loading"}>
            Replay
          </button>
          <button
            type="button"
            className="ex-demo-control"
            onClick={toggleSlow}
            aria-pressed={slow}
            disabled={mode === "loading"}
          >
            0.5×
          </button>
