// Owns the full nutrition details. Deterministic Stage 1 macros/hydration/fuel
// timing win when present; the legacy prose fields are the fallback only. Never
// renders coach_gated (it is stripped server-side before reaching the frontend).
export function NutritionCard({
  plan,
  activePhaseKey = null,
  openOngoing = false,
}: {
  plan: StructuredPlan;
  /** Normalized phase key of the week the athlete is viewing. The matching
   * phase opens by default so a taper/SPP week does not land on expanded GPP. */
  activePhaseKey?: string | null;
  openOngoing?: boolean;
}) {
  const items = getNutritionPhaseItems(plan);
  if (items.length === 0 && !hasNutrition(plan)) {
    return null;
  }
  if (items.length === 0) {
    return (
      <section className="sp-card sp-nutrition">
        <p className="sp-eyebrow">Nutrition</p>
        <NutritionProse plan={plan} />
      </section>
    );
  }
  const openIndex = resolveActiveSupportPhaseIndex(items, activePhaseKey);
  const visibleItems = openOngoing ? items.slice(openIndex, openIndex + 1) : items;
  return (
    <div className="sp-phase-support-grid">
      {visibleItems.map((item, index) => (
        <NutritionPhaseCard
          key={item.phase}
          item={item}
          defaultOpen={openOngoing || index === openIndex}
          syncKey={activePhaseKey ?? ""}
          displayLabel={openOngoing ? "Current block" : undefined}
        />
      ))}
    </div>
  );
}

// Owns recovery detail (sleep / fatigue / phase focus / core actions). Renders
// deterministic Stage 1 recovery; never coach_gated. Stop/modify/report
// thresholds stay with RedFlagsCard, so this card does not repeat them.
export function RecoveryCard({
  plan,
  activePhaseKey = null,
  openOngoing = false,
}: {
  plan: StructuredPlan;
  activePhaseKey?: string | null;
  openOngoing?: boolean;
}) {
  const items = getRecoveryPhaseItems(plan);
  if (items.length === 0) {
    return null;
  }
  const openIndex = resolveActiveSupportPhaseIndex(items, activePhaseKey);
  const visibleItems = openOngoing ? items.slice(openIndex, openIndex + 1) : items;
  return (
    <div className="sp-phase-support-grid">
      {visibleItems.map((item, index) => (
        <RecoveryPhaseCard
          key={item.phase}
          item={item}
          defaultOpen={openOngoing || index === openIndex}
          syncKey={activePhaseKey ?? ""}
          displayLabel={openOngoing ? "Current block" : undefined}
        />
      ))}
    </div>
  );
}

/** Threshold at which the week rail switches from "share the width evenly" to
 * "hold a readable width and scroll". Up to this many weeks fit the strip
 * without scrolling; beyond it the rail shows ~this many per viewport. */
const WEEK_STRIP_FIT_LIMIT = 4;

/** Horizontal scroll offset that centres a week card within the rail, clamped so
 * the first cards never scroll past the start. Pure for direct testing — jsdom
 * reports zero element geometry, so the centring math is verified here rather
 * than through a rendered layout. */
export function weekStripCenterOffset(
  stripWidth: number,
  pillOffset: number,
  pillWidth: number,
): number {
  return Math.max(0, pillOffset - (stripWidth - pillWidth) / 2);
}

/** Progression rail of week cards used to pick the week. Up to four weeks share
 * the strip width evenly (no scroll); five or more hold a readable ~quarter
 * width and the rail scrolls with snap, auto-centring the active week. */
function WeekStrip({
  weeks,
  selectedPos,
  currentPos,
  onSelect,
  completionIndex,
  openOngoing,
}: {
  weeks: StructuredWeek[];
  selectedPos: number;
  currentPos: number | null;
  onSelect: (pos: number) => void;
  completionIndex?: CompletionIndex;
  openOngoing: boolean;
}) {
  const stripRef = useRef<HTMLElement>(null);
  const scrollable = weeks.length > WEEK_STRIP_FIT_LIMIT;
  // Centre on the week being viewed. `selectedPos` (the parent's `safePos`)
  // already defaults to the current week until the athlete picks another, so it
  // covers "land on now" on mount AND re-centres each manual selection — whereas
  // preferring `currentPos` would pin the target and never move when a different
  // week is tapped, leaving that card half cut off.
  const activePos = selectedPos;

  // Bring the active week into view when the rail scrolls. Adjusts only the
  // horizontal scroll of the strip itself (never scrollIntoView, which could
  // jump the whole page vertically). No-ops when the rail is not scrollable or
  // has no layout yet (SSR / jsdom report zero widths).
  useEffect(() => {
    const strip = stripRef.current;
    if (!strip || strip.scrollWidth <= strip.clientWidth) {
      return;
    }
    const pill = strip.querySelector<HTMLElement>(`[data-week-pos="${activePos}"]`);
    if (!pill) {
      return;
    }
    strip.scrollLeft = weekStripCenterOffset(strip.clientWidth, pill.offsetLeft, pill.clientWidth);
  }, [activePos, weeks.length]);

  return (
    <>
    <div className="cm-week-navigation">
      <p className="cm-week-navigation-label" aria-live="polite" aria-atomic="true">
        Week {selectedPos + 1} of {weeks.length}
      </p>
      {currentPos !== null && currentPos !== selectedPos ? (
        <button type="button" className="cm-current-week" onClick={() => onSelect(currentPos)}>
          Current week
        </button>
      ) : null}
    </div>
    <nav
      ref={stripRef}
      className="cm-week-strip"
      data-scroll={scrollable ? "true" : undefined}
      aria-label={openOngoing ? "Training block weeks" : "Camp weeks"}
    >
      {weeks.map((week, pos) => {
        // This compact fraction is a progress action: count the same app sessions
        // as the week overview, not coach-owned days that cannot be logged here.
        const completion = weekCompletion(week, completionIndex, { includeCoachLed: false });
        const phase = openOngoing
          ? OPEN_BLOCK_WEEK_LABELS[pos] || `Week ${pos + 1}`
          : resolvedWeekPhase(week);
        const index =
          typeof week.week_index === "number" && Number.isFinite(week.week_index)
            ? week.week_index
            : pos + 1;
        const selected = pos === selectedPos;
        const current = pos === currentPos;
        const phaseLabel = phase ? titleize(phase) : null;
        return (
          <button
            key={cleanText(week.week_id) || `week-${pos}`}
            type="button"
            data-week-pos={pos}
            className={`cm-week-pill${selected ? " cm-week-pill-selected" : ""}${
              current ? " cm-week-pill-current" : ""
            }`}
            aria-current={current ? "step" : undefined}
            aria-pressed={selected}
            onClick={() => onSelect(pos)}
          >
            <span className="cm-week-pill-head">
              <span className="cm-week-pill-index">W{index}</span>
              {current ? <span className="cm-week-pill-dot" aria-hidden="true" /> : null}
            </span>
            {phaseLabel ? (
              <span className="cm-week-pill-phase" title={phaseLabel}>
                {phaseLabel}
              </span>
            ) : null}
            {completion.total > 0 ? (
              <span
                className="cm-week-pill-completion"
                title="App sessions completed. Coach/gym days are tracked separately."
              >
                {completion.done}/{completion.total} app
                <span className="sr-only"> sessions completed. Coach/gym days are tracked separately.</span>
              </span>
            ) : null}
            {current ? <span className="sr-only">Current week</span> : null}
          </button>
        );
      })}
    </nav>
    </>
  );
}

/** The selected week's countdown/dates, work sources and app completion.
 *  The week goal is already shown in the heading via weekLabel, and the phase is
 *  already visible in the week pill, so this overview avoids repeating it. */
function WeekOverview({
  week,
  weekNumber,
  completionIndex,
  openOngoing,
  scheduleContext,
}: {
  week: StructuredWeek;
  /** 1-based position of the viewed week; drives the open-plan week intent. */
  weekNumber: number;
  completionIndex?: CompletionIndex;
  openOngoing: boolean;
  scheduleContext?: PlanScheduleContext | null;
}) {
  // "App completed" promises app work: a coach-owned combat day carries no app
  // card, so it is reported by the Coach/gym counter, not by this fraction.
  const completion = weekCompletion(week, completionIndex, { includeCoachLed: false });
  const sessionSummary = weekSessionSummary(week);
  const countdownStart = formatCountdownLabel(week.countdown_start);
  const countdownEnd = formatCountdownLabel(week.countdown_end);
  const countdownRange =
    countdownStart && countdownEnd
      ? `${countdownStart} → ${countdownEnd}`
      : countdownStart || countdownEnd;
  const startDate = cleanText(week.start_date);
  const endDate = cleanText(week.end_date);
  const dateRange =
    startDate && endDate
      ? formatAppDateRange(startDate, endDate)
      : startDate || endDate
        ? formatAppDate(startDate || endDate)
        : null;

  const rows = [
    { label: "Countdown", value: countdownRange },
    { label: "Dates", value: dateRange, wide: true },
    {
      label: "App sessions",
      value: sessionSummary.appSessions > 0 ? `${sessionSummary.appSessions}` : null,
    },
    {
      label: "Support cards",
      value: sessionSummary.supportSessions > 0 ? `${sessionSummary.supportSessions}` : null,
    },
    {
      label: "Coach/gym days",
      value: sessionSummary.coachLedSessions > 0 ? `${sessionSummary.coachLedSessions}` : null,
    },
    {
      label: "App completed",
      value: completion.total > 0 ? `${completion.done}/${completion.total}` : null,
      wideMobile: true,
    },
  ].filter((row) => Boolean(row.value));
  const baseHeading = weekLabel(week);
  const openWeekNumber = resolveFiniteWeekNumber(
    week.week_index,
    scheduleContext?.current_week_number,
  );
  const openWeekHeading = baseHeading.replace(
    /^Week(?:\s+\d+)?/i,
    `Week ${openWeekNumber} of 4`,
  );
  const heading = openOngoing
    ? `Block ${scheduleContext?.block_number ?? 1} · ${openWeekHeading}`
    : `Week ${weekNumber}`;
  const weekIntent = openOngoing ? openBlockWeekIntent(weekNumber) : null;
  // The pill only names the phase (GPP / SPP / Taper); the selected week's
  // heading is where it gets explained, one tap away.
  const phaseEntry = openOngoing ? null : glossaryEntry(resolvedWeekPhase(week));

  return (
    <section className="sp-card cm-week-overview">
      <div className="cm-week-overview-head">
        <p className="sp-eyebrow">Week overview</p>
        <h2 className="sp-redflags-title">
          {heading}
          {phaseEntry ? (
            <span className="cm-week-phase">
              <span className="sp-tag sp-accent">{phaseEntry.term}</span>
              <GlossaryTooltip term={phaseEntry.term} />
            </span>
          ) : null}
        </h2>
      </div>

      {weekIntent ? (
        <p className="sp-block-purpose cm-week-intent">
          <span className="sp-tag sp-accent">{weekIntent.label}</span>
          {weekIntent.summary}
        </p>
      ) : null}

      {rows.length > 0 ? (
        <div className="sp-block-stats cm-week-overview-stats">
          {rows.map((row) => (
            <span
              key={row.label}
              className="sp-stat"
              data-wide={row.wide ? "" : undefined}
              data-wide-mobile={row.wideMobile ? "" : undefined}
            >
              <span className="sp-stat-label">{row.label}</span>
              {row.value}
            </span>
          ))}
        </div>
      ) : null}
      {completion.total > 0 && sessionSummary.coachLedSessions > 0 ? (
        // Training days = app sessions + coach/gym days, so "0/2" beside a
        // 4-day week needs saying out loud rather than inferring from labels.
        <p className="muted cm-week-count-note">
          App completed counts the sessions you run in the app. Coach/gym days are tracked separately.
        </p>
      ) : null}
    </section>
  );
}

export function StructuredPlanRenderer({
  plan,
  openOngoing = false,
  today,
  createdAt,
  focusDay,
  currentDayLabel = "Today",
  completions,
  currentTrainingDayIso,
  scheduleContext,
  onLogSession,
  isAdmin = false,
  rehabLabelPolicy,
  exerciseMedia,
}: {
  plan: StructuredPlan;
  /** Renewable four-week plan without a scheduled fight date. */
  openOngoing?: boolean;
  today?: Date;
  /** Plan creation timestamp. For an open plan without a server projection it
   * anchors which week of the renewable block is current (the Monday of the week
   * the plan starts training in, mirroring the backend timeline). Not
   * rendered. */
  createdAt?: string | null;
  /** Accepted for compatibility with callers, but not rendered on this plan view. */
  planStatus?: string | null;
  /** Optional advance target: the next scheduled session's day, passed once
   * today is already logged. It moves ONLY the opened week + day highlight, never
   * the truthful current week marker. Omit it for the normal calendar view. */
  focusDay?: Date;
  /** Badge text for the highlighted day. Callers pass "Next session" alongside
   * `focusDay` so the advanced day is not mislabelled "Today". */
  currentDayLabel?: string;
  /** Live completion rows from /api/plans/{id}/completions. When present the
   * day cards colour every session from real logging instead of the static
   * generation-time statuses. */
  completions?: readonly TodaySessionCompletionRecord[] | null;
  /** Server-authoritative athlete-local training day (YYYY-MM-DD). */
  currentTrainingDayIso?: string | null;
  /** Server-derived timing projection. Open plans use it for block identity and
   * fail-closed legacy messaging; dated camps keep their existing D-X spine. */
  scheduleContext?: PlanScheduleContext | null;
  /** Opens the retro-log flow for a past, still-loggable session. */
  onLogSession?: (day: StructuredDay, session: StructuredSession, sessionId: string) => void;
  /** Whether the viewer is an admin. The raw "Original plan text" dump is an
   * internal artefact and is hidden from athletes; it still appears for admins,
   * and for anyone in the fail-closed "schedule unavailable" state where the
   * on-screen message directs the athlete to the raw plan below. */
  isAdmin?: boolean;
  /** Server-derived per-region Rehab/Prehab policy (PlanDetail.rehab_label_policy).
   * Rehab blocks whose target region is no longer injured render as "Prehab".
   * Omitted → every rehab block keeps reading "Rehab". */
  rehabLabelPolicy?: RehabLabelPolicy | null;
  /** Curated demo videos keyed by block display_name (PlanOutputs.exercise_media). */
  exerciseMedia?: Record<string, ExerciseMedia> | null;
}) {
  const weeks = getWeeks(plan);
  const completionIndex = useMemo(
    () => (completions ? buildCompletionIndex(completions) : undefined),
    [completions],
  );

  // Resolve "today" through the shared 03:00 training-day rollover so Plan Detail
  // and the Today tab can never disagree on the current day.
  const mountedDay = useTrainingDay();
  const serverTrainingDay = useMemo(() => {
    const iso = cleanText(currentTrainingDayIso) || cleanText(scheduleContext?.current_training_day);
    if (!iso) {
      return undefined;
    }
    const parsed = new Date(`${iso.slice(0, 10)}T12:00:00`);
    return Number.isNaN(parsed.getTime()) ? undefined : parsed;
  }, [currentTrainingDayIso, scheduleContext?.current_training_day]);
  const calendarDay = today ?? serverTrainingDay ?? mountedDay;

  // Weekday-only open plans need to know which week of the renewable block is
  // current; dated camps ignore the hint (they resolve by calendar date).
  const openWeekNumber = openOngoing
    ? resolveOpenPlanWeekNumber(plan, calendarDay ?? null, {
        currentWeekNumber: scheduleContext?.current_week_number,
        anchorDate: scheduleContext?.anchor_date,
        createdAt,
      })
    : null;

  // The real calendar training day owns the truthful current week marker.
  // `focusDay` only advances the opened week/day highlight.
  const calendarProgress = resolvePlanProgress(plan, calendarDay, {
    openWeekNumber,
    allowDatedWeekdayMatch: openOngoing,
  });
  const resolvedFocusDay = focusDay
    ? resolveNextPlanFocusDay(plan, calendarDay, focusDay, {
        openWeekNumber,
        allowDatedWeekdayMatch: openOngoing,
      })
    : undefined;
  const focusProgress = resolvedFocusDay
    ? resolvePlanProgress(plan, resolvedFocusDay, {
        openWeekNumber,
        allowDatedWeekdayMatch: openOngoing,
      })
    : calendarProgress;
  // The calendar owns the truthful active week while today is inside the camp.
  // Just before a dated camp starts, there is no calendar match yet; in that
  // case the already-resolved next-session focus supplies the actionable week
  // for the red live marker. Manual week selection never changes this value.
  const activeWeekPos =
    calendarProgress.currentWeekPos ?? focusProgress.currentWeekPos;

  // `selectedPos` holds ONLY an explicit manual week choice; while it is null the
  // view auto-follows the plan's current week via the fallback in `effectivePos`
  // below (so no effect is needed to sync it, and there is no render loop).
  const [selectedPos, setSelectedPos] = useState<number | null>(null);

  // A stable identity for the current plan's week structure. When the component
  // is handed a different plan without remounting — e.g. the plan viewer swaps an
  // adapted text plan for the richer structured payload — a retained manual
  // `selectedPos` could point at a week index from the OLD structure. Reset it
  // DURING render (React's recommended "reset state on prop change" pattern):
  // this drops the stale selection before anything renders, so the wrong week is
  // never briefly shown, with no extra effect/render pass.
  const weekSignature = useMemo(
    () =>
      `${weeks.length}:` +
      weeks
        .map((week) => cleanText(week.week_id) || cleanText(week.start_date) || "")
        .join("|"),
    [weeks],
  );
  const [prevWeekSignature, setPrevWeekSignature] = useState(weekSignature);
  if (weekSignature !== prevWeekSignature) {
    setPrevWeekSignature(weekSignature);
    setSelectedPos(null);
  }

  const handleSelectWeek = (pos: number) => {
    setSelectedPos(pos);
  };

  const effectivePos = selectedPos ?? focusProgress.currentWeekPos ?? 0;
  const safePos = effectivePos >= 0 && effectivePos < weeks.length ? effectivePos : 0;
  const selectedWeek = weeks[safePos];

  const progressionNotes = cleanText(plan.progression_notes);
  const rawFallback = cleanText(plan.raw_markdown_fallback);
  const safetyOwnershipTexts = useMemo(
    () => [
      ...getSafetyPriorityTexts(plan),
      ...getActiveNotesExcludingRedFlags(plan)
        .map((note) => cleanText(note.text))
        .filter((text): text is string => text !== null),
    ],
    [plan],
  );
  // The raw plan dump is internal: athletes see the structured cards only. It
  // stays for admins, and for the fail-closed schedule-unavailable state whose
  // message tells the athlete to read the original plan below.
  const scheduleUnavailable =
    openOngoing && scheduleContext?.projection_status === "unavailable";
  const showRawFallback = Boolean(rawFallback) && (isAdmin || scheduleUnavailable);
  const hasNutritionSupport = getNutritionPhaseItems(plan).length > 0 || hasNutrition(plan);
  const hasRecoverySupport = getRecoveryPhaseItems(plan).length > 0;
  const dayList = useMemo(() => (selectedWeek ? getDays(selectedWeek) : []), [selectedWeek]);
  const dayTimeline = useMemo(
    () => buildDayTimeline(dayList, !openOngoing),
    [dayList, openOngoing],
  );
  // Calendar day a synthesized gap row should highlight. Gap days never exist
  // in the plan, so focusProgress can't mark them — compare dates directly.
  // Only in the normal (non-advanced) view, though: once the plan advances to a
  // future "Next session" (focusDay set), that future session card owns the
  // marker, so gap rows stay plain instead of stamping today with a label that
  // belongs to a different day.
  const restCurrentIso = focusDay
    ? null
    : (cleanText(currentTrainingDayIso)?.slice(0, 10) ??
      cleanText(scheduleContext?.current_training_day)?.slice(0, 10) ??
      (calendarDay ? toLocalIsoDay(calendarDay) : null));
  // Open the support phase that matches the week the athlete is viewing.
  const activeSupportPhaseKey = normalizeSupportPhaseKey(resolvedWeekPhase(selectedWeek));
  // A block that starts on a future Monday — an open plan generated late enough
  // in the week to join the next one — has no current day to mark. Say when it
  // starts rather than showing a plain week with no "Today" anywhere on it and
  // leaving the athlete to guess whether the plan is live.
  //
  // The block starts on the server's anchor (the Monday the week runs from), not
  // on the first day that happens to carry a session: a block anchored to Mon 03
  // Aug whose first session is Thursday still starts on the Monday, and saying
  // "starts Thu 06 Aug" would contradict the week it is shown above. The
  // earliest scheduled day is only a fallback for a payload with no anchor.
  const blockStartsOn = useMemo(() => {
    if (!openOngoing || activeWeekPos !== null) {
      return null;
    }
    const todayIso =
      cleanText(currentTrainingDayIso)?.slice(0, 10) ??
      cleanText(scheduleContext?.current_training_day)?.slice(0, 10) ??
      (calendarDay ? toLocalIsoDay(calendarDay) : null);
    if (!todayIso) {
      return null;
    }
    const anchorIso = cleanText(scheduleContext?.anchor_date)?.slice(0, 10);
    const startIso =
      anchorIso && ISO_DAY_PATTERN.test(anchorIso)
        ? anchorIso
        : weeks
            .flatMap((week) => getDays(week))
            .map((day) => cleanText(day.date)?.slice(0, 10))
            .filter((iso): iso is string => typeof iso === "string" && ISO_DAY_PATTERN.test(iso))
            .sort()[0];
    return startIso && startIso > todayIso
      ? { iso: startIso, relative: describeRelativeDay(startIso, todayIso) }
      : null;
  }, [
    openOngoing,
    activeWeekPos,
    currentTrainingDayIso,
    scheduleContext?.current_training_day,
    scheduleContext?.anchor_date,
    calendarDay,
    weeks,
  ]);

  return (
    <RehabLabelProvider policy={rehabLabelPolicy}>
    <ExerciseMediaProvider media={exerciseMedia}>
    <PlanSourceTextContext.Provider value={rawFallback}>
    <PlanSafetyTextContext.Provider value={safetyOwnershipTexts}>
    <div className="sp-root cm-root">
      {weeks.length > 0 ? (
        <>
          {openOngoing && scheduleContext?.projection_status === "unavailable" ? (
            <section className="sp-card cm-schedule-unavailable" role="status">
              <p className="sp-eyebrow">Schedule unavailable</p>
              <p className="sp-block-purpose">
                This legacy plan could not be matched safely to weekdays. Use the original plan
                below until the schedule is rebuilt.
              </p>
            </section>
          ) : null}
          <WeekStrip
            weeks={weeks}
            selectedPos={safePos}
            currentPos={activeWeekPos}
            onSelect={handleSelectWeek}
            completionIndex={completionIndex}
            openOngoing={openOngoing}
          />

          {selectedWeek ? (
            <WeekOverview
              week={selectedWeek}
              weekNumber={safePos + 1}
              completionIndex={completionIndex}
              openOngoing={openOngoing}
              scheduleContext={scheduleContext}
            />
          ) : null}

          <div className="cm-guardrails">
            <ActiveNotesCard plan={plan} />
            <RedFlagsCard plan={plan} />
          </div>

          {blockStartsOn ? (
            <p className="sp-today-note cm-block-start" role="status">
              {`Plan starts ${formatAppDate(blockStartsOn.iso)}`}
              {blockStartsOn.relative ? ` · ${blockStartsOn.relative.toLowerCase()}` : ""}
            </p>
          ) : null}

          <div className="sp-weeks cm-days">
            {dayList.length > 0 ? (
              dayTimeline.map((entry) => {
                if (entry.kind === "gap") {
                  const gapLabel = gapDayLabel(entry.countdown);
                  return (
                    <RestDayRow
                      key={`rest-${entry.dateIso}`}
                      countdown={entry.countdown}
                      weekday={entry.weekday}
                      label={gapLabel.label}
                      reason={gapLabel.reason}
                      isCurrent={entry.dateIso === restCurrentIso}
                      currentLabel={currentDayLabel}
                    />
                  );
                }
                const { day, index } = entry;
                // Dated days match on the calendar date. A weekday-only (open
                // plan) match carries no date, so it is identified by week/day
                // position instead — only while the matched week is the one
                // being viewed.
                const isCurrent =
                  focusProgress.currentDayDate != null
                    ? cleanText(day.date)?.slice(0, 10) === focusProgress.currentDayDate
                    : focusProgress.currentWeekPos === safePos &&
                      focusProgress.currentDayPos === index &&
                      focusProgress.currentDayPos != null;

                // A pure rest day renders identically to a synthesized gap row,
                // so real and filled-in rest days read as one continuous line.
                if (!openOngoing && isPlainRestDay(day)) {
                  const restDate = cleanText(day.date);
                  return (
                    <RestDayRow
                      key={restDate || `day-${index}`}
                      countdown={formatCountdownLabel(day.countdown_label)}
                      weekday={weekdayLabel(restDate)}
                      label="Rest"
                      isCurrent={isCurrent}
                      currentLabel={currentDayLabel}
                    />
                  );
                }

                return (
                  <CampDayCard
                    key={cleanText(day.date) || `day-${index}`}
                    day={day}
                    displayDate={
                      isCurrent && focusProgress.matchType === "weekday"
                        ? focusProgress.trainingDayISO
                        : null
                    }
                    fallbackLabel={`Training day ${index + 1}`}
                    openOngoing={openOngoing}
                    weekNumber={safePos + 1}
                    isCurrent={isCurrent}
                    currentLabel={currentDayLabel}
                    defaultOpen={isCurrent || (focusProgress.currentWeekPos == null && index === 0)}
                    completionIndex={completionIndex}
                    currentTrainingDayIso={currentTrainingDayIso}
                    onLogSession={onLogSession}
                  />
                );
              })
            ) : (
              <p className="sp-muted">No days scheduled this week.</p>
            )}
          </div>
        </>
      ) : null}

      {progressionNotes ? (
        <CollapsibleSection
          title="Progression notes"
          detailLabel="notes"
          className="sp-progression"
        >
          <p className="sp-block-purpose">{progressionNotes}</p>
        </CollapsibleSection>
      ) : null}

      {hasRecoverySupport ? (
        <CollapsibleSection
          title="Recovery"
          detailLabel="recovery"
          className="cm-support-section"
        >
          <RecoveryCard
            plan={plan}
            activePhaseKey={activeSupportPhaseKey}
            openOngoing={openOngoing}
          />
        </CollapsibleSection>
      ) : null}

      {hasNutritionSupport ? (
        <CollapsibleSection
          title="Nutrition"
          detailLabel="nutrition"
          className="cm-support-section"
        >
          <NutritionCard
            plan={plan}
            activePhaseKey={activeSupportPhaseKey}
            openOngoing={openOngoing}
          />
        </CollapsibleSection>
      ) : null}

      {showRawFallback ? (
        <details className="sp-collapse cm-raw-fallback">
          <summary className="sp-collapse-summary">
            <span className="sp-collapse-title">Original plan text</span>
            <span className="sp-collapse-action">Show original</span>
          </summary>
          <div className="sp-collapse-body">
            <pre className="cm-raw-pre">{rawFallback}</pre>
          </div>
        </details>
      ) : null}
    </div>
    </PlanSafetyTextContext.Provider>
    </PlanSourceTextContext.Provider>
    </ExerciseMediaProvider>
    </RehabLabelProvider>
  );
}

web/components/today-screen.tsx:
"use client";

import Link from "next/link";
import { useMemo } from "react";
import styles from "./today-screen.module.css";

import { useAppSession } from "@/components/auth-provider";
import { hasHealthDataConsent } from "@/lib/compliance";
import { ContextualFeedback } from "@/components/feedback/contextual-feedback";
import { Skeleton } from "@/components/skeleton";
import { formatTrainingDay } from "@/components/today/format";
import { TodayDecisionPanel } from "@/components/today/today-decision-panel";
import { TodayInjuryManager } from "@/components/today/today-injury-manager";
import { TodayReadinessForm } from "@/components/today/today-readiness-form";
import { TodayRiskWatch } from "@/components/today/today-risk-watch";
import { TodaySessionPanel } from "@/components/today/today-session-panel";
import { useTodayCommand } from "@/components/today/use-today-command";
import { humanizeIfRawEnum } from "@/lib/plan-labels";
import { isOpenOngoingPlan } from "@/lib/plan-format";
import { getTodayNextStep } from "@/lib/today-next-step";
import {
  TODAY_EMPTY_TEXT,
  TODAY_EMPTY_TITLE,
  getCompletionLabel,
  getDistinctTodayRiskWatch,
  getSupplementaryRiskWatch,
  hasActivePlan,
  resolveTodayDecision,
  shouldShowTodayCheckin,
} from "@/lib/today";
import type { TodayCompletionStatus } from "@/lib/types";

function TodayLoadingState() {
  return (
    <section className="panel today-shell" aria-busy="true">
      <Skeleton variant="text" width={120} />
      <Skeleton variant="text" width="70%" height={42} />
      <Skeleton variant="block" height={180} />
      <Skeleton variant="block" height={220} />
    </section>
  );
}

function NoActivePlanState() {
  return (
    <section className="panel today-shell today-empty-state">
      <div className="today-hero-copy">
        <p className="kicker">Today</p>
        <h1>{TODAY_EMPTY_TITLE}</h1>
        <p className="muted">{TODAY_EMPTY_TEXT}</p>
      </div>
      <div className="today-action-row">
        <Link href="/onboarding" className="cta">
          Complete Intake
        </Link>
        <Link href="/timer" className="secondary-button">
          Round timer
        </Link>
      </div>
    </section>
  );
}

type TileIconName = "check" | "clock" | "pulse" | "injury" | "plan" | "history" | "timer";

const TILE_ICON_PATHS: Record<TileIconName, string> = {
  check: "M7 12.5l3.2 3.2L17 9",
  clock: "M12 7.5V12l3 2",
  pulse: "M5 12h3l2-4 4 8 2-4h3",
  injury: "M12 7v6M12 16.5v.5",
  plan: "M7 7h10M7 12h10M7 17h6",
  history: "M5 12a7 7 0 107-7 7 7 0 00-5 2.1M5 5v3h3M12 8.5V12l2.5 1.5",
  timer: "M12 13V9.5M9.5 3h5M12 21a8 8 0 100-16 8 8 0 000 16z",
};

function TileIcon({ name, ring = false }: { name: TileIconName; ring?: boolean }) {
  return (
    <svg className={styles.icon} viewBox="0 0 24 24" aria-hidden="true">
      <g fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        {ring ? <circle cx="12" cy="12" r="10" /> : null}
        <path d={TILE_ICON_PATHS[name]} />
      </g>
    </svg>
  );
}

const SESSION_TILE_VALUE: Record<TodayCompletionStatus, string> = {
  not_started: "Not started",
  started: "In progress",
  done: "Complete",
  modified: "Modified",
  skipped: "Skipped",
};

// One status tile. With a same-page target the whole tile is the jump-link to
// the section that resolves it; without one it is a plain readout.
function StatusTile({
  label,
  value,
  tone,
  icon,
  href,
  actionLabel,
}: {
  label: string;
  value: string;
  tone?: "pending" | "clear" | "risk";
  icon: TileIconName;
  href?: string;
  actionLabel: string;
}) {
  const body = (
    <>
      <span className={styles.tileIcon}>
        <TileIcon name={icon} ring />
      </span>
      <span className={styles.tileText}>
        <span className={styles.tileLabel}>{label}</span>
        <span className={styles.tileValue}>{value}</span>
      </span>
      {href ? <span className={styles.chevron} aria-hidden="true" /> : null}
    </>
  );
  return (
    <li className={styles.tile} data-tone={tone}>
      {href ? (
        <a href={href} className={styles.tileLink}>
          {body}
          <span className="sr-only">, {actionLabel}</span>
        </a>
      ) : (
        body
      )}
    </li>
  );
}

function TodayReadinessStrip({
  needsCheckin,
  openInjuryCount,
  completionStatus,
  checkinHref,
  injuriesHref,
  sessionHref,
}: {
  needsCheckin: boolean;
  openInjuryCount: number;
  completionStatus: TodayCompletionStatus;
  checkinHref?: string;
  injuriesHref?: string;
  sessionHref?: string;
}) {
  // Tones: pending (amber) = needs the athlete's action, clear (green) =
  // handled, risk (red) = open injuries. The session reads pending while in
  // progress and clear once any completion is logged.
  const sessionLogged =
    completionStatus === "done" ||
    completionStatus === "modified" ||
    completionStatus === "skipped";
  const sessionTone = sessionLogged ? "clear" : completionStatus === "started" ? "pending" : undefined;

  return (
    <ul className={styles.tiles} aria-label="Today command status">
      <StatusTile
        label="Check-in"
        value={needsCheckin ? "Due" : "Done"}
        tone={needsCheckin ? "pending" : "clear"}
        icon={needsCheckin ? "clock" : "check"}
        href={checkinHref}
        actionLabel="Go to today's check-in"
      />
      <StatusTile
        label="Today’s session"
        value={SESSION_TILE_VALUE[completionStatus] ?? getCompletionLabel(completionStatus)}
        tone={sessionTone}
        icon={sessionLogged ? "check" : completionStatus === "started" ? "pulse" : "clock"}
        href={sessionHref}
        actionLabel="Go to today's session"
      />
      <StatusTile
        label="Injuries"
        value={openInjuryCount ? `${openInjuryCount} active` : "None"}
        tone={openInjuryCount ? "risk" : "clear"}
        icon={openInjuryCount ? "injury" : "check"}
        href={injuriesHref}
        actionLabel="Go to injury manager"
      />
    </ul>
  );
}

export function TodayScreen() {
  const { session, me } = useAppSession();
  const token = session?.access_token ?? null;
  const {
    state,
    structuredPlan,
    planSchedule,
    rehabLabelPolicy,
    exerciseMedia,
    isLoading,
    error,
    refresh,
  } = useTodayCommand(token);

  const activePlan = state?.active_plan ?? {};
  const openOngoing = isOpenOngoingPlan(activePlan.fight_date);
  const planTitle = activePlan.name?.trim() || (openOngoing ? "Open training plan" : "Active fight camp");
  const hasPlan = hasActivePlan(activePlan);
  const showCheckin = state ? shouldShowTodayCheckin(state) : false;
  const trainingDayLabel = useMemo(
    () => formatTrainingDay(state?.today.training_day),
    [state?.today.training_day],
  );

  if (isLoading) {
    return <TodayLoadingState />;
  }
  if (error && (!state || /unauthorized|forbidden|not authenticated/i.test(error))) {
    const isAccessIssue = /unauthorized|forbidden|not authenticated/i.test(error);
    return (
      <section className="panel today-shell today-error-state">
        <div className="today-hero-copy">
          <p className="kicker">Today command feed</p>
          <h1>{isAccessIssue ? "Access is locked" : "Today is temporarily unavailable"}</h1>
          <p className="muted" role="alert">
            {isAccessIssue
              ? "Sign in with an active athlete account to unlock Today."
              : "The live check-in feed did not respond. Your saved plan has not changed."}
          </p>
          {process.env.NODE_ENV !== "production" ? (
            <p className="today-error-detail">Technical detail: {error}</p>
          ) : null}
        </div>
        <div className="today-action-row">
          <button type="button" className="cta" onClick={() => void refresh()}>
            Retry Today
          </button>
          <Link href="/plans" className="secondary-button">
            Open Plans
          </Link>
          <Link href="/timer" className="secondary-button">
            Round timer
          </Link>
          <Link href="/" className="ghost-button">
            Overview
          </Link>
        </div>
      </section>
    );
  }

  if (!state || !hasPlan) {
    return <NoActivePlanState />;
  }
  const resolvedDecision = resolveTodayDecision(state);
  const nextStep = getTodayNextStep(state, resolvedDecision);
  const supplementaryRisks = getSupplementaryRiskWatch(
    state.risk_watch,
    resolvedDecision,
  );
  const visibleTriggerLabels =
    resolvedDecision.displayTier === "preview" && !resolvedDecision.currentGuidanceBanner
      ? []
      : state.today.recommendation_trigger_labels;
  const commandRisks = getDistinctTodayRiskWatch(
    supplementaryRisks,
    visibleTriggerLabels,
  );
  const readinessForm = showCheckin ? (
    <TodayReadinessForm
      plan={activePlan}
      token={token ?? ""}
      warnings={state.today.warnings}
      onRefresh={refresh}
    />
  ) : null;
  const sessionPanel = (
    <TodaySessionPanel
      state={state}
      structuredPlan={structuredPlan}
      rehabLabelPolicy={rehabLabelPolicy}
      exerciseMedia={{ ...exerciseMedia, ...state.exercise_media }}
      planSchedule={planSchedule}
      painReasonAllowed={hasHealthDataConsent(me)}
      token={token ?? ""}
      onRefresh={refresh}
      athleteFullName={me?.profile.full_name}
      commandUnavailable={Boolean(error)}
      professionalStatus={me?.profile.professional_status}
    />
  );

  return (
    <div className="today-page">
      {error ? (
        <section className="panel" role="alert">
          <p>Today could not refresh. Your entries are still here. Refresh before starting or saving a session.</p>
          <button type="button" className="secondary-button" onClick={() => void refresh()}>Retry Today</button>
        </section>
      ) : null}
      <section className={`panel today-shell ${styles.command}`}>
        <div className={styles.hero}>
          <div className="today-hero-copy">
            <p className={styles.heroDate}>{trainingDayLabel}</p>
            <h1>Today</h1>
            <p className={styles.heroPhase}>{openOngoing
              ? "Ongoing 4-week block"
              : activePlan.phase
                ? humanizeIfRawEnum(activePlan.phase)
                : null}</p>
          </div>
        </div>
        <TodayReadinessStrip
          needsCheckin={showCheckin}
          openInjuryCount={state.open_injuries?.length ?? 0}
          completionStatus={state.today.completion_status}
          checkinHref={showCheckin ? "#today-checkin" : undefined}
          injuriesHref={token ? "#today-injury" : undefined}
          sessionHref={resolvedDecision.displayTier === "preview" ? undefined : "#today-session"}
        />
        <TodayDecisionPanel
          banner={resolvedDecision.currentGuidanceBanner ?? resolvedDecision.banner}
          compactPreview={resolvedDecision.hasSession && !resolvedDecision.currentGuidanceBanner}
          tier={resolvedDecision.currentGuidanceBanner ? resolvedDecision.authoritativeTier : resolvedDecision.displayTier}
          triggers={state.today.recommendation_trigger_labels}
          safetyChecks={state.today.recommendation_safety_checks}
          context={state.today.recommendation_context_labels}
          sources={resolvedDecision.currentGuidanceBanner
            ? state.today.recommendation_sources?.filter((source) => source !== "today's planned session")
            : state.today.recommendation_sources}
          confidenceNote={state.today.recommendation_confidence_note}
        />
        <TodayRiskWatch
          risks={commandRisks}
          hasActiveInjury={(state.open_injuries?.length ?? 0) > 0}
        />
        {nextStep ? (
          <div className={styles.nextStep} role="status">
            <div>
              <p className={styles.nextStepTitle}>{nextStep.title}</p>
              <p className={styles.nextStepDetail}>{nextStep.detail}</p>
            </div>
            <Link href={nextStep.href}>{nextStep.action} <span aria-hidden="true">→</span></Link>
          </div>
        ) : null}
      </section>

      {resolvedDecision.useSafeReplacement ? (
        <>
          {sessionPanel}
          {readinessForm}
        </>
      ) : (
        <>
          {readinessForm}
          {sessionPanel}
        </>
      )}

      {token ? (
        <TodayInjuryManager
          openInjuries={state.open_injuries ?? []}
          effectiveClearance={state.effective_clinician_clearance}
          delayedPrompts={state.delayed_rehab_prompts}
          token={token}
          onRefresh={refresh}
        />
      ) : null}

      <nav className={styles.quickActions} aria-label="Quick actions">
        <p className={styles.quickTitle}>Quick actions</p>
        <div className={styles.quickRow}>
          {showCheckin ? (
            <a href="#today-checkin" className={styles.quickAction}>
              <TileIcon name="clock" />
              Check in
              <span className={styles.chevron} aria-hidden="true" />
            </a>
          ) : (
            <Link href="/timer" className={styles.quickAction}>
              <TileIcon name="timer" />
              Round timer
              <span className={styles.chevron} aria-hidden="true" />
            </Link>
          )}
          <Link href={`/plans/${activePlan.id}`} className={styles.quickAction}>
            <TileIcon name="plan" />
            View plan
            <span className={styles.chevron} aria-hidden="true" />
          </Link>
          <Link href="/history" className={styles.quickAction}>
            <TileIcon name="history" />
            History
            <span className={styles.chevron} aria-hidden="true" />
          </Link>
        </div>
      </nav>

      {resolvedDecision.recommendationState !== "not_checked_in" ? (
        <ContextualFeedback
          key={`daily-feedback-${state.active_plan?.id ?? "none"}-${state.today.training_day}`}
          token={token ?? ""}
          surface="daily_recommendation"
          className="today-feedback-card"
        />
      ) : null}
    </div>
  );
}

web/components/today/injury-detail-sheet:
"use client";

import { useEffect, useId, useRef, type ReactNode } from "react";
import { createPortal } from "react-dom";
import { lockOverlayScroll } from "@/lib/overlay-scroll-lock";

/** Injury details stay off the daily card; reuse the app's iOS scroll lock.
 * `variant="screen"` fills the viewport for a full screen (Today's session
 * preview). Sheets stack: only the topmost one answers Escape and Tab. */
export function InjuryDetailSheet({ title, children, onClose, busy = false, variant = "sheet", closeLabel = "Close" }: {
  title: string; children: ReactNode; onClose: () => void; busy?: boolean;
  variant?: "sheet" | "screen"; closeLabel?: string;
}) {
  const titleId = useId();
  const panel = useRef<HTMLDivElement>(null);
  const state = useRef({ busy, onClose });
  useEffect(() => { state.current = { busy, onClose }; }, [busy, onClose]);
  useEffect(() => {
    const previous = document.activeElement as HTMLElement | null;
    const release = lockOverlayScroll();
    panel.current?.focus({ preventScroll: true });
    function keydown(event: KeyboardEvent) {
      const dialogs = document.querySelectorAll('[role="dialog"][aria-modal="true"]');
      if (dialogs[dialogs.length - 1] !== panel.current) return;
      if (event.key === "Escape") {
        event.preventDefault();
        if (!state.current.busy) state.current.onClose();
      }
      if (event.key !== "Tab") return;
      const controls = Array.from(panel.current?.querySelectorAll<HTMLElement>(
        'button:not(:disabled), select:not(:disabled), input:not(:disabled), summary, a[href], [tabindex="0"]',
      ) ?? []).filter(control => {
        const details = control.closest("details");
        return !details || details.open || control.tagName === "SUMMARY";
      });
      const first = controls[0], last = controls.at(-1);
      if (!first) { event.preventDefault(); panel.current?.focus(); }
      else if (event.shiftKey && (document.activeElement === first || document.activeElement === panel.current)) {
        event.preventDefault(); last?.focus();
      } else if (!event.shiftKey && (document.activeElement === last || document.activeElement === panel.current)) {
        event.preventDefault(); first.focus();
      }
    }
    document.addEventListener("keydown", keydown);
    return () => { document.removeEventListener("keydown", keydown); release(); previous?.focus({ preventScroll: true }); };
  }, []);
  if (typeof document === "undefined") return null;
  return createPortal(<div className="injury-sheet-backdrop" data-variant={variant} onClick={() => { if (!busy) onClose(); }}>
    <div className="injury-sheet" data-variant={variant} ref={panel} role="dialog" aria-modal="true" aria-labelledby={titleId}
      aria-busy={busy} tabIndex={-1} onClick={event => event.stopPropagation()}>
      <div className="injury-sheet-header"><h2 id={titleId}>{title}</h2>
        <button type="button" className="injury-sheet-close" aria-label={closeLabel} disabled={busy} onClick={onClose}>
          <svg viewBox="0 0 24 24" aria-hidden="true"><path d={variant === "screen" ? "m15 5-7 7 7 7" : "m6 6 12 12M6 18 18 6"} /></svg>
        </button>
      </div>
      {children}
    </div>
  </div>, document.body);
}

export function InjuryChevron() {
  return <svg className="injury-chevron" viewBox="0 0 24 24" aria-hidden="true"><path d="m9 5 7 7-7 7" /></svg>;
}

web/components/today/today-injury-manage:
"use client";

import { type FormEvent, useId, useRef, useState } from "react";

import {
  BodyMap,
  type BodyMapSelection,
  type BodyMapSeverity,
  type BodyMapSide,
} from "@/components/body-map";
import { EffectiveClinicianClearanceStatus, InjuryCareStatus, InjuryClearance } from "@/components/today/injury-care-status";
import { RehabStageMeter, rehabStageLabel } from "@/components/today/rehab-progress-status";
import { SegmentGroup } from "@/components/today/segment-group";
import { useToast } from "@/components/toast-provider";
import { submitTodayInjuryCheckin, submitInjuryEpisodeObservation } from "@/lib/api";
import { normalizeInjuryLabel, resolveInjuryTypeLabel } from "@/lib/injury-display";
import { INJURY_IMPACT_OPTIONS, readInjuryImpact, writeInjuryImpact, type InjuryImpact } from "@/lib/injury-impact";
import { TODAY_INJURY_MAX_WORDS } from "@/lib/input-limits";
import {
  NO_TODAY_INJURY_TYPE,
  TODAY_INJURY_TYPE_OPTIONS,
  TODAY_OTHER_INJURY_TYPES,
  type TodayInjuryTypeSelection,
  type TodayOtherInjuryType,
  composeTodayInjuryDescription,
  readAchillesSite, stripAchillesSite, writeAchillesSite, type AchillesSite,
  readElbowSite, stripElbowSite, writeElbowSite, type ElbowSite,
  readAnkleScope, stripAnkleScope, writeAnkleScope, type AnkleScope,
  getTodayOtherInjuryTypes,
  readTodayOtherInjuryType,
  isInjuryEntryLimited,
  limitInjuryEntryText,
} from "@/lib/today-injury-input";
import type {
  Coverable,
  Drainage,
  FrictionOrContactProblem,
  InjuryFlagRecord,
  InjuryFlagSeverity,
  SkinIntegrity,
  SurfaceInjuryClass,
  TodayInjuryCheckinStatus,
  TodayInjuryDeclaration,
  TodayCommandView,
} from "@/lib/types";

const INJURY_STATUS_ACTIONS: Array<{ value: TodayInjuryCheckinStatus; label: string }> = [
  { value: "improving", label: "Better" },
  { value: "ongoing", label: "Same" },
  { value: "worse", label: "Worse" },
];

// Surface (skin) follow-up ----------------------------------------------------
// A blister, graze or cut is routed by what the skin is doing, not by a blanket
// "injury" rule — so the five skin questions are asked as soon as one is ADDED,
// rather than lying dormant until it is later marked worse or easing. They are
// never shown for other injuries.
//
// The same answers are what a wound is still restricted BY, so they also need a
// way back down: an injury currently held at "no contact" or "needs checking"
// gets a shortened recheck on Easing / Same, which is how an open blister that
// has closed over stops blocking contact. Nothing is ever cleared without the
// athlete confirming it — the recheck opens pre-filled with what is on record.
//
// The three follow-up modes differ only in framing and in the check-in status
// they report: "initial" captures a freshly added wound's baseline (reported
// ``ongoing`` — nothing has changed), "worse" is the way up, "recheck" the way
// back down.
type SurfaceFollowUpMode = "initial" | "worse" | "recheck";

const SURFACE_FOLLOW_UP_STATUS: Record<SurfaceFollowUpMode, TodayInjuryCheckinStatus> = {
  initial: "ongoing",
  worse: "worse",
  recheck: "improving",
};

/** Backend classes that mean "this is a skin injury we route by skin answers". */
const SURFACE_FOLLOW_UP_CLASSES = new Set([
  "stable_surface",
  "surface_local_restriction",
  "surface_no_contact",
]);

/** Classes where the stored skin state is actively restricting training, so an
 * improving report has to say what changed before the restriction can lift. */
const SURFACE_RECHECK_CLASSES = new Set(["surface_no_contact", "surface_medical_review"]);

function needsSurfaceFollowUp(injury: InjuryFlagRecord): boolean {
  return SURFACE_FOLLOW_UP_CLASSES.has(injury.surface_class ?? "non_surface");
}

function needsSurfaceRecheck(injury: InjuryFlagRecord): boolean {
  return SURFACE_RECHECK_CLASSES.has(injury.surface_class ?? "non_surface");
}

/** Bleeding and leaking read as one question to the athlete; the answer maps to
 * the two structured fields the backend routes on. */
type BleedAnswer = "no" | "controlled" | "leaking" | "uncontrolled";

const BLEED_ANSWER_FIELDS: Record<
  BleedAnswer,
  Pick<TodayInjuryDeclaration, "bleeding_status" | "drainage">
> = {
  no: { bleeding_status: "none", drainage: "none" },
  controlled: { bleeding_status: "controlled", drainage: "none" },
  leaking: { bleeding_status: "controlled", drainage: "present" },
  uncontrolled: { bleeding_status: "uncontrolled", drainage: "unknown" },
};

const SKIN_INTEGRITY_OPTIONS: Array<{ value: SkinIntegrity; label: string }> = [
  { value: "intact", label: "Still closed" },
  { value: "open", label: "Open or burst" },
  { value: "unknown", label: "Not sure" },
];

const BLEED_OPTIONS: Array<{ value: BleedAnswer; label: string }> = [
  { value: "no", label: "No" },
  { value: "controlled", label: "A little, stops" },
  { value: "leaking", label: "Weeping" },
  { value: "uncontrolled", label: "Won't stop" },
];

const INFECTION_SIGN_OPTIONS: Array<{ value: string; label: string }> = [
  { value: "spreading_redness", label: "Spreading redness" },
  { value: "pus", label: "Pus" },
  { value: "heat_or_swelling", label: "Hot or swollen" },
  { value: "fever", label: "Fever" },
];

const COVERABLE_OPTIONS: Array<{ value: Coverable; label: string }> = [
  { value: "yes", label: "Yes" },
  { value: "no", label: "No" },
  { value: "unknown", label: "Not sure" },
];

const FRICTION_OPTIONS: Array<{ value: FrictionOrContactProblem; label: string }> = [
  { value: "yes", label: "Yes" },
  { value: "no", label: "No" },
  { value: "unknown", label: "Not sure" },
];

type SurfaceFollowUpAnswers = {
  skin_integrity: SkinIntegrity;
  bleed: BleedAnswer;
  // Bleeding and drainage are one question to the athlete but two stored facts,
  // and "Won't stop" does not say anything about drainage. These two remember
  // what was on record so an untouched recheck can send the stored drainage back
  // instead of overwriting a recorded "present" with "unknown".
  initialBleed: BleedAnswer;
  storedDrainage: Drainage | null;
  infection_signs: string[];
  coverable: Coverable;
  friction_or_contact_problem: FrictionOrContactProblem;
};

const EMPTY_SURFACE_ANSWERS: SurfaceFollowUpAnswers = {
  skin_integrity: "unknown",
  bleed: "no",
  initialBleed: "no",
  storedDrainage: null,
  infection_signs: [],
  coverable: "unknown",
  friction_or_contact_problem: "unknown",
};

/** Open the follow-up on what is already on record, not on blanks.
 *
 * This is what keeps a recheck from silently clearing an infection sign or a
 * bleeding answer the athlete never revisited: every field starts where the
 * backend has it, and only what they change is changed. */
function answersFromInjury(injury: InjuryFlagRecord): SurfaceFollowUpAnswers {
  const bleeding = injury.bleeding_status ?? null;
  let bleed: BleedAnswer = EMPTY_SURFACE_ANSWERS.bleed;
  if (bleeding === "uncontrolled") {
    bleed = "uncontrolled";
  } else if (injury.drainage === "present") {
    bleed = "leaking";
  } else if (bleeding === "controlled") {
    bleed = "controlled";
  } else if (bleeding === "none") {
    bleed = "no";
  }
  return {
    skin_integrity: injury.skin_integrity ?? EMPTY_SURFACE_ANSWERS.skin_integrity,
    bleed,
    initialBleed: bleed,
    storedDrainage: injury.drainage ?? null,
    infection_signs: [...(injury.infection_signs ?? [])],
    coverable: injury.coverable ?? EMPTY_SURFACE_ANSWERS.coverable,
    friction_or_contact_problem:
      injury.friction_or_contact_problem ?? EMPTY_SURFACE_ANSWERS.friction_or_contact_problem,
  };
}

function surfaceDeclaration(
  flagId: string,
  status: TodayInjuryCheckinStatus,
  answers: SurfaceFollowUpAnswers,
): TodayInjuryDeclaration {
  const bleedFields = BLEED_ANSWER_FIELDS[answers.bleed];
  // The athlete did not revisit the bleeding question, so the drainage already
  // on record still stands. Sending the canonical mapping's drainage here would
  // downgrade a stored "present" to "unknown" on an otherwise untouched recheck
  // — losing a safety signal nobody asked to change.
  const drainageUntouched = answers.bleed === answers.initialBleed && answers.storedDrainage !== null;
  return {
    flag_id: flagId,
    status,
    skin_integrity: answers.skin_integrity,
    infection_signs: answers.infection_signs,
    coverable: answers.coverable,
    // Asked on the way back down as well as the way up. Friction is what holds a
    // closed wound at a local restriction, so a recheck that could not answer it
    // left that restriction — and the severity floor under it — with no way to
    // lift. The form opens pre-filled from the record, so leaving it alone still
    // preserves the stored answer.
    friction_or_contact_problem: answers.friction_or_contact_problem,
    ...bleedFields,
    ...(drainageUntouched ? { drainage: answers.storedDrainage as Drainage } : {}),
  };
}

const BODY_MAP_SEVERITY_BY_FLAG: Record<InjuryFlagSeverity, BodyMapSeverity> = {
  mild: "low",
  moderate: "moderate",
  severe: "high",
};

function getInjuryLabel(injury: InjuryFlagRecord): string {
  // Prefer the server-computed label (built from the shared injury synonym
  // logic) so the card matches the reminder and never re-parses raw words.
  const serverLabel = injury.label?.trim();
  if (serverLabel) {
    return serverLabel;
  }
  const raw = injury.body_area?.trim() || injury.description?.trim();
  return normalizeInjuryLabel(raw) || "Injury";
}

function getInjuryType(injury: InjuryFlagRecord): string {
  // Guided intake stores its structured read of the injury in the description
  // (the taxonomy family plus its `family:specific` pair), so the raw field
  // leaks planner vocabulary — "Right shoulder: blister. surface injury.
  // surface injury:blister". The athlete gets the condition and their own
  // words; the routing keys stay internal.
  return resolveInjuryTypeLabel(injury.description, {
    bodyArea: injury.body_area,
    label: injury.label,
  });
}

type SurfaceGuidance = {
  label: string;
  message: string;
  tone: "caution" | "danger";
};

const SURFACE_GUIDANCE: Partial<Record<SurfaceInjuryClass, SurfaceGuidance>> = {
  surface_medical_review: {
    label: "Check before training",
    message: "This skin injury needs checking before training.",
    tone: "danger",
  },
  surface_no_contact: {
    label: "Contact restriction",
    message: "Keep contact off it until the skin is closed and coverable.",
    tone: "caution",
  },
  surface_local_restriction: {
    label: "Protect the area",
    message: "Protect it from rubbing or contact.",
    tone: "caution",
  },
};

/** Persistent, injury-owned guidance. The main Today decision remains the only
 * session-level command; this only states the current local skin restriction. */
function getSurfaceGuidance(injury: InjuryFlagRecord): SurfaceGuidance | null {
  return SURFACE_GUIDANCE[injury.surface_class ?? "non_surface"] ?? null;
}

/**
 * Daily injury check-in. Each open injury can be marked easing / same / worse /
 * resolved (a per-injury update), and new injuries can be added. Writes reconcile
 * the athlete's injury_flags server-side so a resolved injury clears and a new one
 * is tracked — the data the dynamic plan engine will later read. It also feeds the
 * risk watch, so the badge stays live while any injury is open.
 */
export function TodayInjuryManager({
  openInjuries,
  effectiveClearance,
  delayedPrompts = [],
  token,
  onRefresh,
}: {
  openInjuries: InjuryFlagRecord[];
  effectiveClearance?: TodayCommandView["effective_clinician_clearance"];
  delayedPrompts?: TodayCommandView["delayed_rehab_prompts"];
  token: string;
  onRefresh: () => Promise<void>;
}) {
  const { showToast } = useToast();
  const [pendingFlagId, setPendingFlagId] = useState<string | null>(null);
  const [selectedStatusByFlagId, setSelectedStatusByFlagId] = useState<
    Partial<Record<string, TodayInjuryCheckinStatus>>
  >({});
  // Clearing an injury removes it from tracking, so it asks for an explicit
  // confirmation first; this holds the flag id awaiting that "are you sure?".
  const [confirmingClearId, setConfirmingClearId] = useState<string | null>(null);
  // Which injuries have their full check-in controls open under the summary row.
  const [openInjuryIds, setOpenInjuryIds] = useState<Record<string, boolean>>({});
  // A skin injury needs its skin state before a report can be routed — on the
  // way up (worse) and on the way back down (a restricted wound reported easing
  // or the same). This holds the flag id, which report it belongs to, and the
  // answers so far. Nothing is sent — and nothing is marked selected — until it
  // is submitted.
  const [surfaceFollowUpId, setSurfaceFollowUpId] = useState<string | null>(null);
  const [surfaceFollowUpMode, setSurfaceFollowUpMode] = useState<SurfaceFollowUpMode>("worse");
  const [surfaceAnswers, setSurfaceAnswers] = useState<SurfaceFollowUpAnswers>(
    EMPTY_SURFACE_ANSWERS,
  );
  const surfaceFollowUpStatus = SURFACE_FOLLOW_UP_STATUS[surfaceFollowUpMode];
  const isSurfaceRecheck = surfaceFollowUpMode === "recheck";
  const isSurfaceInitial = surfaceFollowUpMode === "initial";
  const [isAddFormOpen, setIsAddFormOpen] = useState(false);
  const [isAdding, setIsAdding] = useState(false);
  const [editingFlagId, setEditingFlagId] = useState<string | null>(null);
  const [newArea, setNewArea] = useState("");
  const [newImpact, setNewImpact] = useState<InjuryImpact | "">("");
  const newSeverity = INJURY_IMPACT_OPTIONS.find((option) => option.value === newImpact)?.flagSeverity ?? "moderate";
  const [manualArea, setManualArea] = useState(false);
  const [notesOpen, setNotesOpen] = useState(false);
  const [newType, setNewType] = useState<TodayInjuryTypeSelection>(NO_TODAY_INJURY_TYPE);
  // The more specific type picked under "Other" ("" = something else, described in the note).
  const [newOtherType, setNewOtherType] = useState<TodayOtherInjuryType | "">("");
  const [newDetail, setNewDetail] = useState("");
  const [achillesSite, setAchillesSite] = useState<AchillesSite>("unknown");
  const [elbowSite, setElbowSite] = useState<ElbowSite>("unknown");
  const [ankleScope, setAnkleScope] = useState<AnkleScope>("unknown");
  // Whether the last edit hit the word/character cap, so the hint can explain the
  // trim instead of a word silently vanishing.
  const [areaLimited, setAreaLimited] = useState(false);
  const [detailLimited, setDetailLimited] = useState(false);
  const [newZone, setNewZone] = useState("");
  const [bodyMapVisible, setBodyMapVisible] = useState(true);
  const [bodyMapSide, setBodyMapSide] = useState<BodyMapSide>("front");
  // Which required answer stopped the last submit attempt. Both the area and
  // the type are required and neither has a default, so a form that only
  // disabled its own submit button left the athlete tapping a dead control
  // with nothing on screen naming what was missing.
  const [addMissing, setAddMissing] = useState<"area" | "type" | "impact" | null>(null);
  const areaInputRef = useRef<HTMLInputElement>(null);
  const typeGroupRef = useRef<HTMLDivElement>(null);
  const addFormId = useId();
  const addErrorId = useId();
  const impactGroupRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<HTMLDivElement>(null);
  const newInjurySelections: BodyMapSelection[] = newArea.trim()
    ? [
        {
          zone: newZone || undefined,
          label: newArea.trim(),
          severity: BODY_MAP_SEVERITY_BY_FLAG[newSeverity],
        },
      ]
    : [];

  async function submit(injuries: TodayInjuryDeclaration[]) {
    const response = await submitTodayInjuryCheckin(token, { injuries });
    await onRefresh();
    return response;
  }

  /** Send one per-injury update. The button only reads as selected AFTER the
   * backend confirms it: an optimistic tick on a request that then fails told
   * the athlete their injury was logged when nothing was saved. Returns whether
   * the write succeeded so callers can keep a follow-up open on failure. */
  async function updateInjury(
    flagId: string,
    status: TodayInjuryCheckinStatus,
    declaration?: TodayInjuryDeclaration,
  ): Promise<boolean> {
    if (pendingFlagId) {
      return false;
    }
    setPendingFlagId(flagId);
    try {
      // Save the current safety report even if a delayed response fails.
      const response = await submit([declaration ?? { flag_id: flagId, status }]);
      setSelectedStatusByFlagId((current) => ({ ...current, [flagId]: status }));
      // The same three-button response answers yesterday's rehab question.
      // Match the exact episode; never attach an answer after an injury changes.
      const currentInjury = response.open_injuries.find(injury => injury.id === flagId);
      const matchingPrompts = (delayedPrompts ?? []).filter(prompt => prompt.injury_id === flagId
        && prompt.injury_episode_id === currentInjury?.episode_id && status !== "resolved");
      try {
        for (const prompt of matchingPrompts) {
          await submitInjuryEpisodeObservation(token, { injury_id: flagId, injury_episode_id: prompt.injury_episode_id,
            event_type: "delayed_rehab_response", exposure_id: prompt.exposure_id,
            response: status === "improving" ? "better" : status === "worse" ? "worse" : "same" });
        }
        if (matchingPrompts.length) await onRefresh();
      } catch {
        showToast("Injury updated. Your rehab response could not be saved; try the same response again.", { tone: "error" });
        return true;
      }
      const previous = openInjuries.find((injury) => injury.id === flagId);
      const updated = response.open_injuries.find((injury) => injury.id === flagId);
      const severityRaised =
        previous && updated
          ? ["mild", "moderate", "severe"].indexOf(updated.severity) >
            ["mild", "moderate", "severe"].indexOf(previous.severity)
          : false;
      if (status !== "resolved" && updated?.surface_class === "surface_medical_review") {
        showToast(
          severityRaised
            ? `Severity raised to ${updated.severity}. This skin injury needs checking.`
            : "This skin injury needs checking before training.",
          { tone: "info" },
        );
      } else if (status !== "resolved" && updated?.surface_class === "surface_no_contact") {
        showToast("Injury updated. Keep contact off it until the skin is closed and coverable.", {
          tone: "info",
        });
      } else if (
        status !== "resolved" &&
        updated?.surface_class === "surface_local_restriction"
      ) {
        showToast("Injury updated. Protect it from rubbing or contact.", { tone: "info" });
      } else {
        showToast(status === "resolved" ? "Injury resolved." : "Injury updated.", {
          tone: "success",
        });
      }
      return true;
    } catch (error) {
      showToast(error instanceof Error ? error.message : "Injury update failed.", { tone: "error" });
      return false;
    } finally {
      setPendingFlagId(null);
    }
  }

  // Better/Same apply straight away. "Resolved" routes through an inline
  // confirmation because it removes the injury from tracking, and "Worse" on a
  // known skin injury routes through the surface follow-up, because how a wound
  // is worse (open? bleeding? coverable?) is what decides whether anything about
  // today's session actually changes.
  function openSurfaceFollowUp(injury: InjuryFlagRecord, mode: SurfaceFollowUpMode) {
    setConfirmingClearId(null);
    // Pre-filled with what is on record, so an untouched answer is preserved
    // rather than blanked by the act of rechecking. (A freshly added injury has
    // nothing on record yet, so this opens on blanks — the baseline to capture.)
    setSurfaceAnswers(answersFromInjury(injury));
    setSurfaceFollowUpMode(mode);
    setSurfaceFollowUpId(injury.id);
  }

  function handleInjuryAction(injury: InjuryFlagRecord, status: TodayInjuryCheckinStatus) {
    // A write is already in flight. updateInjury would refuse this one anyway,
    // but the handler would first tear down whatever follow-up or confirmation
    // is open — so a click on a second row silently discarded the surface
    // answers being filled in on the first. Refuse before touching any state.
    if (pendingFlagId) {
      return;
    }
    if (status === "resolved") {
      setSurfaceFollowUpId(null);
      setConfirmingClearId(injury.id);
      return;
    }
    if (status === "worse" && needsSurfaceFollowUp(injury)) {
      openSurfaceFollowUp(injury, "worse");
      return;
    }
    // An easing report on a wound that is currently restricting training has to
    // say what the skin is doing now — otherwise the restriction would either
    // stick forever or lift on nothing.
    if (status !== "worse" && needsSurfaceRecheck(injury)) {
      openSurfaceFollowUp(injury, "recheck");
      return;
    }
    // Choosing a different answer abandons any pending confirmation/follow-up.
    setConfirmingClearId(null);
    setSurfaceFollowUpId(null);
    void updateInjury(injury.id, status);
  }

  async function confirmClear(flagId: string) {
    const saved = await updateInjury(flagId, "resolved");
    if (saved) {
      setConfirmingClearId(null);
    }
  }

  async function submitSurfaceFollowUp(flagId: string) {
    const status = surfaceFollowUpStatus;
    const saved = await updateInjury(
      flagId,
      status,
      surfaceDeclaration(flagId, status, surfaceAnswers),
    );
    if (saved) {
      setSurfaceFollowUpId(null);
    }
  }

  function toggleInfectionSign(value: string) {
    setSurfaceAnswers((current) => ({
      ...current,
      infection_signs: current.infection_signs.includes(value)
        ? current.infection_signs.filter((sign) => sign !== value)
        : [...current.infection_signs, value],
    }));
  }

  async function addInjury(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (isAdding) {
      return;
    }
    const area = newArea.trim();
    // A type is a required, explicit choice — an area alone cannot submit a blank
    // report. ("Other" is a valid choice; it just carries no condition word.)
    // Say which answer is missing and put the cursor on it, rather than refusing
    // the submit silently.
    if (!area) {
      setAddMissing("area");
      mapRef.current?.querySelector<SVGElement>('[role="button"]')?.focus();
      return;
    }
    if (!newType) {
      setAddMissing("type");
      typeGroupRef.current?.querySelector("button")?.focus();
      return;
    }
    if (!newImpact) {
      setAddMissing("impact");
      impactGroupRef.current?.querySelector("button")?.focus();
      return;
    }
    setAddMissing(null);
    setIsAdding(true);
    try {
      let description = writeInjuryImpact(composeTodayInjuryDescription({ injuryType: newType, otherType: newOtherType, detail: newDetail }), newImpact);
      if (/achilles/i.test(area)) description = writeAchillesSite(description, achillesSite);
      if (/elbow/i.test(area) && newOtherType === "tendonitis") description = writeElbowSite(description, elbowSite);
      if (/ankle/i.test(area) && newOtherType === "sprain") description = writeAnkleScope(description, ankleScope);
      // Whatever open injury the reconcile returns that was not here before this
      // add is the flag it just created — that is how we find it to route on.
      const previousIds = new Set(openInjuries.map((injury) => injury.id));
      const response = await submit([
        { ...(editingFlagId ? { flag_id: editingFlagId } : {}), body_area: area, description, severity: newSeverity, status: "ongoing" },
      ]);
      setNewArea("");
      setNewImpact("");
      setManualArea(false);
      setNotesOpen(false);
      setBodyMapVisible(true);
      setNewType(NO_TODAY_INJURY_TYPE);
      setNewOtherType("");
      setNewDetail(""); setAchillesSite("unknown"); setElbowSite("unknown"); setAnkleScope("unknown");
      setAreaLimited(false);
      setDetailLimited(false);
      setNewZone("");
      setAddMissing(null);
      setIsAddFormOpen(false);
      showToast(editingFlagId ? "Injury updated." : "Injury added.", { tone: "success" });
      setEditingFlagId(null);
      // A skin injury is routed by what the skin is doing, so ask the five
      // surface questions immediately instead of waiting for a later easing /
      // worse report. A wound that already lands in medical review skips the
      // questions — it goes straight to its "get it checked" banner. The
      // follow-up renders on the refreshed row, so it needs the just-created
      // flag id from the response.
      const created = response.open_injuries.find((injury) => !previousIds.has(injury.id));
      if (created && needsSurfaceFollowUp(created)) {
        openSurfaceFollowUp(created, "initial");
      }
    } catch (error) {
      showToast(error instanceof Error ? error.message : "Could not add injury.", { tone: "error" });
    } finally {
      setIsAdding(false);
    }
  }

  function selectBodyMapZone(zone: string, label: string) {
    const sameZone = newZone === zone;
    setNewZone(zone);
    setAddMissing((current) => (current === "area" ? null : current));
    if (!sameZone || !newArea.trim()) {
      // Body-map labels go through the same cap as typed text so an inserted label
      // can never exceed the limit either.
      const limited = limitInjuryEntryText(label);
      setNewArea(limited);
      setAreaLimited(limited !== label);
    }
    setManualArea(false);
    setBodyMapVisible(false);
  }

  // Start a fresh location draft; Change preserves the entered answers.
  function clearBodyMapSelection() {
    setNewArea("");
    setNewZone("");
    setNewImpact("");
    setManualArea(false);
    setNotesOpen(false);
    setBodyMapVisible(true);
    setNewType(NO_TODAY_INJURY_TYPE);
    setNewOtherType("");
    setNewDetail(""); setAchillesSite("unknown"); setElbowSite("unknown"); setAnkleScope("unknown");
    setAreaLimited(false);
    setDetailLimited(false);
    setAddMissing(null);
  }

  return (
    <section id="today-injury" className="today-card today-injury-card" aria-labelledby="today-injury-heading">
      <div className="today-card-head">
        <div>
          <p className="kicker">Injury check-in</p>
          <h2 id="today-injury-heading">Injury management</h2>
        </div>
      </div>
      {/* Omit only a duplicate single-injury summary. Unclear or different
          effective restrictions must remain visible above the individual report. */}
      {effectiveClearance && (openInjuries.length !== 1 || effectiveClearance.requires_update ||
        !openInjuries[0].episode_id ||
        effectiveClearance.limited_by.some((item) => item.injury_id !== openInjuries[0].id) ||
        [...effectiveClearance.scopes].sort().join(",") !==
          [...(openInjuries[0].clinician_clearance?.scopes ?? [])].sort().join(",")) ?
        <EffectiveClinicianClearanceStatus clearance={effectiveClearance} /> : null}
      {openInjuries.length ? (
        <ul className="today-injury-list">
          {openInjuries.map((injury) => {
            const selectedStatus = selectedStatusByFlagId[injury.id];
            const injuryType = getInjuryType(injury);
            const injuryLabel = getInjuryLabel(injury);
            const impact = readInjuryImpact(injury.description ?? "");
            const impactLabel = impact?.value === "not_limiting" ? "Low impact today" : impact?.label ?? `${injury.severity} symptoms`;
            const showInjuryType = injuryType && !injuryLabel.toLowerCase().includes(injuryType.toLowerCase());
            const surfaceGuidance = getSurfaceGuidance(injury);
            const isPending = pendingFlagId === injury.id;
            // Any in-flight write locks every row's status actions, not just its
            // own. The store refuses concurrent writes, so leaving other rows
            // clickable only offered an action that could not succeed — and that
            // discarded a follow-up in progress on its way to failing.
            const isLockedByOtherWrite = pendingFlagId !== null && !isPending;

            const stageLabel = rehabStageLabel(injury.rehab_decision);
            const restriction = injury.clinician_clearance?.scopes.includes("contact")
              ? "Contact training"
              : injury.clinician_clearance?.scopes.includes("training")
                ? "Non-contact training"
                : injury.clinician_clearance?.scopes.includes("rehab")
                  ? "Rehab only"
                  : null;
            // A confirmation or follow-up in progress keeps the controls open.
            const isOpen = Boolean(openInjuryIds[injury.id]) ||
              confirmingClearId === injury.id || surfaceFollowUpId === injury.id;
            const bodyId = `${injury.id}-controls`;

            return (
              <li key={injury.id} className="today-injury-item" data-severity={injury.severity} data-open={isOpen || undefined}>
                <button
                  type="button"
                  className="today-injury-summary-row"
                  aria-expanded={isOpen}
                  aria-controls={bodyId}
                  onClick={() => setOpenInjuryIds((current) => ({ ...current, [injury.id]: !isOpen }))}
                >
                  <span className="today-injury-summary-icon" data-region={injury.region_group ?? undefined} aria-hidden="true" />
                  <span className="today-injury-summary-text">
                    <strong>{injuryLabel}</strong>
                    {stageLabel ? <span>Stage: <em>{stageLabel}</em></span> : <span>{impactLabel}</span>}
                    <RehabStageMeter decision={injury.rehab_decision} />
                  </span>
                  <span className="today-injury-summary-chevron" aria-hidden="true" />
                </button>
                {restriction || stageLabel || isOpen ? (
                  <p className="today-injury-chips">
                    <span className="today-injury-chip-list">
                      {restriction ? <span data-kind="clearance">{restriction}</span> : null}
                      {stageLabel ? <span data-kind="impact">{impactLabel.charAt(0).toUpperCase() + impactLabel.slice(1)}</span> : null}
                    </span>
                    {/* Open, a pencil (Edit) rides this line instead of taking a row of its own. */}
                    {isOpen ? <button type="button" className="today-injury-edit" title="Edit injury" disabled={isAdding || pendingFlagId !== null}
                    onClick={() => {
                      setEditingFlagId(injury.id); setNewArea(injury.body_area);
                      const impact = readInjuryImpact(injury.description ?? "");
                      setNewImpact(impact?.value ?? "");
                      setAchillesSite(readAchillesSite(injury.description ?? ""));
                      setElbowSite(readElbowSite(injury.description ?? ""));
                      setAnkleScope(readAnkleScope(injury.description ?? ""));
                      const description = stripAnkleScope(stripElbowSite(stripAchillesSite(writeInjuryImpact(injury.description ?? "", ""))));
                      const otherType = readTodayOtherInjuryType(description);
                      const type = otherType ? undefined : TODAY_INJURY_TYPE_OPTIONS.find((option) => option.value !== "other" && new RegExp(`\\b${option.value}\\b`, "i").test(description));
                      const typeWord = otherType ? TODAY_OTHER_INJURY_TYPES[otherType].word : type?.value;
                      setNewType(type?.value ?? "other");
                      setNewOtherType(otherType);
                      setNewDetail(typeWord ? description.replace(new RegExp(`^${typeWord}\\.?\\s*`, "i"), "") : description);
                      setNewZone(""); setBodyMapVisible(false); setManualArea(false); setNotesOpen(false); setAddMissing(null);
                      setIsAddFormOpen(true);
                    }}>
                      <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 20h9" /><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4Z" /></svg>
                      <span className="sr-only">Edit</span>
                    </button> : null}
                  </p>
                ) : null}
                <div id={bodyId} className="today-injury-controls" hidden={!isOpen}>
                <div className="today-injury-meta">
                  <span className="today-injury-name">
                    <strong>{injuryLabel}</strong>
                    {showInjuryType ? <small>{injuryType}</small> : null}
                    <small className="today-injury-summary">
                      {injury.status === "monitoring" ? "Monitoring" : "Tracking"} · {impactLabel}
                    </small>
                  </span>
                </div>
                {surfaceGuidance ? (
                  <div
                    className="today-injury-guidance"
                    data-tone={surfaceGuidance.tone}
                    role="note"
                  >
                    <span>{surfaceGuidance.label}</span>
                    <p>{surfaceGuidance.message}</p>
                  </div>
                ) : null}
                {injury.rehab_decision || injury.episode_id ? <InjuryCareStatus injury={injury} token={token} onRefresh={onRefresh} showClearance={false} /> : null}
                <div className="today-injury-update-head">
                  <p className="today-field-label today-injury-status-label">How&apos;s your injury?</p>
                </div>
                <div
                  className="today-segment-row today-injury-status-row"
                  role="group"
                  aria-label={`Update ${getInjuryLabel(injury)}`}
                >
                  {INJURY_STATUS_ACTIONS.map((action) => {
                    // Selected styling means SAVED, and a confirmed backend
                    // write is the only thing that produces it. An answer that
                    // is still waiting on a confirmation or a follow-up gets a
                    // neutral "pending" outline instead, so nothing ever looks
                    // logged before it is.
                    const isSelected = action.value === selectedStatus;
                    const isAwaitingConfirmation =
                      (confirmingClearId === injury.id && action.value === "resolved") ||
                      (surfaceFollowUpId === injury.id && action.value === surfaceFollowUpStatus);

                    return (
                      <button
                        key={action.value}
                        type="button"
                        className={`today-segment${isSelected ? " today-segment-active" : ""}${
                          isAwaitingConfirmation ? " today-segment-pending" : ""
                        }`}
                        disabled={isPending || isLockedByOtherWrite}
                        // aria-pressed stays false until the backend confirms:
                        // pressed means SAVED. The pending state is announced
                        // separately so a screen-reader user still knows the
                        // answer is captured but not yet written.
                        aria-pressed={isSelected}
                        aria-describedby={
                          isAwaitingConfirmation ? `${injury.id}-pending-hint` : undefined
                        }
                        data-awaiting-confirmation={isAwaitingConfirmation || undefined}
                        onClick={() => handleInjuryAction(injury, action.value)}
                      >
                        {action.label}
                      </button>
                    );
                  })}
                </div>
                <InjuryClearance key={`${injury.id}:${injury.episode_id}`} injury={injury} token={token} onRefresh={onRefresh} />
                <button type="button" className={`today-tool-link injury-resolve-link${confirmingClearId === injury.id ? " today-segment-pending" : ""}${selectedStatus === "resolved" ? " today-segment-active" : ""}`} aria-pressed={selectedStatus === "resolved"} aria-describedby={confirmingClearId === injury.id ? `${injury.id}-pending-hint` : undefined}
                  disabled={isAdding || pendingFlagId !== null} onClick={() => handleInjuryAction(injury, "resolved")}>Mark resolved</button>
                {confirmingClearId === injury.id || surfaceFollowUpId === injury.id ? (
                  <p id={`${injury.id}-pending-hint`} className="today-injury-pending-hint">
                    Not saved yet. Confirm below.
                  </p>
                ) : null}
                {surfaceFollowUpId === injury.id ? (
                  <div
                    className="today-injury-surface-followup"
                    data-mode={surfaceFollowUpMode}
                    role="group"
                    aria-label={
                      isSurfaceRecheck
                        ? `Recheck the ${getInjuryLabel(injury)}`
                        : isSurfaceInitial
                          ? `Skin check for the ${getInjuryLabel(injury)}`
                          : `How is the ${getInjuryLabel(injury)} worse?`
                    }
                  >
                    <div className="today-injury-followup-head">
                      <p className="today-injury-followup-eyebrow">
                        {isSurfaceRecheck ? "Skin recheck" : "Skin check"}
                        <span aria-hidden="true"> · 5 quick questions</span>
                      </p>
                      <p className="today-injury-confirm-text">
                        {isSurfaceRecheck
                          ? "Quick recheck so we can lift what no longer applies."
                          : isSurfaceInitial
                            ? "Quick check so we protect the right thing from the start."
                            : "Quick check so we only change what we need to."}
                      </p>
                    </div>
                    <SegmentGroup
                      label={isSurfaceRecheck ? "Is the skin closed now?" : "Is it open or burst?"}
                      value={surfaceAnswers.skin_integrity}
                      options={SKIN_INTEGRITY_OPTIONS}
                      onChange={(value) =>
                        setSurfaceAnswers((current) => ({ ...current, skin_integrity: value }))
                      }
                    />
                    <SegmentGroup
                      label="Bleeding or weeping?"
                      value={surfaceAnswers.bleed}
                      options={BLEED_OPTIONS}
                      onChange={(value) => setSurfaceAnswers((current) => ({ ...current, bleed: value }))}
                      columns={2}
                    />
                    <div className="today-field-group">
                      <p className="today-field-label">Any infection signs?</p>
                      {/* Multi-select, unlike every other control in this panel — say
                          so and keep a live count, so "none picked" reads as an
                          answered question rather than a skipped one. */}
                      <p className="today-field-hint" aria-live="polite">
                        {surfaceAnswers.infection_signs.length
                          ? `${surfaceAnswers.infection_signs.length} selected`
                          : "Tap any that apply. None is fine."}
                      </p>
                      {/* One per row: these labels are the longest in the panel
                          and will not share a line on a phone without being
                          broken across two. */}
                      <div className="today-segment-row today-segment-row-list">
                        {INFECTION_SIGN_OPTIONS.map((option) => {
                          const checked = surfaceAnswers.infection_signs.includes(option.value);
                          return (
                            <button
                              key={option.value}
                              type="button"
                              className={`today-segment today-segment-multi${
                                checked ? " today-segment-active" : ""
                              }`}
                              aria-pressed={checked}
                              onClick={() => toggleInfectionSign(option.value)}
                            >
                              {option.label}
                            </button>
                          );
                        })}
                      </div>
                    </div>
                    <SegmentGroup
                      label="Can it stay covered?"
                      value={surfaceAnswers.coverable}
                      options={COVERABLE_OPTIONS}
                      onChange={(value) =>
                        setSurfaceAnswers((current) => ({ ...current, coverable: value }))
                      }
                    />
                    <SegmentGroup
                      label={
                        isSurfaceRecheck
                          ? "Is rubbing or contact still the problem?"
                          : "Is rubbing or contact the problem?"
                      }
                      value={surfaceAnswers.friction_or_contact_problem}
                      options={FRICTION_OPTIONS}
                      onChange={(value) =>
                        setSurfaceAnswers((current) => ({
                          ...current,
                          friction_or_contact_problem: value,
                        }))
                      }
                    />
                    <div className="today-injury-confirm-actions today-injury-followup-actions">
                      <button
                        type="button"
                        className="today-injury-confirm-yes"
                        disabled={pendingFlagId !== null}
                        onClick={() => void submitSurfaceFollowUp(injury.id)}
                      >
                        {isPending ? "Saving..." : "Save update"}
                      </button>
                      <button
                        type="button"
                        className="today-injury-confirm-cancel"
                        disabled={pendingFlagId !== null}
                        onClick={() => setSurfaceFollowUpId(null)}
                      >
                        Cancel
                      </button>
                    </div>
                  </div>
                ) : null}
                {confirmingClearId === injury.id ? (
                  <div
                    className="today-injury-confirm"
                    role="alertdialog"
                    aria-label={`Resolve ${getInjuryLabel(injury)}?`}
                  >
                    <span className="today-injury-confirm-text">
                      Resolve this injury? It will be removed from today&apos;s tracking.
                    </span>
                    <div className="today-injury-confirm-actions">
                      <button
                        type="button"
                        className="today-injury-confirm-yes"
                        disabled={pendingFlagId !== null}
                        onClick={() => void confirmClear(injury.id)}
                      >
                        {pendingFlagId === injury.id ? "Resolving..." : "Yes, resolve"}
                      </button>
                      <button
                        type="button"
                        className="today-injury-confirm-cancel"
                        disabled={pendingFlagId !== null}
                        onClick={() => setConfirmingClearId(null)}
                      >
                        Cancel
                      </button>
                    </div>
                  </div>
                ) : null}
                </div>
              </li>
            );
          })}
        </ul>
      ) : (
        <p className="muted">No injuries tracked.</p>
      )}

      <button
        type="button"
        className="today-risk-more today-injury-add-trigger"
        aria-controls={addFormId}
        aria-expanded={isAddFormOpen}
        data-expanded={isAddFormOpen ? "true" : "false"}
        onClick={() => {
        if (editingFlagId) { clearBodyMapSelection(); setEditingFlagId(null); setIsAddFormOpen(true); }
        else setIsAddFormOpen((current) => !current);
      }}
      >
        <span>
          {isAddFormOpen ? "" : "+ "}
          {openInjuries.length ? "Add another injury" : "Add injury"}
        </span>
        <span className="today-injury-add-chevron" aria-hidden="true" />
      </button>

      <form
        id={addFormId}
        className="today-injury-add"
        hidden={!isAddFormOpen}
        onSubmit={addInjury}
      >
        {editingFlagId ? <p className="today-injury-add-title">Edit injury</p> : null}
        {bodyMapVisible ? (
          <div ref={mapRef}>
            <BodyMap side={bodyMapSide} selections={newInjurySelections}
              onZoneSelect={selectBodyMapZone} onSideChange={setBodyMapSide} />
          </div>
        ) : null}
        {newArea.trim() ? (
          <div className="today-injury-selection" aria-live="polite">
            <span aria-hidden="true">✓</span><strong>{newArea.trim()}</strong>
            <button type="button" onClick={() => setBodyMapVisible(true)} disabled={isAdding}>Change</button>
            <button type="button" className="today-injury-selection-clear" onClick={clearBodyMapSelection} disabled={isAdding}>Clear</button>
          </div>
        ) : null}
        <button type="button" className="gi-notes-toggle injury-manual-entry" aria-expanded={manualArea}
          onClick={() => setManualArea((current) => !current)}>
          {manualArea ? "Use the body map" : "Can’t find the area? Enter it manually"}
        </button>
        {manualArea ? <div className="field">
          <label htmlFor="today-injury-area">
            Affected area
            <span className="today-field-required">Required</span>
          </label>
          <input
            id="today-injury-area"
            ref={areaInputRef}
            value={newArea}
            spellCheck
            placeholder="e.g. left shoulder"
            aria-invalid={addMissing === "area" || undefined}
            aria-describedby={addMissing === "area" ? addErrorId : undefined}
            onChange={(event) => {
              const raw = event.target.value;
              const value = limitInjuryEntryText(raw);
              setAreaLimited(value !== raw);
              setNewArea(value);
              setNewZone("");
              if (value.trim()) {
                setAddMissing((current) => (current === "area" ? null : current));
              } else {
                setNewZone("");
              }
            }}
          />
          <small
            className="today-injury-limit-hint"
            data-limit-hit={areaLimited}
            aria-live="polite"
          >
            {areaLimited
              ? `${TODAY_INJURY_MAX_WORDS}-word limit. Extra removed`
              : `Up to ${TODAY_INJURY_MAX_WORDS} words`}
          </small>
        </div> : null}
        <div ref={typeGroupRef}>
          <SegmentGroup
            label="Type"
            value={newType}
            options={TODAY_INJURY_TYPE_OPTIONS}
            onChange={(value) => {
              setNewType(value);
              if (value !== "other") setNewOtherType("");
              setAddMissing((current) => (current === "type" ? null : current));
            }}
            columns={2}
            required
            invalid={addMissing === "type"}
          />
          {newType === "other" ? <TodayOtherTypePicker area={newArea.trim()} value={newOtherType}
            onChange={setNewOtherType} onDescribe={() => { setNewOtherType(""); setNotesOpen(true); }} /> : null}
        </div>
        {/achilles/i.test(newArea) ? <div className="field">
          <label htmlFor="today-achilles-site">Where is the Achilles problem?</label>
          <select id="today-achilles-site" value={achillesSite} onChange={event => setAchillesSite(event.target.value as AchillesSite)}>
            <option value="unknown">Not sure</option>
            <option value="midportion">Above the heel</option>
            <option value="insertional">Where the tendon meets the heel</option>
          </select>
        </div> : null}
        {/elbow/i.test(newArea) && newOtherType === "tendonitis" ? <SegmentGroup
          label="Where is the elbow problem?"
          value={elbowSite}
          options={[{ value: "lateral", label: "Outside of elbow" }, { value: "other", label: "Elsewhere" }, { value: "unknown", label: "Not sure" }]}
          onChange={value => setElbowSite(value as ElbowSite)}
        /> : null}
        {/ankle/i.test(newArea) && newOtherType === "sprain" ? <SegmentGroup
          label="What type of sprain did your clinician describe?"
          value={ankleScope}
          options={[{ value: "uncomplicated_lateral", label: "Uncomplicated outer ankle sprain" }, { value: "other", label: "Another type" }, { value: "unknown", label: "Not sure" }]}
          onChange={value => setAnkleScope(value as AnkleScope)}
        /> : null}
        <div ref={impactGroupRef} className="injury-impact-input">
          <SegmentGroup label="How much is it affecting you?" value={newImpact}
            options={INJURY_IMPACT_OPTIONS.map(({ value, label }) => ({ value, label }))}
            required invalid={addMissing === "impact"}
            onChange={(value) => { setNewImpact(value as InjuryImpact); setAddMissing((current) => current === "impact" ? null : current); }} />
        </div>
        <button type="button" className="gi-notes-toggle injury-optional-note" aria-expanded={notesOpen} onClick={() => setNotesOpen((current) => !current)}>
          {notesOpen ? "Hide optional note" : "+ Add note (optional)"}
        </button>
        {notesOpen ? (
        <div className="field today-injury-detail">
          <label htmlFor="today-injury-detail">Note (optional)</label>
          <input
            id="today-injury-detail"
            value={newDetail}
            spellCheck
            placeholder="e.g. worse when sprinting"
            onChange={(event) => {
              const raw = event.target.value;
              setDetailLimited(isInjuryEntryLimited(raw));
              setNewDetail(limitInjuryEntryText(raw));
            }}
          />
          <small
            className="today-injury-limit-hint"
            data-limit-hit={detailLimited}
            aria-live="polite"
          >
            {detailLimited
              ? `${TODAY_INJURY_MAX_WORDS}-word limit. Extra removed`
              : `Up to ${TODAY_INJURY_MAX_WORDS} words`}
          </small>
        </div>
        ) : null}
        {addMissing ? (
          <p id={addErrorId} className="today-inline-error" role="alert">
            {addMissing === "area"
              ? "Say where it is first. Tap an area or enter it manually."
              : addMissing === "impact" ? "Choose how much it is affecting your training."
              : "Pick a type first. If none of these fit, tap “Other”."}
          </p>
        ) : null}
        {/* Deliberately not disabled on an incomplete form. A disabled submit is
            the reason a missing type read as the app being broken: the only
            feedback was a button that would not respond. Let the tap land, then
            name what is missing. */}
        <button type="submit" className="secondary-button" disabled={isAdding}>
          {isAdding ? "Saving..." : editingFlagId ? "Save update" : "Save injury"}
        </button>
      </form>
    </section>
  );
}

function TodayOtherTypePicker({ area, value, onChange, onDescribe }: {
  area: string;
  value: TodayOtherInjuryType | "";
  onChange: (value: TodayOtherInjuryType | "") => void;
  onDescribe: () => void;
}) {
  const { suggested, skin } = getTodayOtherInjuryTypes(area);
  const chip = (type: TodayOtherInjuryType) => (
    <button key={type} type="button" className={`gi-chip${value === type ? " gi-chip-selected" : ""}`}
      aria-pressed={value === type} onClick={() => onChange(value === type ? "" : type)}>
      {TODAY_OTHER_INJURY_TYPES[type].label}
    </button>
  );
  return (
    <div className="today-injury-other" role="group" aria-label="More specific type">
      <p className="today-injury-other-label">{area ? `Common for ${area.toLowerCase()}` : "More types"}</p>
      <div className="gi-type-grid">{suggested.map(chip)}</div>
      {value && TODAY_OTHER_INJURY_TYPES[value].serious ? (
        <p className="today-injury-other-warning" role="status">Get this checked by a clinician before training.</p>
      ) : null}
      <p className="today-injury-other-label">Skin</p>
      <div className="gi-type-grid">{skin.map(chip)}</div>
      <button type="button" className="gi-text-link today-injury-other-describe" onClick={onDescribe}>
        Something else? Describe it in a note
      </button>
    </div>
  );
}

web/components/today/today-session-panel:
"use client";

import { useCallback, useEffect, useState, useSyncExternalStore, type ReactNode } from "react";

import { ExerciseMediaProvider } from "@/components/exercise-demo";
import { ExerciseLogProvider, type ExerciseLogging } from "@/components/exercise-log";
import { SessionFeedbackPrompt } from "@/components/feedback/session-feedback-prompt";
import {
  SessionCompletionForm,
  type CompletionIntent,
} from "@/components/session-completion-form";
import {
  DaySessionContext,
