import { requiresComplianceAcceptance } from "@/lib/compliance";
import { requiresPrivateTrialAcknowledgement } from "@/lib/private-trial";
import type { MeResponse } from "@/lib/types";

/**
 * Where an athlete belongs once the private trial briefing is behind them:
 * their latest plan if they have one, otherwise onboarding.
 *
 * Kept separate from `getAuthenticatedLandingHref` so the trial screen can send
 * the tester onwards after they acknowledge without re-entering the gate.
 */
export function getAthleteWorkspaceHref(me: MeResponse | null): string {
  if (me?.latest_plan?.plan_id) {
    return `/plans/${me.latest_plan.plan_id}`;
  }

  return "/onboarding";
}

export function getAuthenticatedLandingHref(me: MeResponse | null): string {
  if (me?.profile.role === "admin") {
    return "/admin";
  }

  // Coach and gym_owner are not live yet. No account currently holds these
  // roles, but route defensively to the protected "Coming soon" pages so they
  // never land in the athlete intake/dashboard flow if one is ever assigned.
  if (me?.profile.role === "coach") {
    return "/coach";
  }

  if (me?.profile.role === "gym_owner") {
    return "/gym-owner";
  }

  // Age and Terms come first: an athlete who has not accepted the Terms has not
  // completed signup, so they cannot be sent into the trial briefing or intake.
  // Only reached by accounts that predate the consent fields — a signup through
  // the current form already satisfies this.
  if (requiresComplianceAcceptance(me)) {
    return "/consent";
  }

  // The trial briefing sits between account creation and onboarding: a tester
  // has to know what the trial asks of them before they start answering intake
  // questions. It is shown once — the acknowledgement lives on the profile.
  if (requiresPrivateTrialAcknowledgement(me)) {
    return "/private-trial";
  }

  return getAthleteWorkspaceHref(me);
}

web/lib/exercise-log.ts:
import { cleanText, finitePositiveNumber, isModeLikeReps, isTimeLikeReps } from "@/lib/structured-plan";
import type {
  ExerciseLogActual,
  ExerciseLogReason,
  ExerciseLogRecord,
  ExerciseLogMeasure,
  ExerciseLogRequest,
  ExerciseLogStatus,
  ExerciseRecentLoad,
  StructuredBlock,
  StructuredSession,
} from "@/lib/types";

/**
 * The model behind in-session exercise logging: which numbers an exercise can
 * be logged with, how what the athlete typed compares with the prescription,
 * and how a saved log reads back. The prescription itself is never edited.
 */

export type LogFieldKey = "sets" | "reps" | "load" | "duration" | "work" | "rounds" | "distance" | "effort";

export type LogField = {
  key: LogFieldKey;
  label: string;
  /** Unit shown beside the input ("kg", "min"); null for bare counts. */
  unit: string | null;
  /** Unit sent to the API for measured fields; null for counts and RPE. */
  apiUnit: string | null;
  /** The prescribed value, or the prescribed range ("8-12" is [8, 12]). Null
   * when the plan gives no number for this field (the weight on the bar). */
  prescribed: [number, number] | null;
  /** The prescription as written, shown as the input's placeholder. */
  hint: string | null;
};

export const EXERCISE_LOG_REASONS: readonly ExerciseLogReason[] = ["equipment", "fatigue", "pain", "felt_strong"];

// Short answers to "why?", so a chip reads on its own and in a saved log line.
export const EXERCISE_LOG_REASON_LABELS: Record<ExerciseLogReason, string> = {
  equipment: "No kit",
  fatigue: "Too tired",
  pain: "Pain",
  felt_strong: "Felt strong",
};

export const EXERCISE_LOG_STATUS_LABELS: Record<ExerciseLogStatus, string> = {
  as_prescribed: "Done",
  modified: "Changed",
  skipped: "Skipped",
};

/** A value this many times over (or under) the prescription is confirmed before saving. */
const OUTLIER_RATIO = 3;
/** With no prescribed load to compare with, anything past this is confirmed. */
const OUTLIER_LOAD_KG = 400;

// Loads the athlete cannot put a number on.
const UNWEIGHED_LOAD_METHODS = new Set(["bodyweight", "band"]);

function timeUnit(unit: unknown): { unit: string; apiUnit: string } | null {
  const text = cleanText(unit)?.toLowerCase() ?? "";
  if (/^(s|sec|secs|second|seconds)$/.test(text)) return { unit: "sec", apiUnit: "seconds" };
  if (/^(m|min|mins|minute|minutes)$/.test(text)) return { unit: "min", apiUnit: "minutes" };
  return null;
}

function distanceUnit(unit: unknown): { unit: string; apiUnit: string } | null {
  const text = cleanText(unit)?.toLowerCase() ?? "";
  if (/^(m|meter|meters|metre|metres)$/.test(text)) return { unit: "m", apiUnit: "meters" };
  if (/^(km|kilometer|kilometers|kilometre|kilometres)$/.test(text)) return { unit: "km", apiUnit: "km" };
  if (/^(mi|mile|miles)$/.test(text)) return { unit: "mi", apiUnit: "miles" };
  return null;
}

function single(value: number): [number, number] {
  return [value, value];
}

/** "8", "8-12", "5 each side" as a prescribed rep count or range; null for
 * anything that is not a rep count ("30 seconds", "AMRAP"). */
function prescribedReps(reps: StructuredBlock["reps"]): { range: [number, number]; hint: string } | null {
  if (typeof reps === "number") {
    return finitePositiveNumber(reps) ? { range: single(reps), hint: String(reps) } : null;
  }
  const text = cleanText(reps);
  if (!text || isTimeLikeReps(text) || isModeLikeReps(text)) {
    return null;
  }
  const match = /^(\d+)(?:\s*[-–—]\s*(\d+))?(?![\d.])/.exec(text);
  if (!match) {
    return null;
  }
  const low = Number(match[1]);
  const high = match[2] ? Number(match[2]) : low;
  if (!finitePositiveNumber(low) || high < low) {
    return null;
  }
  return { range: [low, high], hint: text.replace(/\s*[-–—]\s*/, "–") };
}

function measured(
  key: LogFieldKey,
  label: string,
  value: StructuredBlock["duration"],
  resolveUnit: (unit: unknown) => { unit: string; apiUnit: string } | null,
): LogField | null {
  const amount = value?.value;
  const unit = resolveUnit(value?.unit);
  if (!finitePositiveNumber(amount) || !unit) {
    return null;
  }
  return { key, label, ...unit, prescribed: single(amount), hint: String(amount) };
}

/**
 * The numbers this exercise can be logged with, in display order. A field is
 * offered when the prescription carries it; the weight used is offered for
 * rep-based work, because the plan rarely prescribes one; RPE is always offered.
 */
export function logFieldsForBlock(block: StructuredBlock): LogField[] {
  const fields: LogField[] = [];
  const sets = finitePositiveNumber(block.sets) ? block.sets : null;
  const reps = prescribedReps(block.reps);
  if (sets !== null) {
    fields.push({ key: "sets", label: "Sets", unit: null, apiUnit: null, prescribed: single(sets), hint: String(sets) });
  }
  if (reps) {
    fields.push({ key: "reps", label: "Reps", unit: null, apiUnit: null, prescribed: reps.range, hint: reps.hint });
  }
  const timed = [
    measured("duration", "Duration", block.duration, timeUnit),
    measured("work", "Work", block.work, timeUnit),
    measured("distance", "Distance", block.distance, distanceUnit),
  ].filter((field): field is LogField => field !== null);
  const loadMethod = cleanText(block.load?.method)?.toLowerCase() ?? "";
  // Sets of a sprint or a hold are not weighed; sets of reps (or bare sets) are.
  const weighed = Boolean(reps) || (sets !== null && timed.length === 0);
  if (weighed && !UNWEIGHED_LOAD_METHODS.has(loadMethod)) {
    const loadUnit = cleanText(block.load?.unit)?.toLowerCase();
    const prescribedLoad =
      (loadUnit === "kg" || loadUnit === "lb") && finitePositiveNumber(block.load?.value)
        ? block.load.value
        : null;
    fields.push({
      key: "load",
      label: "Load",
      unit: loadUnit === "lb" ? "lb" : "kg",
      apiUnit: loadUnit === "lb" ? "lb" : "kg",
      prescribed: prescribedLoad === null ? null : single(prescribedLoad),
      hint: prescribedLoad === null ? null : String(prescribedLoad),
    });
  }
  const rounds = finitePositiveNumber(block.rounds) ? block.rounds : null;
  if (rounds !== null) {
    fields.push({ key: "rounds", label: "Rounds", unit: null, apiUnit: null, prescribed: single(rounds), hint: String(rounds) });
  }
  fields.push(...timed);

  const effort = block.effort;
  const prescribedRpe =
    cleanText(effort?.method)?.toUpperCase() === "RPE" && typeof effort?.value === "number" && finitePositiveNumber(effort.value)
      ? effort.value
      : null;
  fields.push({
    key: "effort",
    label: "RPE",
    unit: null,
    apiUnit: null,
    prescribed: prescribedRpe === null ? null : single(prescribedRpe),
    hint: prescribedRpe === null ? "1–10" : String(prescribedRpe),
  });
  return fields;
}

/** Whether the exercise has anything beyond RPE to put a different number on. */
export function hasLoggableNumbers(fields: LogField[]): boolean {
  return fields.some((field) => field.key !== "effort");
}

export type LogDraft = Partial<Record<LogFieldKey, string>>;

function parseEntry(text: string | undefined): number | null {
  const cleaned = (text ?? "").trim().replace(",", ".");
  if (!/^\d+(?:\.\d+)?$/.test(cleaned)) {
    return null;
  }
  const value = Number(cleaned);
  return Number.isFinite(value) ? value : null;
}

function formatNumber(value: number): string {
  return String(Math.round(value * 100) / 100);
}

function formatPrescribed(field: LogField): string {
  if (!field.prescribed) return "";
  const [low, high] = field.prescribed;
  return low === high ? formatNumber(low) : `${formatNumber(low)}–${formatNumber(high)}`;
}

/** "3 sets", "80 kg", "15 min", "RPE 8". */
export function formatLogValue(field: LogField, value: number): string {
  const number = formatNumber(value);
  if (field.key === "effort") return `RPE ${number}`;
  if (field.unit) return `${number} ${field.unit}`;
  const noun = field.label.toLowerCase();
  return `${number} ${value === 1 ? noun.replace(/s$/, "") : noun}`;
}

function withValue(actual: ExerciseLogActual, field: LogField, value: number): void {
  switch (field.key) {
    case "sets":
    case "reps":
    case "rounds":
      actual[field.key] = value;
      break;
    case "effort":
      actual.effort = { method: "RPE", value };
      break;
    default:
      actual[field.key] = { value, unit: field.apiUnit ?? "" };
  }
}

export type LogEntryResult = {
  status: Exclude<ExerciseLogStatus, "skipped">;
  /** Only what differs from, or adds to, the prescription. */
  actual: ExerciseLogActual;
  /** Fields that could not be read as a number, or are out of range. */
  invalid: LogFieldKey[];
  /** Entries far enough from the prescription to be worth a second look. */
  outliers: string[];
};

const FIELD_LIMITS: Record<LogFieldKey, [number, number, boolean]> = {
  // [min, max, whole numbers only]
  sets: [0, 50, true],
  reps: [0, 1000, true],
  rounds: [0, 100, true],
  load: [0, 1000, false],
  duration: [0, 600, false],
  work: [0, 600, false],
  distance: [0, 100000, false],
  effort: [1, 10, false],
};

/**
 * Turn what the athlete typed into a log. An empty field means "as written".
 * A number that departs from the prescription makes the log "modified"; a
 * number the plan never gave (the weight used, the RPE felt) is recorded
 * without counting as a change.
 */
export function buildLogEntry(fields: LogField[], draft: LogDraft): LogEntryResult {
  const actual: ExerciseLogActual = {};
  const invalid: LogFieldKey[] = [];
  const outliers: string[] = [];
  let modified = false;
  for (const field of fields) {
    const text = (draft[field.key] ?? "").trim();
    if (!text) {
      continue;
    }
    const value = parseEntry(text);
    const [min, max, whole] = FIELD_LIMITS[field.key];
    if (value === null || value < min || value > max || (whole && !Number.isInteger(value))) {
      invalid.push(field.key);
      continue;
    }
    if (!field.prescribed) {
      withValue(actual, field, value);
      if (field.key === "load" && value > (field.unit === "lb" ? OUTLIER_LOAD_KG * 2.2 : OUTLIER_LOAD_KG)) {
        outliers.push(`${formatLogValue(field, value)} is a very heavy load`);
      }
      continue;
    }
    const [low, high] = field.prescribed;
    if (value >= low && value <= high) {
      // Inside a prescribed range, the exact count is still worth keeping.
      if (low !== high) {
        withValue(actual, field, value);
      }
      continue;
    }
    modified = true;
    withValue(actual, field, value);
    if (value > high * OUTLIER_RATIO || value < low / OUTLIER_RATIO) {
      outliers.push(`${formatLogValue(field, value)} against ${formatPrescribed(field)} prescribed`);
    }
  }
  return { status: modified ? "modified" : "as_prescribed", actual, invalid, outliers };
}

function actualNumber(actual: ExerciseLogActual | null | undefined, key: LogFieldKey): number | null {
  const value = key === "effort" ? actual?.effort?.value : actual?.[key];
  if (typeof value === "number") return Number.isFinite(value) ? value : null;
  if (value && typeof value === "object" && typeof value.value === "number") {
    return Number.isFinite(value.value) ? value.value : null;
  }
  return null;
}

/** The draft that reproduces a saved log, for editing it. */
export function draftFromLog(fields: LogField[], log: ExerciseLogRecord | null | undefined): LogDraft {
  const draft: LogDraft = {};
  for (const field of fields) {
    const value = actualNumber(log?.actual, field.key);
    if (value !== null) {
      draft[field.key] = formatNumber(value);
    }
  }
  return draft;
}

export type LoggedValue = {
  key: LogFieldKey;
  label: string;
  /** What was done, e.g. "3" or "80 kg". */
  value: string;
  /** The same with its noun: "3 sets", "80 kg", "RPE 8". */
  text: string;
  /** The prescription it replaced; null when it only adds to it. */
  insteadOf: string | null;
};

/** What a saved log recorded, field by field, for showing beside the prescription. */
export function loggedValues(fields: LogField[], log: ExerciseLogRecord): LoggedValue[] {
  const values: LoggedValue[] = [];
  for (const field of fields) {
    const value = actualNumber(log.actual, field.key);
    if (value === null) {
      continue;
    }
    const departs = Boolean(field.prescribed) && (value < field.prescribed![0] || value > field.prescribed![1]);
    const number = formatNumber(value);
    values.push({
      key: field.key,
      label: field.label,
      value: field.unit ? `${number} ${field.unit}` : number,
      text: formatLogValue(field, value),
      insteadOf: departs ? `${formatPrescribed(field)}${field.unit ? ` ${field.unit}` : ""}` : null,
    });
  }
  return values;
}

/** One line for the collapsed row: "Done", "Done · 80 kg", "Changed · 3 sets · 6 reps", "Skipped". */
export function logSummary(fields: LogField[], log: ExerciseLogRecord): string {
  const label = EXERCISE_LOG_STATUS_LABELS[log.status];
  if (log.status === "skipped") {
    return label;
  }
  const parts = fields.flatMap((field) => {
    const value = actualNumber(log.actual, field.key);
    return value === null ? [] : [formatLogValue(field, value)];
  });
  return [label, ...parts].join(" · ");
}

/** Whether a block can be logged at all: it needs its server id, and rehab is
 * logged with the session. */
export function isLoggableBlock(block: StructuredBlock): boolean {
  return Boolean(cleanText(block.block_id)) && cleanText(block.block_type) !== "rehab";
}

export type SessionOutcome = {
  /** The session status the exercise logs add up to. */
  status: "done" | "modified" | "skipped";
  /** Exercises the session owes (optional work and rehab are not counted). */
  total: number;
  logged: number;
  /** Owed exercises with no log yet; they are saved as skipped. */
  unlogged: StructuredBlock[];
  /** What changed, in words, for the session's modification reason. "" when done. */
  reason: string;
};

/**
 * The session's outcome, read off its exercise logs, so the athlete logs each
 * exercise once and never states the session result separately:
 * every owed exercise done as written → done; nothing done → skipped; anything
 * else → modified, with the changes spelled out as the reason. An exercise with
 * no log counts as skipped. Optional sessions never decide the outcome.
 */
export function deriveSessionOutcome(
  sessions: readonly StructuredSession[],
  logs: Readonly<Record<string, ExerciseLogRecord>>,
): SessionOutcome {
  const owed = sessions
    .filter((session) => session.optional !== true)
    .flatMap((session) => session.blocks ?? [])
    .filter(isLoggableBlock);
  const changed: string[] = [];
  const skipped: string[] = [];
  const unlogged: StructuredBlock[] = [];
  let logged = 0;
  for (const block of owed) {
    const name = cleanText(block.display_name) || "Exercise";
    const log = logs[cleanText(block.block_id) ?? ""];
    if (!log) {
      unlogged.push(block);
      skipped.push(name);
      continue;
    }
    logged += 1;
    if (log.status === "skipped") {
      skipped.push(name);
    } else if (log.status === "modified") {
      const values = loggedValues(logFieldsForBlock(block), log).map((value) => value.text);
      changed.push(values.length ? `${name} (${values.join(" · ")})` : name);
    }
  }
  const status =
    owed.length > 0 && skipped.length === owed.length
      ? "skipped"
      : changed.length === 0 && skipped.length === 0
        ? "done"
        : "modified";
  const reason = [
    changed.length ? `Changed: ${changed.join(", ")}.` : "",
    skipped.length ? `Skipped: ${skipped.join(", ")}.` : "",
  ]
    .filter(Boolean)
    .join(" ");
  return { status, total: owed.length, logged, unlogged, reason: status === "done" ? "" : reason };
}

/**
 * The weight this exercise was last logged with, to carry into today's log, or
 * null. Only for weighed work whose plan names no weight (when it does, "done
 * as written" already means that weight), and only in the same unit.
 */
export function lastLoadFor(
  block: StructuredBlock,
  recentLoads: readonly ExerciseRecentLoad[] | undefined,
): ExerciseLogMeasure | null {
  if (!recentLoads?.length) return null;
  const field = logFieldsForBlock(block).find((item) => item.key === "load");
  if (!field || field.prescribed) return null;
  const key = cleanText(block.exercise_key);
  const name = cleanText(block.display_name)?.toLowerCase() ?? "";
  const match =
    (key ? recentLoads.find((item) => item.exercise_key === key) : undefined) ??
    (name ? recentLoads.find((item) => !item.exercise_key && item.display_name.trim().toLowerCase() === name) : undefined);
  if (!match || match.load.unit !== field.apiUnit || !finitePositiveNumber(match.load.value)) return null;
  return { value: match.load.value, unit: match.load.unit };
}

/** A log of work done, with the last weight (eased after a struggle) filled in when none was given. */
export function withLastLoad<T extends Omit<ExerciseLogRequest, "plan_id" | "block_id">>(
  block: StructuredBlock,
  request: T,
  recentLoads: readonly ExerciseRecentLoad[] | undefined,
  history?: readonly ExerciseLogRecord[],
): T {
  const previous = lastPerformanceFor(block, history);
  if (previous?.status === "skipped" || previous?.reason === "pain") return request;
  if (request.status === "skipped" || request.actual?.load) return request;
  // After a struggle the row offers an eased weight, so "done" records that one.
  const load = backoffLoadFor(block, previous) ?? lastLoadFor(block, recentLoads);
  return load ? { ...request, actual: { ...(request.actual ?? {}), load } } : request;
}

/**
 * The effort the session was planned at: the middle RPE of the exercises the
 * session owes, rounded onto the 1-9 session effort scale. Null when the plan
 * gives no RPE. The review starts
 * there so a session that went to plan is one tap to confirm.
 */
export function plannedSessionRpe(sessions: readonly StructuredSession[]): number | null {
  const values = sessions
    .filter((session) => session.optional !== true)
    .flatMap((session) => session.blocks ?? [])
    .filter(isLoggableBlock)
    .flatMap((block) => {
      const effort = block.effort;
      const value = typeof effort?.value === "number" ? effort.value : Number(effort?.value);
      return cleanText(effort?.method)?.toUpperCase() === "RPE" && Number.isFinite(value) && value >= 1 && value <= 10
        ? [value]
        : [];
    })
    .sort((a, b) => a - b);
  if (values.length === 0) return null;
  const middle = values.length / 2;
  const median = values.length % 2 ? values[Math.floor(middle)] : (values[middle - 1] + values[middle]) / 2;
  // The session effort scale stops at 9 (Max Effort).
  return Math.min(9, Math.round(median));
}

/** A planner key is authoritative; names only match legacy records without keys. */
export function lastPerformanceFor(block: StructuredBlock, history?: readonly ExerciseLogRecord[]): ExerciseLogRecord | null {
  const key = cleanText(block.exercise_key);
  const name = cleanText(block.display_name)?.toLowerCase();
  return history?.find((row) => key && row.exercise_key
    ? row.exercise_key === key
    : !row.exercise_key && name && String(row.prescribed.display_name ?? "").trim().toLowerCase() === name) ?? null;
}

export function performanceSummary(log: ExerciseLogRecord): string {
  if (log.status === "skipped") return "Skipped";
  const block: StructuredBlock = {
    ...log.prescribed,
    ...Object.fromEntries((["load", "duration", "work", "distance"] as const)
      .flatMap((key) => log.actual[key] ? [[key, log.actual[key]]] : [])),
  };
  const actual = { ...log.actual };
  // Blank actual fields mean the saved prescription was followed, not today's dose.
  for (const key of ["sets", "reps", "rounds"] as const) {
    if (actual[key] == null && typeof block[key] === "number") actual[key] = block[key] as number;
  }
  const fields = logFieldsForBlock(block);
  const values = loggedValues(fields, { ...log, actual });
  const sets = fields.find((field) => field.key === "sets");
  const reps = fields.find((field) => field.key === "reps");
  const count = (field: LogField | undefined) => {
    if (!field) return null;
    const value = actualNumber(actual, field.key);
    return value !== null ? formatNumber(value) : field.prescribed ? formatPrescribed(field) : null;
  };
  const setCount = count(sets);
  const repCount = count(reps);
  const compactDose = setCount !== null && repCount !== null ? `${setCount} × ${repCount}` : null;
  const parts = [...fields].sort((a, b) => (a.key === "load" ? -1 : b.key === "load" ? 1 : 0)).flatMap((field) => {
    if (compactDose && field.key === "sets") return [compactDose];
    if (compactDose && field.key === "reps") return [];
    const recorded = values.find((value) => value.key === field.key);
    if (recorded) return [recorded.text];
    if (field.key === "effort" || !field.prescribed) return [];
    return [`${formatPrescribed(field)}${field.unit ? ` ${field.unit}` : ` ${field.label.toLowerCase()}`}`];
  });
  return parts.join(" · ") || EXERCISE_LOG_STATUS_LABELS[log.status];
}

/** Only a literal, supported progression rule can propose an increase. */
export function progressionLoadFor(block: StructuredBlock, log: ExerciseLogRecord | null, allowed: boolean): ExerciseLogMeasure | null {
  if (!allowed || !log || log.status === "skipped" || (log.reason != null && log.reason !== "felt_strong") || logFieldsForBlock(block).find((field) => field.key === "load")?.prescribed) return null;
  const field = logFieldsForBlock(block).find((item) => item.key === "load");
  const load = log.actual.load;
  const effort = log.actual.effort;
  const rule = cleanText(block.progression_rule);
  const match = rule?.match(/^(?:add|increase(?: load)? by)\s+(\d+(?:\.\d+)?)\s*(kg|lb)\s+when all (?:sets|reps)(?: (?:are )?complete(?:d)?)?[.!]?$/i);
  if (!field || !load || load.unit !== field.apiUnit || !finitePositiveNumber(load.value) || !match || load.unit !== match[2].toLowerCase()
      || !effort || effort.method !== "RPE" || effort.value > 7
      || block.effort?.method !== "RPE" || typeof block.effort.value !== "number" || effort.value > block.effort.value) return null;
  for (const key of ["sets", "reps"] as const) {
    const planned = log.prescribed[key];
    const current = block[key];
    const done = log.actual[key] ?? planned;
    if (typeof planned !== "number" || typeof done !== "number" || typeof current !== "number"
        || done < planned || current !== planned) return null;
  }
  const increment = Number(match[1]);
  if (!(increment > 0 && increment <= load.value * 0.05)) return null;
  return { value: Math.round((load.value + increment) * 100) / 100, unit: load.unit };
}

/** Last time's weight is eased by this share when the athlete struggled with it. */
const BACKOFF_RATIO = 0.9;

/**
 * A lighter weight to offer when last time's was too much: the athlete flagged
 * fatigue, fell short of the sets or reps, or reported an RPE at least two over
 * the plan's (9+ when the plan gave none). Only a suggestion, never applied on
 * its own, and only while today's dose matches the one that was struggled with.
 * Pain and skips are left out: those already stop the old weight carrying over.
 * A stated reason outranks what the numbers suggest, so short sets for want of
 * kit, or a high RPE on a strong day, are not read as the weight being too much.
 */
export function backoffLoadFor(block: StructuredBlock, log: ExerciseLogRecord | null): ExerciseLogMeasure | null {
  if (!log || log.status === "skipped" || log.reason === "pain") return null;
  if (log.reason === "equipment" || log.reason === "felt_strong") return null;
  const field = logFieldsForBlock(block).find((item) => item.key === "load");
  const load = log.actual.load;
  if (!field || field.prescribed || !load || load.unit !== field.apiUnit || !finitePositiveNumber(load.value)) return null;
  // The block as it was shown last time.
  const before = log.prescribed as StructuredBlock;
  const todayReps = prescribedReps(block.reps)?.range;
  const plannedReps = prescribedReps(before.reps)?.range;
  if (block.sets !== before.sets || todayReps?.join() !== plannedReps?.join()) return null;

  const plannedSets = finitePositiveNumber(before.sets) ? before.sets : null;
  const doneSets = log.actual.sets;
  const doneReps = log.actual.reps;
  const missedDose =
    (plannedSets !== null && typeof doneSets === "number" && doneSets < plannedSets) ||
    (plannedReps !== undefined && typeof doneReps === "number" && doneReps < plannedReps[0]);
  const effort = log.actual.effort;
  const plannedRpe = before.effort;
  const ceiling =
    cleanText(plannedRpe?.method)?.toUpperCase() === "RPE" && typeof plannedRpe?.value === "number" && finitePositiveNumber(plannedRpe.value)
      ? Math.min(plannedRpe.value + 2, 10)
      : 9;
  const overreached = effort?.method === "RPE" && typeof effort.value === "number" && effort.value >= ceiling;
  if (log.reason !== "fatigue" && !missedDose && !overreached) return null;

  // Plate-friendly steps for bar work, finer ones for light dumbbells.
  const heavy = load.unit === "lb" ? load.value >= 55 : load.value >= 25;
  const step = load.unit === "lb" ? (heavy ? 5 : 1) : heavy ? 2.5 : 0.5;
  const eased = Math.round((load.value * BACKOFF_RATIO) / step) * step;
  if (!(eased > 0 && eased < load.value)) return null;
  return { value: Math.round(eased * 100) / 100, unit: load.unit };
}

web/lib/open-block.ts:
// The renewable open-plan development block: Week 1 baseline, Week 2 small
// progression, Week 3 highest controlled, Week 4 deload/reassess (mirrors
// open_plan_spec.development_block in fightcamp/stage2_payload_open_ongoing.py).
//
// An open plan's four weeks share one weekly rhythm, so without this overlay
// they render as identical clones and the block's built-in wave never reaches
// the athlete. These helpers turn the week position into the athlete-facing
// intent (week strip / week overview / Today) and into a per-exercise
// directive on each block card. Display-level only: doses are never mutated
// and no wording is invented here — the per-block progression/deload text is
// written by the structured-card conversion, which knows the exercise type.

import { cleanText, progressionRuleLabel } from "@/lib/structured-plan";
import type { StructuredBlock } from "@/lib/types";

export type OpenBlockWeekKey = "baseline" | "progress" | "peak" | "deload";

export type OpenBlockWeekIntent = {
  key: OpenBlockWeekKey;
  /** 1-based week number inside the renewable block. */
  weekNumber: number;
  /** Short label shown on the week pill. */
  label: string;
  /** One-line week policy shown in the week overview and on Today. */
  summary: string;
};

const OPEN_BLOCK_WEEK_INTENTS: readonly OpenBlockWeekIntent[] = [
  {
    key: "baseline",
    weekNumber: 1,
    label: "Baseline",
    summary: "Run every dose as written and groove technical consistency.",
  },
  {
    key: "progress",
    weekNumber: 2,
    label: "Progress",
    summary:
      "Small progression: apply each exercise's progression rule, but only where last week felt controlled.",
  },
  {
    key: "peak",
    weekNumber: 3,
    label: "Highest controlled",
    summary:
      "The block's top week. Progress again only while movement quality holds.",
  },
  {
    key: "deload",
    weekNumber: 4,
    label: "Deload + reassess",
    summary:
      "Cut working volume roughly in half, stop every session fresh, and reassess for the next block.",
  },
];

/** Pill labels for the open-plan week strip, in block order. */
export const OPEN_BLOCK_WEEK_LABELS: readonly string[] = OPEN_BLOCK_WEEK_INTENTS.map(
  (intent) => intent.label,
);

/** The development-block intent for a 1-based week number, or null outside the
 * four-week block (callers gate on the plan being open/ongoing). */
export function openBlockWeekIntent(
  weekNumber: number | null | undefined,
): OpenBlockWeekIntent | null {
  if (typeof weekNumber !== "number" || !Number.isFinite(weekNumber)) {
    return null;
  }
  return OPEN_BLOCK_WEEK_INTENTS[Math.trunc(weekNumber) - 1] ?? null;
}

export type OpenBlockWeekDirective = {
  /** Aside label on the block card. */
  label: string;
  text: string;
  /** True when the text IS the block's own progression rule, so the generic
   * progression aside would duplicate it and should be suppressed. */
  usesProgressionRule: boolean;
};

/** True when the block carries a genuine progression rule (not a stop rule). */
function progressionRuleText(block: StructuredBlock): string | null {
  const rule = cleanText(block.progression_rule);
  if (!rule || progressionRuleLabel(rule) !== "Progress") {
    return null;
  }
  return rule;
}

/**
 * The week-directed instruction for one block card. Baseline weeks return null
 * (the dose is already the instruction); progression weeks surface the block's
 * own progression rule and the deload week its own deload rule, both written
 * per exercise by the structured-card conversion.
 *
 * A block with no such rule returns null rather than a generic directive: the
 * old "add one set or a small load bump" / "cut working sets roughly in half"
 * fallbacks were invented here, so they told an easy aerobic ride, a mobility
 * drill or a rehab insert to do something that does not apply to it. The week
 * intent still carries the block-level policy for the week strip and overview.
 */
export function openBlockWeekDirective(
  intent: OpenBlockWeekIntent | null | undefined,
  block: StructuredBlock,
): OpenBlockWeekDirective | null {
  if (!intent) {
    return null;
  }
  if (intent.key === "progress" || intent.key === "peak") {
    const rule = progressionRuleText(block);
    if (!rule) {
      return null;
    }
    return { label: "This week", text: rule, usesProgressionRule: true };
  }
  if (intent.key === "deload") {
    const deload = cleanText(block.deload_rule);
    if (!deload) {
      return null;
    }
    return { label: "This week", text: deload, usesProgressionRule: false };
  }
  return null;
}

web/lib/rounds-format.ts:
import type { IntakeOption } from "@/lib/intake-options";

export const ROUND_COUNT_OPTIONS: IntakeOption[] = Array.from({ length: 12 }, (_, index) => ({
  label: String(index + 1),
  value: String(index + 1),
}));

export const ROUND_DURATION_OPTIONS: IntakeOption[] = [
  { label: "1 minute", value: "1" },
  { label: "2 minutes", value: "2" },
  { label: "3 minutes", value: "3" },
  { label: "5 minutes", value: "5" },
];

export type ParsedRoundsFormat = {
  roundCount: string;
  roundDuration: string;
};

const ROUNDS_FORMAT_PATTERN = /^(\d+)\s*[xX]\s*(\d+)$/;

export function parseRoundsFormat(value: string | null | undefined): ParsedRoundsFormat {
  const raw = (value ?? "").trim();
  const match = raw.match(ROUNDS_FORMAT_PATTERN);
  if (!match) {
    return { roundCount: "", roundDuration: "" };
  }
  return {
    roundCount: match[1] ?? "",
    roundDuration: match[2] ?? "",
  };
}

export function buildRoundsFormat(roundCount: string, roundDuration: string): string {
  if (!roundCount || !roundDuration) {
    return "";
  }
  return `${roundCount} x ${roundDuration}`;
}

web/lib/structured-plan.ts:
// Pure, defensive helpers that decide how a structured_plan renders. The React
// components in components/structured-plan-renderer.tsx are thin wrappers over
// these so the rendering rules stay unit-testable (node:test) and crash-proof
// against malformed/partial payloads.
import { formatPlanLabel, isRawEnumLabel } from "./plan-labels.ts";
import type {
  DeterministicMacroRange,
  DeterministicNutritionPhase,
  DeterministicRecoveryPhase,
  DeterministicWeightCut,
  LoadPrescription,
  MeasuredValue,
  PlanOutputs,
  StructuredBlock,
  StructuredDay,
  StructuredPlan,
  StructuredSession,
  StructuredWeek,
} from "@/lib/types";

type MindsetLine = { label: string; value: string };

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** Trimmed non-empty string, or null. Hides null/blank/whitespace fields. */
export function cleanText(value: unknown): string | null {
  if (typeof value !== "string") {
    return null;
  }
  const trimmed = value.trim();
  return trimmed ? trimmed : null;
}

/** Athlete-facing countdown label. Older structured plans can carry the event
 * day as `D0`; keep the UI contract consistent by always rendering it as `D-0`. */
export function formatCountdownLabel(value: unknown): string | null {
  const text = cleanText(value);
  return text ? text.replace(/^D0\b/i, "D-0") : null;
}

/** A safe array (never throws on null/non-array); empty arrays stay empty. */
export function safeArray<T>(value: T[] | null | undefined): T[] {
  return Array.isArray(value) ? value.filter((item) => item != null) : [];
}

/** Capitalise the first character so a mental cue reads as a sentence
 * ("stop if breathing becomes heavy" -> "Stop if breathing becomes heavy").
 * Only the first character is touched, so acronyms and the rest of the phrase
 * are left exactly as authored. */
function capitalizeFirst(value: string): string {
  return value ? value.charAt(0).toUpperCase() + value.slice(1) : value;
}

/** The session objective — the plan's "Why:" line, shown as the subtitle under
 * the session title. Like the mindset cues it is authored inconsistently (mostly
 * lower-case, occasionally sentence-case), which reads as a typo next to the
 * Title Case session name, so normalise the first letter for display and leave
 * the rest of the phrase exactly as authored. */
// A session objective that still carries its source label ("Why: read the exit
// lane…") would render as "WHY Why: read the exit lane…" once the card adds its
// own kicker. The label is the source grammar, not athlete-facing copy.
const LEADING_WHY_LABEL_RE = /^\s*why(?:\s+today)?\s*:\s*/i;

export function formatSessionObjective(value: unknown): string | null {
  const text = cleanText(value);
  if (!text) {
    return null;
  }
  return capitalizeFirst(text.replace(LEADING_WHY_LABEL_RE, "").trim()) || null;
}

/**
 * Whether to render the structured UI instead of the plan_text fallback.
 * True only when structured_plan is an object with at least one week. Malformed
 * or empty structures fall back to plan_text.
 */
export function shouldRenderStructuredPlan(
  outputs: Pick<PlanOutputs, "structured_plan"> | null | undefined,
): boolean {
  const plan = outputs?.structured_plan;
  if (!isObject(plan)) {
    return false;
  }
  const weeks = (plan as StructuredPlan).weeks;
  return Array.isArray(weeks) && weeks.some((week) => isObject(week));
}

const MEANINGLESS_LOAD = new Set(["", "n/a", "na", "none", "null", "-", "0", "tbd"]);

/**
 * Athlete-facing load string, or null when it should be hidden.
 * Prefers ``load.display``; hides empty/null/meaningless values.
 */
export function formatBlockLoad(load: LoadPrescription | null | undefined): string | null {
  if (!isObject(load)) {
    return null;
  }
  const display = cleanText(load.display);
  if (display && !MEANINGLESS_LOAD.has(display.toLowerCase()) && !isNonFiniteNumericToken(display)) {
    return display;
  }
  return null;
}

/** Rest is shown only when it carries a positive value. Hides 0-second rest. */
export function shouldShowRest(rest: MeasuredValue | null | undefined): boolean {
  return isObject(rest) && typeof rest.value === "number" && rest.value > 0;
}

/** A finite, strictly-positive number — the guard for any count/multiplier the
 * renderer prints (sets, reps, rounds). Rejects NaN, ±Infinity, zero, negative
 * and non-numbers so a malformed numeric payload never reaches the UI. */
export function finitePositiveNumber(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value) && value > 0;
}

/** A bare non-finite numeric spelling — "NaN", "Infinity", "+Infinity",
 * "-Infinity" (case-insensitive) — that must never render. This targets the
 * STANDALONE token only, so it never touches a valid range like "4-6" or a time
 * string like "30 seconds" (those carry a dash / units and are not bare tokens). */
export function isNonFiniteNumericToken(text: string): boolean {
  return /^[+-]?(nan|infinity)$/i.test(text.trim());
}

/** "180 seconds" / "45 minutes" / null. Rejects non-finite (NaN/Infinity) and
 * negative values — a duration/rest/distance/work measure is never below zero,
 * and a bad number must not leak into the card as "NaN seconds". */
export function formatMeasured(measured: MeasuredValue | null | undefined): string | null {
  if (
    !isObject(measured) ||
    typeof measured.value !== "number" ||
    !Number.isFinite(measured.value) ||
    measured.value < 0
  ) {
    return null;
  }
  // The unit is free text from the model; "sec_per_side" must read as words.
  const unit = cleanText(measured.unit)?.replace(/_+/g, " ").replace(/\s+/g, " ").trim();
  return unit ? `${measured.value} ${unit}` : `${measured.value}`;
}

const TIME_WORDS_RE =
  /(\d+(?:\.\d+)?)(?:\s*([-–—])\s*(\d+(?:\.\d+)?))?\s*(seconds?|secs?|minutes?|mins?)\b/gi;

/**
 * Short time units for the exercise card: "120 seconds" -> "2 min",
 * "90 seconds" -> "90 sec", "2 minutes" -> "2 min", "60-120 seconds" ->
 * "1-2 min". Seconds become minutes only when every number is a whole minute,
 * so the value never changes, only its wording. Everything else in the string
 * ("× 3", "per side") is left as written.
 */
export function compactTimeUnits(text: string): string {
  return text.replace(TIME_WORDS_RE, (_match, low: string, dash: string | undefined, high: string | undefined, unit: string) => {
    const numbers = [low, high].filter((value): value is string => value !== undefined);
    const range = (values: string[]) => values.join(dash ?? "");
    if (/^m/i.test(unit)) {
      return `${range(numbers)} min`;
    }
    const wholeMinutes = numbers.every((value) => Number(value) >= 60 && Number(value) % 60 === 0);
    return wholeMinutes
      ? `${range(numbers.map((value) => String(Number(value) / 60)))} min`
      : `${range(numbers)} sec`;
  });
}

/** A reps value that is really a duration string, e.g. "5-6 min", "30s", "2 min". */
export function isTimeLikeReps(reps: unknown): boolean {
  if (typeof reps !== "string") {
    return false;
  }
  return /\b(s|sec|secs|second|seconds|min|mins|minute|minutes|hr|hrs|hour|hours)\b/i.test(
    reps,
  ) || /\d\s*s\b/i.test(reps) || /\b\d{1,2}:\d{2}\b/.test(reps);
}

/** A prescription mode stored in `reps` by some structured-plan payloads.
 * These values describe how work is performed, not a repetition count. */
export function isModeLikeReps(reps: string): boolean {
  return /\b(continuous|amrap|emom)\b/i.test(reps);
}

function repsEchoesIntervalWork(block: StructuredBlock, repsText: string): boolean {
  const work = block.work;
  if (
    !finitePositiveNumber(block.rounds) ||
    finitePositiveNumber(block.sets) ||
    !isObject(work) ||
    !finitePositiveNumber(work.value) ||
    !/^s(?:ec(?:ond)?s?)?$/i.test(cleanText(work.unit) ?? "")
  ) {
    return false;
  }
  return /^\d+(?:\.\d+)?$/.test(repsText) && Number(repsText) === work.value;
}

export type BlockMetric = { label: string; value: string };

/**
 * The quantitative "how much" lines for a block, in display order.
 *
 * Strength blocks use reps (with optional sets); time-based work uses duration;
 * conditioning blocks may instead (or additionally) use distance and/or rounds.
 * Prefers an explicit duration over reps when reps looks like a time string.
 * Returns an empty array when the block carries no usable metric.
 */
export function selectBlockMetric(block: StructuredBlock | null | undefined): BlockMetric[] {
  if (!isObject(block)) {
    return [];
  }
  const metrics: BlockMetric[] = [];

  const duration = formatMeasured(block.duration);
  // reps as a NUMBER is only usable when finite and positive, so a malformed
  // NaN/Infinity/negative count never renders as "NaN"/"Infinity"/"-5".
  const repsRaw = block.reps;
  let repsText: string | null =
    typeof repsRaw === "number"
      ? finitePositiveNumber(repsRaw)
        ? String(repsRaw)
        : null
      : cleanText(repsRaw as string | null);
  // A reps STRING that is a bare non-positive number ("-5", "0") is also dropped;
  // ranges like "4-6" (not a single negative number) are kept.
  if (repsText !== null && /^-?\d+(?:\.\d+)?$/.test(repsText) && Number(repsText) <= 0) {
    repsText = null;
  }
  // A bare non-finite spelling as text ("NaN", "Infinity", "-Infinity") never
  // renders — a range "4-6" or time "30 seconds" is untouched.
  if (repsText !== null && isNonFiniteNumericToken(repsText)) {
    repsText = null;
  }
  // An interval block (rounds x work) whose bare rep count only repeats the
  // work seconds ("2x3s" read as rounds 2, work 3 sec, reps 3) is an echo, not
  // a volume: "Volume 3" beside "Work 3 seconds" means nothing to the athlete.
  if (repsText !== null && repsEchoesIntervalWork(block, repsText)) {
    repsText = null;
  }
  // The set multiplier must be a finite positive number, or it is omitted.
  const sets = finitePositiveNumber(block.sets) ? (block.sets as number) : null;
  const modeLikeReps = repsText ? isModeLikeReps(repsText) : false;
  const timedHold =
    repsText === "1" && /\b(hold|isometric)\b/i.test(cleanText(block.display_name) ?? "");

  // Whether a metric row already prints the set multiplier. A set count that no
  // row carries is a lost prescription ("2 x 5 sec" rendering as "5 seconds"),
  // so the work/distance rows below pick it up when nothing else did.
  let setsShown = false;
  if ((!repsText || isTimeLikeReps(repsText) || modeLikeReps || timedHold) && duration) {
    // A single hold per set is timed work, not an informative "3 × 1" rep
    // count. Keep its set count alongside the measured, unit-bearing hold.
    metrics.push({ label: "Duration", value: sets && sets > 1 ? `${sets} × ${duration}` : duration });
    setsShown = true;
  } else if (repsText && isTimeLikeReps(repsText)) {
    // The reps value is itself a duration ("30 seconds") and no separate
    // duration exists, so it is time, not a rep count — labelling it "Volume"
    // ("5 × 30 seconds") is semantically wrong. Surface it as Duration, keeping
    // any sets multiplier for the interval count.
    metrics.push({ label: "Duration", value: sets ? `${sets} × ${repsText}` : repsText });
    setsShown = true;
  } else if (repsText && modeLikeReps) {
    // "continuous" / AMRAP / EMOM are execution modes, not volume. When the
    // payload omitted a quantitative duration, keep the card truthful instead
    // of inventing minutes from progression or regression prose.
    metrics.push({
      label: "Mode",
      value: `${repsText.charAt(0).toUpperCase()}${repsText.slice(1)}`,
    });
  } else if (repsText) {
    metrics.push({ label: "Volume", value: sets ? `${sets} × ${repsText}` : repsText });
    setsShown = true;
    if (duration) {
      metrics.push({ label: "Duration", value: duration });
    }
  } else if (duration) {
    metrics.push({ label: "Duration", value: sets && sets > 1 ? `${sets} × ${duration}` : duration });
    setsShown = true;
  }

  const work = formatMeasured(block.work);
  const distance = formatMeasured(block.distance);
  // "1 ×" says nothing, so a single set never needs a carrier.
  const pendingSets = !setsShown && sets && sets > 1 ? sets : null;
  // Timed work per set (sets 2, work 5 sec) prefers the work row; a distance
  // per set (sets 4, distance 200 m) with no work takes it on the distance row.
  const workTakesSets = pendingSets !== null && work !== null;
  const distanceTakesSets = pendingSets !== null && !workTakesSets && distance !== null;

  if (distance) {
    metrics.push({
      label: "Distance",
      value: distanceTakesSets ? `${pendingSets} × ${distance}` : distance,
    });
  }

  if (finitePositiveNumber(block.rounds)) {
    metrics.push({ label: "Rounds", value: String(block.rounds) });
  }

  if (work) {
    metrics.push({ label: "Work", value: workTakesSets ? `${pendingSets} × ${work}` : work });
  }

  return metrics;
}

// Athlete-facing names for an effort method printed without a value.
const EFFORT_METHOD_LABELS: Readonly<Record<string, string>> = {
  rpe: "RPE",
  rir: "RIR",
  intent: "Intent",
  velocity: "Velocity",
  heart_rate_zone: "Heart rate zone",
  pace: "Pace",
  max_effort_percent: "Max effort %",
};

// Intent values that are a bare intensity word read as "Max intent"; anything
// more descriptive ("max_speed", "explosive") already says how to move.
const BARE_INTENT_LEVELS = new Set([
  "max",
  "maximal",
  "maximum",
  "full",
  "high",
  "moderate",
  "medium",
  "low",
  "submaximal",
  "sub-maximal",
]);

const NUMERIC_OR_RANGE_RE = /^\d+(?:\.\d+)?(?:\s*[-–—]\s*\d+(?:\.\d+)?)?$/;

/** Machine spellings ("max_speed", "zone_2") as plain words ("max speed"). An
 * all-caps token ("MAX_SPEED") is lowered so the card does not shout. */
function humanizeEffortToken(text: string): string {
  const spaced = text.replace(/_+/g, " ").replace(/\s+/g, " ").trim();
  return /[a-z]/.test(spaced) || !/[A-Z]{2}/.test(spaced) ? spaced : spaced.toLowerCase();
}

/** "RPE 7" / "7 RPE" as a value under method RPE is just "7": the method is
 * printed once by the caller. */
function stripRepeatedMethod(value: string, method: string): string {
  const escaped = method.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return value
    .replace(new RegExp(`^${escaped}\\s*:?\\s*`, "i"), "")
    .replace(new RegExp(`\\s*${escaped}$`, "i"), "")
    .trim();
}

/** "2", "z2", "zone2", "Zone 2", "z2 z3" -> the zone number(s), else null. */
function heartRateZoneNumbers(value: string): string | null {
  if (NUMERIC_OR_RANGE_RE.test(value)) return value;
  const zones = value.match(/^(?:z|zone)\s*(\d)(?:\s*(?:[-–—]|to|\s)\s*(?:z|zone)?\s*(\d))?$/i);
  if (!zones) return null;
  return zones[2] ? `${zones[1]}-${zones[2]}` : zones[1];
}

function effortWithMethod(methodKey: string, method: string, rawValue: string): string {
  const value =
    methodKey in EFFORT_METHOD_LABELS
      ? stripRepeatedMethod(rawValue, methodKey === "heart_rate_zone" ? "heart rate zone" : methodKey) ||
        rawValue
      : rawValue;
  const lower = value.toLowerCase();
  switch (methodKey) {
    case "rpe":
      return `RPE ${value}`;
    case "rir":
      return `RIR ${value}`;
    case "intent":
      if (BARE_INTENT_LEVELS.has(lower)) return `${capitalizeFirst(lower)} intent`;
      // A bare number has no unit on its own. Up to 1 is a fraction of full
      // intent (the model writes 1 for "full", never meaning 1/10 on a power
      // block), up to 10 a 10-point scale, anything larger a percentage.
      if (/^\d+(?:\.\d+)?$/.test(value)) {
        const intent = Number(value);
        if (intent > 0 && intent <= 1) {
          return intent === 1 ? "Max intent" : `${Math.round(intent * 100)}% intent`;
        }
        return intent <= 10 ? `Intent ${value}/10` : `${value}% intent`;
      }
      if (/^\d+(?:\.\d+)?\s*%$/.test(value)) return `${value} intent`;
      return capitalizeFirst(value);
    case "velocity":
      if (NUMERIC_OR_RANGE_RE.test(value)) return `${value} m/s`;
      return capitalizeFirst(value.replace(/(\d)\s*m\/s\b/i, "$1 m/s"));
    case "heart_rate_zone": {
      const zone = heartRateZoneNumbers(value);
      if (zone) return `Zone ${zone}`;
      return capitalizeFirst(/\bzone\b/i.test(value) ? value : `${value} zone`);
    }
    case "pace":
      if (/\bpace\b/i.test(value)) return capitalizeFirst(value);
      return /\d/.test(value) ? `Pace ${value}` : `${capitalizeFirst(value)} pace`;
    case "max_effort_percent":
      if (/^\d+(?:\.\d+)?$/.test(value) && Number(value) > 0 && Number(value) <= 1) {
        // A fraction (0.8) is 80%, never "0.8% of max".
        return `${Math.round(Number(value) * 100)}% of max`;
      }
      if (NUMERIC_OR_RANGE_RE.test(value)) return `${value}% of max`;
      return /\bmax/i.test(value) ? value : `${value} of max`;
    default:
      return capitalizeFirst(`${humanizeEffortToken(method)} ${value}`);
  }
}

/**
 * Athlete-facing effort: "RPE 7", "Max intent", "Max speed", "Zone 2",
 * "80% of max" or null. The payload's method is an enum and its value is often
 * a machine token from the model ("max_speed"), so neither is printed raw.
 */
export function formatEffort(block: StructuredBlock | null | undefined): string | null {
  const effort = block?.effort;
  if (!isObject(effort)) {
    return null;
  }
  const method = cleanText(effort.method);
  // A numeric effort (e.g. RPE 7) must be finite — a NaN/Infinity would otherwise
  // print "RPE NaN". Non-numeric effort passes through cleanText, but a bare
  // non-finite spelling as text ("RPE" + "NaN"/"Infinity") is dropped too.
  const rawValue =
    typeof effort.value === "number"
      ? Number.isFinite(effort.value)
        ? String(effort.value)
        : null
      : cleanText(effort.value as string);
  const cleanValue = rawValue !== null && isNonFiniteNumericToken(rawValue) ? null : rawValue;
  const value = cleanValue ? humanizeEffortToken(cleanValue) || null : null;
  const methodKey = method ? method.toLowerCase() : "";
  if (method && value) {
    return effortWithMethod(methodKey, method, value);
  }
  if (method) {
    return EFFORT_METHOD_LABELS[methodKey] ?? capitalizeFirst(humanizeEffortToken(method));
  }
  return value ? capitalizeFirst(value) : null;
}

// --- safe structural selectors (never throw on partial data) ----------------

/** Local ISO date (YYYY-MM-DD) for the Monday of the week containing `dateStr`. */
function calendarWeekMonday(dateStr: string | null): string | null {
  if (!dateStr) {
    return null;
  }
  const parsed = new Date(`${dateStr.slice(0, 10)}T00:00:00`);
  if (Number.isNaN(parsed.getTime())) {
    return null;
  }
  // getDay(): 0=Sun..6=Sat -> offset back to Monday (0=Mon..6=Sun).
  const offsetToMonday = (parsed.getDay() + 6) % 7;
  parsed.setDate(parsed.getDate() - offsetToMonday);
  const y = parsed.getFullYear();
  const m = String(parsed.getMonth() + 1).padStart(2, "0");
  const d = String(parsed.getDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

/** Whole days between two local ISO date strings, or null if either is unusable. */
function daySpan(startIso: string, endIso: string): number | null {
  const start = new Date(`${startIso.slice(0, 10)}T00:00:00`);
  const end = new Date(`${endIso.slice(0, 10)}T00:00:00`);
  if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime())) {
    return null;
  }
  return Math.round((end.getTime() - start.getTime()) / 86_400_000);
}

const PHASE_RANK: Record<string, number> = {
  GPP: 0,
  SPP: 1,
  TAPER: 2,
  FIGHT_WEEK: 3,
  REINTEGRATION: 4,
};

function phaseCoverage(days: StructuredDay[]): string[] {
  const phases: string[] = [];
  for (const day of days) {
    const phase = cleanText(day.phase_label)?.toUpperCase();
    if (phase && !phases.includes(phase)) {
      phases.push(phase);
    }
  }
  return phases;
}

function displayPhaseForDays(days: StructuredDay[], fallback: string | null | undefined): string | null {
  const counts = new Map<string, number>();
  for (const day of days) {
    const phase = cleanText(day.phase_label)?.toUpperCase();
    if (!phase) continue;
    counts.set(phase, (counts.get(phase) ?? 0) + 1);
  }
  if (counts.size === 0) {
    return cleanText(fallback);
  }
  const top = Math.max(...counts.values());
  return [...counts.entries()]
    .filter(([, count]) => count === top)
    .map(([phase]) => phase)
    .sort((a, b) => (PHASE_RANK[b] ?? 0) - (PHASE_RANK[a] ?? 0))[0] ?? cleanText(fallback);
}

/**
 * Split one plan week into per-calendar-week (Mon–Sun) display weeks.
 *
 * Normal camp weeks already fit inside a single calendar week, so they pass
 * through unchanged. A late-fight / bridge plan, however, ships its whole
 * countdown as ONE week object spanning two or three calendar weeks — which the
 * UI would otherwise render as a single "Week 1" listing every day. Splitting it
 * on Monday boundaries restores the week-by-week view. Each sub-week inherits the
 * source week's metadata but gets its own day list and recomputed date/countdown
 * range. Days without a parseable date stay with the preceding sub-week.
 *
 * Guarded to only ever touch a genuinely long block: a week whose dated days
 * span 7 days or fewer is returned untouched even if it happens to cross a
 * Monday, so a normally-structured camp week is never re-cut.
 */
function splitWeekByCalendarWeek(week: StructuredWeek): StructuredWeek[] {
  const days = getDays(week);
  const datedSorted = days
    .map((day) => cleanText(day.date))
    .filter((value): value is string => value !== null)
    .sort();
  if (datedSorted.length > 0) {
    const span = daySpan(datedSorted[0], datedSorted[datedSorted.length - 1]);
    if (span === null || span <= 7) {
      return [week];
    }
  }

  const groups: { monday: string; days: StructuredDay[] }[] = [];
  const leadingUndated: StructuredDay[] = [];

  for (const day of days) {
    const monday = calendarWeekMonday(cleanText(day.date));
    if (monday === null) {
      if (groups.length > 0) {
        groups[groups.length - 1].days.push(day);
      } else {
        leadingUndated.push(day);
      }
      continue;
    }
    const existing = groups.find((group) => group.monday === monday);
    if (existing) {
      existing.days.push(day);
    } else {
      groups.push({ monday, days: [day] });
    }
  }

  // One calendar week (or no dates to split on) -> leave the week untouched.
  if (groups.length <= 1) {
    return [week];
  }

  groups.sort((a, b) => (a.monday < b.monday ? -1 : a.monday > b.monday ? 1 : 0));
  if (leadingUndated.length > 0) {
    groups[0].days = [...leadingUndated, ...groups[0].days];
  }

  return groups.map((group, index) => {
    const dates = group.days
      .map((day) => cleanText(day.date))
      .filter((value): value is string => value !== null)
      .sort();
    const labels = group.days
      .map((day) => formatCountdownLabel(day.countdown_label))
      .filter((value): value is string => value !== null);
    const splitWeek = {
      ...week,
      week_id: `${cleanText(week.week_id) || "week"}-${group.monday}-cw${index + 1}`,

      days: group.days,
      phase_label: displayPhaseForDays(group.days, week.phase_label),
      phase_coverage: phaseCoverage(group.days),
      start_date: dates[0] ?? week.start_date,
      end_date: dates[dates.length - 1] ?? week.end_date,
      // Days run furthest-from-fight first, so the first/last labels bound the range.
      countdown_start: labels[0] ?? week.countdown_start,
      countdown_end: labels[labels.length - 1] ?? week.countdown_end,
    };
    const inheritedGoal = cleanText(week.week_goal);
    const inheritedLateFightGoal = inferredLateFightWeekContext(week).goal;
    if (
      inheritedGoal &&
      inheritedLateFightGoal &&
      inheritedGoal.toLowerCase() === inheritedLateFightGoal.toLowerCase()
    ) {
      return {
        ...splitWeek,
        week_goal: inferredLateFightWeekContext(splitWeek).goal || inheritedGoal,
      };
    }
    return splitWeek;
  });
}

export function getWeeks(plan: StructuredPlan | null | undefined): StructuredWeek[] {
  const raw = safeArray(plan?.weeks).filter(isObject);
  const split = raw.flatMap(splitWeekByCalendarWeek);
  // No week spanned multiple calendar weeks -> identity (zero change for normal
  // camps). Only when a split happened do we renumber week_index so the strip
  // reads Week 1, 2, 3… in order.
  if (split.length === raw.length) {
    return raw;
  }
  return split.map((week, index) => ({ ...week, week_index: index + 1 }));
}

export function getDays(week: StructuredWeek | null | undefined): StructuredDay[] {
  return safeArray(week?.days).filter(isObject);
}

export function getSessions(day: StructuredDay | null | undefined): StructuredSession[] {
  return safeArray(day?.sessions).filter(isObject);
}

// ---------------------------------------------------------------------------
// Zero-load support: scheduled items that must RENDER but must never count as
// physical training. One shared rule, used by the text adapter, the renderer and
// the completion counters, so rendering fidelity and physical-session
// accounting stay separate concerns (the planner owns the latter in
// fightcamp/physical_session_frequency.py and this never changes it).
// ---------------------------------------------------------------------------

/** Session types that are informational by construction (mental / tactical). */
const ZERO_LOAD_SESSION_TYPES = new Set([
  "mindset",
  "mental",
  "tactical",
  "visualisation",
  "visualization",
  "education",
  "protocol",
  "fight_day",
]);

/** Session types that always prescribe real movement; they win over wording. */
const PHYSICAL_SESSION_TYPES = new Set([
  "strength_power",
  "conditioning",
  "sparring",
  "fight_or_match",
  "rehab",
  "mobility",
  "recovery",
]);

/**
 * Content signals for scheduled zero-load work. Deliberately semantic (what the
 * item IS) rather than a list of drill names, so a new tactical or mental insert
 * is classified correctly without another patch. "Technical"/"footwork"/"joint
 * prep" are NOT here: those are physical work even when they are light.
 */
const ZERO_LOAD_CONTENT_RE =
  /\b(?:visuali[sz]\w*|mental rehearsal|tactical (?:watch|focus|review|cue)|cue card|self-?review|film (?:study|review)|breathing (?:reset|work|only)|fight[- ]day protocol|no physical load|zero[- ]load)\b/i;

/**
 * True when this scheduled item is zero-load support (mental, tactical,
 * breathing-only, fight-day protocol). Such a session still renders in full —
 * it just contributes nothing to physical-session counts.
 *
 * Low-cost PHYSICAL support (joint prep, footwork walkthrough, technical shadow
 * rhythm, walk flush) is deliberately not matched here: it is light work, not
 * absent work, and it keeps counting as a physical session.
 */
export function isZeroLoadSupportSession(
  session: StructuredSession | null | undefined,
): boolean {
  if (!isObject(session)) {
    return false;
  }
  // `stress_class: "support"` is NOT consulted. The planner stamps it on joint
  // prep, footwork walkthroughs and technical shadow rhythm as well as on
  // breathing resets: it means "low cost", not "no movement", and
  // fightcamp/physical_session_frequency.py documents that it is insufficient
  // on its own. Zero load is decided by what the item IS, below.
  const sessionType = cleanText(session.session_type)?.toLowerCase().replace(/[\s-]+/g, "_");
  if (sessionType && ZERO_LOAD_SESSION_TYPES.has(sessionType)) {
    return true;
  }
  // The title names what the item IS, so it is read first: a "Breathing Reset"
  // is zero load even though the adapter infers a `recovery` session type from
  // the same words. Block names only get a say when the session type does not
  // already assert real movement, so a strength session whose accessory happens
  // to mention a cue card is never demoted.
  if (ZERO_LOAD_CONTENT_RE.test(cleanText(session.title) || "")) {
    return true;
  }
  if (sessionType && PHYSICAL_SESSION_TYPES.has(sessionType)) {
    return false;
  }
  const blockNames = getBlocks(session)
    .map((block) => cleanText(block.display_name) || "")
    .join(" ");
  return ZERO_LOAD_CONTENT_RE.test(blockNames);
}

/** Sessions on this day that count toward physical training frequency. */
export function getPhysicalSessions(
  day: StructuredDay | null | undefined,
): StructuredSession[] {
  return getSessions(day).filter((session) => !isZeroLoadSupportSession(session));
}

/** Coach-owned contact kinds that are real physical work the athlete performs. */
const COACH_LED_PHYSICAL_KINDS = new Set<SessionlessDayKind>([
  "coach_led",
  "sparring",
  "technical",
  "light_combat",
]);

/**
 * True when this day's physical training is coach-owned and the app prescribes
 * no physical card of its own: declared hard sparring, and the technical /
 * light-combat days a downgrade produces.
 *
 * The athlete trains physically on such a day, so it is a physical training day
 * even though the app prescribes nothing for it.
 *
 * Two things deliberately do NOT disqualify it:
 *
 *   * zero-load support sharing the day. Production ships "Technical-only
 *     combat + Tactical Focus" on D-11 and "Technical-only combat + Tactical
 *     Cue Card" on D-4; those cards are sessions, but they are not physical
 *     work, so the combat still has to count. Only an app PHYSICAL session on
 *     the same day removes the addition — that day is already counted, and
 *     counting the contact too would double it.
 *   * where the contact is recorded. A day with no app card names it in
 *     `today_card.headline`; a day that also carries app work names it in
 *     `today_card.coach_led_contact` (the deterministic field
 *     `reconcile_coach_led_sparring_days` writes), and the day classifier reads
 *     only the headline. Both are consulted here.
 *
 * Fight day is excluded: D-0 is the competition, not a training session.
 */
export function isCoachLedPhysicalTrainingDay(
  day: StructuredDay | null | undefined,
): boolean {
  if (!isObject(day) || getPhysicalSessions(day).length > 0) {
    return false;
  }
  const countdown = cleanText(day.countdown_label)?.replace(/\s+/g, "").toUpperCase();
  const dayType = cleanText(day.day_type)?.toLowerCase();
  if (countdown === "D-0" || countdown === "D0" || dayType === "competition") {
    return false;
  }
  const contact = getCoachLedContactView(day);
  const kind = contact
    ? contact.kind
    : getSessions(day).length === 0
      ? classifySessionlessDay(day).kind
      : null;
  return kind !== null && COACH_LED_PHYSICAL_KINDS.has(kind);
}

/** Complete planner-owned microdose for this host day; malformed legacy data is hidden. */
export function getPriorityMicrodose(day: StructuredDay | null | undefined) {
  const raw = day?.priority_microdose;
  if (!isObject(raw)) {
    return null;
  }
  const goal = cleanText(raw.goal);
  const name = cleanText(raw.name);
  const prescription = cleanText(raw.prescription);
  return goal && name && prescription ? { goal, name, prescription } : null;
}

export function getBlocks(session: StructuredSession | null | undefined): StructuredBlock[] {
  return safeArray(session?.blocks).filter(isObject);
}

const REHAB_BLOCK_RE = /\b(rehab|prehab|mobility|mobil(?:ity|isation|ization)|isometric|opener)\b/i;

/** Rehab/mobility blocks get a compact always-visible summary on session cards. */
export function isRehabOrMobilityBlock(block: StructuredBlock | null | undefined): boolean {
  if (!isObject(block)) {
    return false;
  }
  return [block.block_type, block.category, block.display_name]
    .map((value) => cleanText(value))
    .some((value) => Boolean(value && REHAB_BLOCK_RE.test(value)));
}

/** Ordered rehab/mobility blocks for a session, empty when absent. */
export function getRehabOrMobilityBlocks(
  session: StructuredSession | null | undefined,
): StructuredBlock[] {
  return getBlocks(session).filter(isRehabOrMobilityBlock);
}

export function getCoachingCues(block: StructuredBlock | null | undefined): string[] {
  return getStringList(block?.coaching_cues);
}

const BARE_ADJUSTMENT_LABEL_RE =
  /^\s*(?:progress(?:ion)?\s*\/\s*)?regress(?:ion)?\s*\/?\s*$/i;
const COACHING_STOP_CUE_RE = /^\s*stop(?:\s+rule)?\s*:/i;

/** Clean legacy converter leakage out of coaching cues while retaining any
 * actionable stop instruction for a labelled Stop rule aside. */
export function getBlockCoachingDisplay(
  block: StructuredBlock | null | undefined,
): { cues: string[]; stopRules: string[] } {
  const cues: string[] = [];
  const stopRules: string[] = [];
  for (const cue of getCoachingCues(block)) {
    if (BARE_ADJUSTMENT_LABEL_RE.test(cue)) {
      continue;
    }
    if (COACHING_STOP_CUE_RE.test(cue)) {
      stopRules.push(cue);
      continue;
    }
    cues.push(cue);
  }
  return { cues, stopRules };
}

const BLOCK_DETAIL_LABEL_RE =
  /^\s*(purpose|why\s+today|easier|regress(?:ion)?|progress(?:ion)?|stop(?:\s+rule)?|swaps?|substitutions?|cue)\s*:\s*(.*)$/i;
const COACHING_PURE_STOP_RE = /^\s*stop(?!-) /i;

function dedupeBlockText(values: string[]): string[] {
  const seen = new Set<string>();
  const result: string[] = [];
  for (const value of values) {
    const text = cleanText(value);
    if (!text) continue;
    const key = text.toLowerCase().replace(/\s+/g, " ").replace(/[.\s]+$/, "");
    if (seen.has(key)) continue;
    seen.add(key);
    result.push(text);
  }
  return result;
}

/** Athlete-facing execution projection. Rich purpose/why-today reasoning stays
 * on the block object, while labelled legacy prose is routed away from cue bullets. */
export function getBlockExecutionDisplay(
  block: StructuredBlock | null | undefined,
): {
  cues: string[];
  stopRules: string[];
  regressions: string[];
  substitutions: string[];
  progressions: string[];
} {
  const cues: string[] = [];
  const stopRules: string[] = [];
  const regressions = getStringList(block?.regression_options);
  const substitutions = getStringList(block?.substitutions);
  const progressions: string[] = [];

  for (const cue of getCoachingCues(block)) {
    if (BARE_ADJUSTMENT_LABEL_RE.test(cue)) continue;
    const labelled = BLOCK_DETAIL_LABEL_RE.exec(cue);
    if (labelled) {
      const label = labelled[1].toLowerCase().replace(/\s+/g, " ");
      const detail = cleanText(labelled[2]);
      if (!detail) continue;
      if (label === "purpose" || label === "why today") continue;
      if (label === "cue") {
        cues.push(detail);
        continue;
      }
      if (label === "easier" || label === "regress" || label === "regression") {
        regressions.push(detail);
      } else if (label === "progress" || label === "progression") {
        progressions.push(detail);
      } else if (label.startsWith("stop")) {
        stopRules.push(detail);
      } else {
        substitutions.push(detail);
      }
      continue;
    }
    if (COACHING_PURE_STOP_RE.test(cue)) {
      stopRules.push(cue);
      continue;
    }
    cues.push(cue);
  }

  return {
    cues: dedupeBlockText(cues),
    stopRules: dedupeBlockText(stopRules),
    regressions: dedupeBlockText(regressions),
    substitutions: dedupeBlockText(substitutions),
    progressions: dedupeBlockText(progressions),
  };
}

const EMBEDDED_STOP_RULE_LABEL_RE = /\bstop(?:\s+rule)?\s*:\s*/i;
const PROGRAMMING_ONLY_PROGRESSION_RE =
  /^\s*(?:maintain(?:\s+(?:the|this))?\s+dose|keep\s+(?:the\s+)?dose\s+small|do\s+not\s+(?:add|increase)\s+(?:sets?|volume)|no\s+(?:set|volume)\s+increase)\b/i;
const NEGATED_PROGRESSION_RE =
  /\b(?:do\s+not|don't|never)\s+(?:add|increase|progress|advance|raise|build|extend)\b/i;
const POSITIVE_PROGRESSION_RE =
  /\b(?:progress|advance|increase|raise|build|extend|heavier|more\s+resistance|reduce\s+assistance)\b/i;
const TAPER_PROGRAMMING_RE = /\b(?:taper|fight[ -]?week|sharpness|freshness)\b/i;

function stripStopRuleLabel(value: string): string {
  return value.replace(/^\s*stop(?:\s+rule)?\s*:\s*/i, "").trim();
}

function isProgrammingOnlyProgression(text: string): boolean {
  if (NEGATED_PROGRESSION_RE.test(text)) {
    return PROGRAMMING_ONLY_PROGRESSION_RE.test(text) || TAPER_PROGRAMMING_RE.test(text);
  }
  if (POSITIVE_PROGRESSION_RE.test(text)) {
    return false;
  }
  return PROGRAMMING_ONLY_PROGRESSION_RE.test(text);
}

function dedupeStopRules(values: string[]): string[] {
  const seen = new Set<string>();
  const result: string[] = [];
  for (const value of values) {
    const text = stripStopRuleLabel(value);
    const key = text.toLowerCase().replace(/[.\s]+$/, "");
    if (!text || seen.has(key)) {
      continue;
    }
    seen.add(key);
    result.push(text);
  }
  return result;
}

export function getBlockAdjustmentDisplay(
  block: StructuredBlock | null | undefined,
): { progression: string | null; stopRules: string[] } {
  const explicitStops = getStringList(block?.stop_rules);
  const execution = getBlockExecutionDisplay(block);
  const progressionCandidates = [
    cleanText(block?.progression_rule),
    ...execution.progressions,
  ].filter((value): value is string => value !== null);
  let progression: string | null = null;
  const embeddedStops: string[] = [];

  for (const rawProgression of progressionCandidates) {
    let candidate: string | null = rawProgression;
    const match = EMBEDDED_STOP_RULE_LABEL_RE.exec(rawProgression);
    if (match) {
      candidate = cleanText(rawProgression.slice(0, match.index).replace(/[\s—–\-:;,.]+$/, ""));
      const stop = cleanText(rawProgression.slice(match.index + match[0].length));
      if (stop) embeddedStops.push(stop);
    } else if (isStopRuleText(rawProgression)) {
      candidate = null;
      embeddedStops.push(rawProgression);
    }
    if (candidate && isProgrammingOnlyProgression(candidate)) candidate = null;
    if (!progression && candidate) progression = candidate;
  }

  return {
    progression,
    stopRules: dedupeStopRules([
      ...explicitStops,
      ...execution.stopRules,
      ...embeddedStops,
    ]),
  };
}

// A stop rule reads like "Stop on sharp pain." / "Stop the set if punch speed
// drops" / "stop if the ankle flares". The conversion model frequently drops
// these into a block's `progression_rule` (its only free-text "what to do"
// field), so the renderer must not label a stop rule as "Progress" — that told
// the athlete to ADVANCE on a safety cue. Detect the stop-rule shape so it can
// be labelled correctly.
const STOP_RULE_RE = /^\s*stop(?!-)\b|(?<!\bdo\snot\s|don't\s|never\s)(?<!-)\bstop (?:the set|on|if|when|immediately)\b/i;

/** Whether a `progression_rule` string is really a stop/safety rule. */
export function isStopRuleText(text: string | null | undefined): boolean {
  const clean = cleanText(text);
  return clean !== null && STOP_RULE_RE.test(clean);
}

/** The label a block's `progression_rule` should render under: a stop rule is
 * surfaced as "Stop rule", genuine progression stays "Progress". */
export function progressionRuleLabel(text: string | null | undefined): "Progress" | "Stop rule" {
  return isStopRuleText(text) ? "Stop rule" : "Progress";
}

/** A clean list of non-empty strings from a possibly-null/non-array value. */
export function getStringList(value: string[] | null | undefined): string[] {
  return safeArray(value)
    .map((item) => cleanText(item))
    .filter((item): item is string => item !== null);
}

/** The mindset anchor as label/value lines (Intent, Focus, Reset, Anchor,
 * Context), in that order, skipping any field that is blank. Empty when the
 * anchor has no usable line, so the renderer can hide the card. */
export function getMindsetLines(
  anchor:
    | {
        intent?: string | null;
        focus_cue?: string | null;
        reset_cue?: string | null;
        confidence_anchor?: string | null;
        context?: string | null;
      }
    | null
    | undefined,
): { label: string; value: string }[] {
  if (!isObject(anchor)) {
    return [];
  }
  const lines: { label: string; value: string }[] = [];
  const intent = cleanText(anchor.intent);
  const focus = cleanText(anchor.focus_cue);
  const reset = cleanText(anchor.reset_cue);
  const confidence = cleanText(anchor.confidence_anchor);
  const context = cleanText(anchor.context);
  // Cues are authored inconsistently (some sentence-case, most lower-case); the
  // card reads better when each one starts with a capital, so normalise the first
  // letter for display without touching the rest of the phrase.
  if (intent) lines.push({ label: "Intent", value: capitalizeFirst(intent) });
  if (focus) lines.push({ label: "Focus", value: capitalizeFirst(focus) });
  if (reset) lines.push({ label: "Reset", value: capitalizeFirst(reset) });
  if (confidence) lines.push({ label: "Anchor", value: capitalizeFirst(confidence) });
  if (context) lines.push({ label: "Context", value: capitalizeFirst(context) });
  return lines;
}

const IMPORTANT_SESSION_CONTEXT_RE =
  /\b(?:injur(?:y|ies)|rehab(?:ilitation)?|prehab|pain|sore(?:ness)?|irritation|strain|sprain|tendon|physio(?:therapy)?|medical|restriction|restricted|modified|limit(?:ed|ing)?|avoid(?:ing)?|taper|fight[ -]?(?:week|day)|weigh[ -]?in|weight[ -]?cut|freshness|return(?:ing)? to (?:training|play))\b/i;
const COACH_SESSION_DEPENDENCY_RE =
  /\b(?:coach(?:[- ]?led)?|gym|sparr(?:ing)?|contact)\b.*\b(?:session|work|block|day|training)\b|\b(?:session|work|block|day|training)\b.*\b(?:coach(?:[- ]?led)?|gym|sparr(?:ing)?|contact)\b/i;

function isImportantSessionContext(value: string): boolean {
  return IMPORTANT_SESSION_CONTEXT_RE.test(value) || COACH_SESSION_DEPENDENCY_RE.test(value);
}

function coachCueValue(values: Array<string | null>): string | null {
  const seen = new Set<string>();
  const cues = values.filter((value): value is string => {
    if (!value) {
      return false;
    }
    const normalized = value.toLowerCase().replace(/\s+/g, " ").replace(/[.\s]+$/, "");
    if (seen.has(normalized)) {
      return false;
    }
    seen.add(normalized);
    return true;
  });
  return cues.length > 0 ? cues.map(capitalizeFirst).join(" · ") : null;
}

/**
 * The compact, athlete-facing session coaching layer. The intake-derived mental
 * framing remains intact, but intent and confidence are one optional Coach cue
 * rather than separate labels. Context is reserved for constraints or a
 * coach-session dependency so generic planning rationale does not slow down the
 * in-session scan.
 */
/** Casefold + whitespace/trailing-punctuation normalise for equality checks, so
 * "Mobility and low-noise speed." matches "mobility and low-noise speed". */
export function normalizeForDedupe(value: string | null | undefined): string | null {
  const clean = cleanText(value ?? null);
  if (!clean) {
    return null;
  }
  return clean.toLowerCase().replace(/\s+/g, " ").replace(/[.\s]+$/, "");
}

export function getSessionCoachingLines(
  anchor: Parameters<typeof getMindsetLines>[0],
): MindsetLine[] {
  if (!isObject(anchor)) {
    return [];
  }
  const focus = cleanText(anchor.focus_cue);
  const reset = cleanText(anchor.reset_cue);
  const intent = cleanText(anchor.intent);
  const confidence = cleanText(anchor.confidence_anchor);
  const context = cleanText(anchor.context);
  const coachCue = coachCueValue([intent, confidence]);
  const lines: MindsetLine[] = [];

  // One sentence, one line. A payload that puts the SAME cue in several slots —
  // the Fight Visualisation bank carries a single trusted cue, and older saved
  // cards replicated it across intent/focus/reset — printed it as "Focus",
  // "Reset" and "Coach cue" on one card. The first slot that carries it keeps
  // it; the repeats are dropped rather than restated.
  const seen = new Set<string>();
  const push = (label: string, value: string) => {
    const key = normalizeForDedupe(value);
    if (!key || seen.has(key)) {
      return;
    }
    seen.add(key);
    lines.push({ label, value });
  };

  if (focus) push("Focus", capitalizeFirst(focus));
  if (reset) push("Reset", capitalizeFirst(reset));
  if (coachCue) push("Coach cue", coachCue);
  if (context && isImportantSessionContext(context)) {
    push("Context", capitalizeFirst(context));
  }
  return lines;
}

export function splitMindsetLines(
  anchor: Parameters<typeof getMindsetLines>[0],
): { primary: MindsetLine[]; secondary: MindsetLine[] } {
  const lines = getMindsetLines(anchor);
  return {
    primary: lines,
    secondary: [],
  };
}

export function redFlagView(
  rule:
    | { display_text?: string | null; action?: string | null; severity?: string | null }
    | null
    | undefined,
): { text: string | null; action: string | null; severityLabel: string | null } {
  const text = cleanText(rule?.display_text);
  const rawAction = cleanText(rule?.action);
  const action =
    rawAction && !isRawEnumLabel(rawAction) && rawAction !== text ? rawAction : null;
  const severity = cleanText(rule?.severity);
  const severityLabel = severity ? formatPlanLabel(severity) : null;
  return { text, action, severityLabel };
}

// --- deterministic (Stage 1) athlete-safe nutrition + recovery --------------

const PHASE_ORDER = ["GPP", "SPP", "TAPER", "FIGHT_WEEK", "REINTEGRATION"];

/** Stable key used to attach deterministic support to matching week phases. */
export function normalizeSupportPhaseKey(value: unknown): string | null {
  const token = cleanText(value)
    ?.toLowerCase()
    .replace(/[\s\-/]+/g, "_")
    .replace(/_+/g, "_")
    .replace(/^_|_$/g, "");
  if (!token) {
    return null;
  }
  if (token === "gpp" || token.includes("general_prep") || token.includes("general_preparation")) {
    return "gpp";
  }
  if (token === "spp" || token.includes("specific_prep") || token.includes("specific_preparation")) {
    return "spp";
  }
  if (token === "taper") {
    return "taper";
  }
  if (token.includes("fight_week") || token.includes("fight_week_taper")) {
    return "fight_week";
  }
  if (token.includes("reintegration")) {
    return "reintegration";
  }
  return token;
}

function orderedPhaseEntries<T>(byPhase: Record<string, T> | null | undefined): {
  phase: string;
  entry: T;
}[] {
  if (!isObject(byPhase)) {
    return [];
  }
  const keys = Object.keys(byPhase);
  keys.sort((a, b) => {
    const ia = PHASE_ORDER.indexOf(a.toUpperCase());
    const ib = PHASE_ORDER.indexOf(b.toUpperCase());
    return (ia === -1 ? 99 : ia) - (ib === -1 ? 99 : ib);
  });
  return keys
    .filter((key) => isObject(byPhase[key]))
    .map((phase) => ({ phase, entry: byPhase[phase] }));
}

/** Ordered athlete-safe deterministic nutrition phases (empty when absent). */
export function getDeterministicNutritionPhases(
  plan: StructuredPlan | null | undefined,
): { phase: string; entry: DeterministicNutritionPhase }[] {
  return orderedPhaseEntries(plan?.deterministic_support?.nutrition?.by_phase);
}

/** Ordered athlete-safe deterministic recovery phases (empty when absent). */
export function getDeterministicRecoveryPhases(
  plan: StructuredPlan | null | undefined,
): { phase: string; entry: DeterministicRecoveryPhase }[] {
  return orderedPhaseEntries(plan?.deterministic_support?.recovery?.by_phase);
}

/** "112–140 g/day" / "up to 350 g/day" / "from 30 g/day" / null. */
export function formatMacroRange(
  range: DeterministicMacroRange | null | undefined,
  unit: string,
): string | null {
  if (!isObject(range)) {
    return null;
  }
  // Reject NaN/Infinity/negative so a malformed macro never prints "NaN g/day"
  // or a nonsensical negative intake. Zero is allowed (a legitimate "0 g" line).
  const finiteNonNegative = (n: unknown): n is number =>
    typeof n === "number" && Number.isFinite(n) && n >= 0;
  const min = finiteNonNegative(range.min) ? range.min : null;
  const max = finiteNonNegative(range.max) ? range.max : null;
  if (min != null && max != null) {
    return `${min}–${max} ${unit}`;
  }
  if (max != null) {
    return `up to ${max} ${unit}`;
  }
  if (min != null) {
    return `from ${min} ${unit}`;
  }
  return null;
}

/** A macro line combining its numeric range and any deterministic note. */
export function macroLine(
  range: DeterministicMacroRange | null | undefined,
  unit: string,
): string | null {
  const numeric = formatMacroRange(range, unit);
  const note = cleanText(range?.note);
  if (numeric && note) return `${numeric} (${note})`;
  return numeric || note || null;
}

/** Athlete-safe weight-cut summary (risk band + supervision) — never dosing. */
export function formatWeightCutBand(
  weightCut: DeterministicWeightCut | null | undefined,
): { band: string; supervisionRequired: boolean } | null {
  if (!isObject(weightCut)) {
    return null;
  }
  const band = cleanText(weightCut.risk_band);
  if (!band || band.toLowerCase() === "none") {
    return null;
  }
  return { band, supervisionRequired: weightCut.supervision_required === true };
}

const WEIGHT_CUT_RISK_RANK: Record<string, number> = {
  none: 0,
  inactive: 0,
  low: 1,
  mild: 1,
  moderate: 2,
  medium: 2,
  amber: 2,
  elevated: 2,
  high: 3,
  severe: 3,
  red: 3,
  critical: 4,
  extreme: 4,
  aggressive: 4,
};

/** The numeric rank of a risk-band token, or null when the token is missing or
 * unrecognised — so callers can tell "explicitly none/low" from "unknown / not
 * provided". Unknown risk is never treated as low. */
function recognizedWeightCutRiskRank(value: unknown): number | null {
  const token = cleanText(value)?.toLowerCase().replace(/[\s-]+/g, "_");
  if (!token) {
    return null;
  }
  if (WEIGHT_CUT_RISK_RANK[token] != null) {
    return WEIGHT_CUT_RISK_RANK[token];
  }
  const matches = Object.entries(WEIGHT_CUT_RISK_RANK)
    .filter(([key]) => token.includes(key))
    .map(([, rank]) => rank);
  return matches.length > 0 ? Math.max(...matches) : null;
}

/** All explicitly-present weight-cut risk-band tokens across the plan's warning
 * and deterministic phases. Empty when the plan states no risk band at all. */
function presentWeightCutRiskTokens(plan: StructuredPlan | null | undefined): string[] {
  const raw: (string | null)[] = [cleanText(plan?.nutrition?.weight_cut_warning?.risk_level)];
  for (const { entry } of getDeterministicNutritionPhases(plan)) {
    raw.push(cleanText(entry.weight_cut?.risk_band));
  }
  for (const { entry } of getDeterministicRecoveryPhases(plan)) {
    raw.push(cleanText(entry.weight_cut?.risk_band));
  }
  return raw.filter((token): token is string => token !== null);
}

/**
 * Whether the plan's weight-cut risk is EXPLICITLY known to be below moderate
 * (low / mild / none-inactive). Returns false when risk is missing, unknown /
 * unrecognised, or moderate-and-above — those must never be de-emphasised. A
 * single unrecognised or at-or-above-moderate band anywhere pins it to false.
 */
function isWeightCutRiskExplicitlyBelowModerate(plan: StructuredPlan | null | undefined): boolean {
  const tokens = presentWeightCutRiskTokens(plan);
  if (tokens.length === 0) {
    return false; // missing / not provided → never de-emphasise
  }
  const ranks = tokens.map(recognizedWeightCutRiskRank);
  if (ranks.some((rank) => rank === null)) {
    return false; // an unknown band is treated as unknown risk → full weight
  }
  const maxRank = Math.max(...(ranks as number[]));
  return maxRank < WEIGHT_CUT_RISK_RANK.moderate;
}

// Red-flag severities that must ALWAYS render at full weight — an explicit
// high/critical safety rule is never faded regardless of computed cut risk.
const PROMINENT_RED_FLAG_SEVERITIES = new Set(["red", "critical", "high", "severe", "extreme"]);

/** True when a red-flag rule's severity must never be visually de-emphasised. */
export function isProminentRedFlagSeverity(severity: string | null | undefined): boolean {
  const token = cleanText(severity)?.toLowerCase();
  return token != null && PROMINENT_RED_FLAG_SEVERITIES.has(token);
}

function isWeightCutSymptomEscalationText(text: string): boolean {
  const normalized = text.toLowerCase();
  return (
    /\bweight[-\s]?cut\b/.test(normalized) &&
    (
      /\bsymptoms?\s+worsen\b/.test(normalized) ||
      /\bworsen(?:s|ed|ing)?\b/.test(normalized) ||
      /\blightheaded(?:ness)?\b/.test(normalized) ||
      /\bdizz(?:y|iness)\b/.test(normalized) ||
      /\bdehydrat(?:ed|ion|e)?\b/.test(normalized)
    )
  );
}

/**
 * Whether a weight-cut symptom safety line should be visually DE-EMPHASISED —
 * shown, but softened — because the athlete's computed cut risk is EXPLICITLY
 * below moderate (low / mild / none). It is never suppressed: a symptom-based
 * stop/escalate rule ("if you feel dizzy/dehydrated, stop and report") is
 * generically safe advice, and a predicted risk band does not make actual
 * symptoms unimportant. De-emphasis is deliberately conservative — it applies
 * ONLY when:
 *   - the text is a weight-cut symptom escalation line, AND
 *   - the plan explicitly states a below-moderate risk band (never on missing,
 *     unknown, moderate, or higher risk), AND
 *   - the rule's own severity is not an explicit high/critical signal
 *     (``severity``, when supplied, overrides any de-emphasis).
 * Everything else renders at full weight, so a genuinely high-risk or unknown
 * situation is never faded.
 */
export function isDeEmphasisedWeightCutSafety(
  plan: StructuredPlan | null | undefined,
  text: string | null | undefined,
  severity?: string | null,
): boolean {
  const clean = cleanText(text);
  if (clean === null || !isWeightCutSymptomEscalationText(clean)) {
    return false;
  }
  if (isProminentRedFlagSeverity(severity)) {
    return false; // an explicit red/critical/high rule is never faded
  }
  return isWeightCutRiskExplicitlyBelowModerate(plan);
}

/** The athlete-safe metric rows for one deterministic nutrition phase. */
export function nutritionPhaseRows(
  entry: DeterministicNutritionPhase | null | undefined,
): { label: string; value: string }[] {
  if (!isObject(entry)) {
    return [];
  }
  const rows: { label: string; value: string }[] = [];
  const push = (label: string, value: string | null) => {
    if (value) rows.push({ label, value });
  };
  push("Protein", macroLine(entry.protein_g_per_day, "g/day"));
  push("Carbs", macroLine(entry.carbs_g_per_day, "g/day"));
  push("Fats", macroLine(entry.fats_g_per_day, "g/day"));
  push("Hydration", macroLine(entry.hydration_ml_per_day, "ml/day"));
  push("Meals", cleanText(entry.meal_structure));
  const fuel = entry.fuel_timing;
  if (isObject(fuel)) {
    push("Fuel (pre)", cleanText(fuel.pre));
    push("Fuel (intra)", cleanText(fuel.intra));
    push("Fuel (post)", cleanText(fuel.post));
  }
  const fatigue = cleanText(entry.fatigue_adjustment);
  if (fatigue) push("Fatigue adjustment", `${fatigue} fatigue support`);
  return rows;
}

/** The athlete-safe recovery view for one deterministic recovery phase. */
export function recoveryPhaseView(entry: DeterministicRecoveryPhase | null | undefined): {
  sleep: string | null;
  coreStrategies: string[];
  phaseFocus: string[];
  fatigue: string[];
  ageAdjustments: string[];
  weightCut: { band: string; supervisionRequired: boolean } | null;
} {
  const e = isObject(entry) ? entry : {};
  // Sleep hours must be finite and positive: typeof alone lets NaN through
  // (NaN is a "number"), which would render as "NaN–9 h/night".
  const sleepRange = safeArray(e.sleep_hours_target).filter(finitePositiveNumber);
  const sleep =
    sleepRange.length === 2
      ? `${sleepRange[0]}–${sleepRange[1]} h/night`
      : sleepRange.length === 1
        ? `${sleepRange[0]} h/night`
        : null;
  return {
    sleep,
    coreStrategies: getStringList(e.core_strategies),
    phaseFocus: getStringList(e.phase_focus),
    // fatigue_flags (high) or fatigue_notes (moderate) — whichever is present.
    fatigue: getStringList(e.fatigue_flags).concat(getStringList(e.fatigue_notes)),
    ageAdjustments: getStringList(e.age_adjustments),
    weightCut: formatWeightCutBand(e.weight_cut),
  };
}

/** True when the plan carries deterministic athlete-safe nutrition data. */
export function hasDeterministicNutrition(plan: StructuredPlan | null | undefined): boolean {
  return getDeterministicNutritionPhases(plan).some(
    ({ entry }) =>
      nutritionPhaseRows(entry).length > 0 || formatWeightCutBand(entry.weight_cut) !== null,
  );
}

/** True when the plan carries deterministic athlete-safe recovery data. */
export function hasDeterministicRecovery(plan: StructuredPlan | null | undefined): boolean {
  return getDeterministicRecoveryPhases(plan).some(({ entry }) => {
    const view = recoveryPhaseView(entry);
    return (
      view.sleep !== null ||
      view.coreStrategies.length > 0 ||
      view.phaseFocus.length > 0 ||
      view.fatigue.length > 0 ||
      view.ageAdjustments.length > 0 ||
      view.weightCut !== null
    );
  });
}

/** True when nutrition carries any displayable text. */
export function hasNutrition(plan: StructuredPlan | null | undefined): boolean {
  const nutrition = plan?.nutrition;
  if (!isObject(nutrition)) {
    return false;
  }
  return Boolean(
    cleanText(nutrition.summary) ||
      cleanText(nutrition.daily_focus) ||
      cleanText(nutrition.training_day_guidance) ||
      cleanText(nutrition.fight_week_guidance) ||
      cleanText(nutrition.weight_cut_warning?.display_text),
  );
}

export type PlanNoteView = { category: string; label: string | null; text: string };

const PLAN_NOTE_CATEGORY_LABELS: Record<string, string> = {
  weight_cut: "Weight cut",
  injury: "Injury",
  nutrition: "Nutrition",
  training: "Training",
  recovery: "Recovery",
  general: "Note",
};

/** Short title for a plan note: its own label, else a category fallback. */
export function planNoteLabel(note: PlanNoteView): string {
  if (note.label) {
    return note.label;
  }
  return PLAN_NOTE_CATEGORY_LABELS[note.category] ?? PLAN_NOTE_CATEGORY_LABELS.general;
}

/** Plan-level "active notes" that carry displayable text (empty when absent). */
export function getPlanNotes(plan: StructuredPlan | null | undefined): PlanNoteView[] {
  return safeArray(plan?.plan_notes)
    .filter(isObject)
    .map((note) => {
      const text = cleanText(note.text);
      if (!text) {
        return null;
      }
      const category = cleanText(note.category)?.toLowerCase().replace(/[-\s]+/g, "_") ?? "general";
      return { category, label: cleanText(note.label), text } satisfies PlanNoteView;
    })
    .filter((note): note is PlanNoteView => note !== null);
}

/** Fallback safety lines from active notes when explicit red-flag rules are
 * absent. A weight-cut symptom safety line is ALWAYS surfaced here (it is a
 * stop/escalate rule); the renderer de-emphasises it below moderate risk rather
 * than hiding it. */
export function getFallbackSafetyNotes(plan: StructuredPlan | null | undefined): PlanNoteView[] {
  const safetyAction =
    /(?:\bstop\s*:|\bstop\s+(?:training|the (?:exercise|session|set)|immediately|if|when|on)\b|\bseek (?:urgent )?medical (?:help|attention|review)\b|\breport (?:to|any|new|worsening)\b|\bdo not train\b|\bno training\b)/i;
  const symptomEscalation =
    /\b(?:dizz(?:y|iness)|faint(?:ing)?|lightheaded(?:ness)?|chest pain|shortness of breath|breathing (?:difficulty|worsens)|bleed(?:ing)?|wound (?:opens|worsens)|pain (?:increases|worsens|above|over)|dehydrat(?:ed|ion)|vomit(?:ing)?|confus(?:ed|ion))\b/i;
  const escalationVerb = /\b(?:stop|report|seek|urgent|worsen|escalat)\b/i;
  return getPlanNotes(plan).filter(
    (note) =>
      safetyAction.test(note.text) ||
      (symptomEscalation.test(note.text) && escalationVerb.test(note.text)),
  );
}

/** Red-flag rules that have something to display. Explicit symptom-based safety
 * rules (incl. weight-cut symptom escalation) are never suppressed by risk band
 * — they always render; the renderer softens the below-moderate ones. */
export function getDisplayableRedFlags(plan: StructuredPlan | null | undefined) {
  return safeArray(plan?.red_flag_rules)
    .filter(isObject)
    .filter((rule) => Boolean(cleanText(rule.display_text)));
}

/** Loose normalization for de-duplicating a note against a red-flag rule:
 *  lowercased, parentheticals dropped, all punctuation/whitespace collapsed to
 *  single spaces. Lets "…worsen, stop…" match "…worsen (lightheadedness), stop…". */
function normalizeForDup(text: string): string {
  return text
    .toLowerCase()
    .replace(/\([^)]*\)/g, " ")
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

/**
 * Active notes with any note that merely restates a red-flag rule removed, so
 * the Red Flags card stays the single home for stop/report rules. A note counts
 * as a duplicate only on EXACT normalized equality with a red flag's normalized
 * display_text. Substring ("contains / is contained by") matching is
 * deliberately NOT used here: these are safety notes, and a looser match risks
 * hiding a note that merely shares wording with a flag but adds its own
 * instruction. Over-suppressing safety copy is the more dangerous failure, so we
 * keep the stricter equality check. Notes shorter than the guard length are
 * always kept. The ``normalizeForDup`` helper still absorbs the common
 * parenthetical-only difference, which is the case this dedup targets.
 */
export function getActiveNotesExcludingRedFlags(
  plan: StructuredPlan | null | undefined,
): PlanNoteView[] {
  // No risk-gated hiding of weight-cut symptom notes here: a symptom-based
  // safety line is never suppressed by risk band (see isDeEmphasisedWeightCutSafety).
  // Duplication with the Red Flags card is prevented by the exact-match dedup
  // below, including when a genuine stop/escalation note supplies the fallback
  // Red Flags content because no explicit rule exists.
  const notes = getPlanNotes(plan);
  const explicitFlags = getDisplayableRedFlags(plan);
  const fallbackFlags = explicitFlags.length === 0 ? getFallbackSafetyNotes(plan) : [];
  const flagTexts = [
    ...explicitFlags.map((rule) => cleanText(rule.display_text)),
    ...fallbackFlags.map((note) => note.text),
  ]
    .filter((text): text is string => text !== null)
    .map(normalizeForDup)
    .filter((text) => text.length >= 12);
  if (flagTexts.length === 0) {
    return notes;
  }
  return notes.filter((note) => {
    const noteNorm = normalizeForDup(note.text);
    if (noteNorm.length < 12) {
      return true;
    }
    return !flagTexts.some((flag) => flag === noteNorm);
  });
}

// The week heading must read as a glanceable label, not a paragraph. The LLM is
// told to keep week_goal short, but plans (and older saved plans) can still
// carry a full multi-clause sentence, so we shorten deterministically: keep the
// first clause (up to the first ; or .) when that already fits in 4 words, else
// hard-cap at 4 words with an ellipsis. Goals already short are returned verbatim
// so their punctuation (e.g. a trailing period) is preserved.
const WEEK_GOAL_MAX_WORDS = 4;
function shortenWeekGoal(goal: string): string {
  const words = goal.split(/\s+/).filter(Boolean);
  if (words.length <= WEEK_GOAL_MAX_WORDS) {
    return goal;
  }
  const firstClause = goal.split(/[;.](?=\\s|$)/)[0].trim();
  const clauseWords = firstClause.split(/\s+/).filter(Boolean);
  if (clauseWords.length > 0 && clauseWords.length <= WEEK_GOAL_MAX_WORDS) {
    return firstClause;
  }
  return `${words.slice(0, WEEK_GOAL_MAX_WORDS).join(" ")}…`;
}

function lateFightCountdownStart(week: StructuredWeek | null | undefined): number | null {
  const labels = [
    formatCountdownLabel(week?.countdown_start),
    ...getDays(week).map((day) => formatCountdownLabel(day.countdown_label)),
  ];
  const distances = labels
    .map((label) => {
      const match = label?.match(/\bD-(\d+)\b/i);
      return match ? Number(match[1]) : null;
    })
    .filter((value): value is number => value !== null && Number.isFinite(value));
  return distances.length > 0 ? Math.max(...distances) : null;
}

/** Display-only fallback for countdown-led late-fight payloads saved before
 * week context repair existed. Explicit saved titles/phases always win. */
export function inferredLateFightWeekContext(
  week: StructuredWeek | null | undefined,
): { goal: string | null; phase: string | null } {
  const countdownStart = lateFightCountdownStart(week);
  if (countdownStart === null || countdownStart < 0 || countdownStart > 21) {
    return { goal: null, phase: null };
  }
  if (countdownStart >= 14) {
    return { goal: "Bridge Compression Week", phase: "TAPER" };
  }
  if (countdownStart >= 8) {
    return { goal: "Compressed Pre-Fight Week", phase: "TAPER" };
  }
  if (countdownStart === 7) {
    return { goal: "Sharpness Week", phase: "TAPER" };
  }
  if (countdownStart >= 5) {
    return { goal: "Sharpness & Freshness Window", phase: "TAPER" };
  }
  if (countdownStart >= 2) {
    return { goal: "Sharpness Sessions", phase: "TAPER" };
  }
  if (countdownStart === 1) {
    return { goal: "Primer Day", phase: "TAPER" };
  }
  return { goal: "Fight-Day Protocol", phase: "TAPER" };
}

export function resolvedWeekPhase(week: StructuredWeek | null | undefined): string | null {
  return cleanText(week?.phase_label) || inferredLateFightWeekContext(week).phase;
}

export function weekLabel(week: StructuredWeek | null | undefined): string {
  const goal = cleanText(week?.week_goal) || inferredLateFightWeekContext(week).goal;
  const index =
    typeof week?.week_index === "number" && Number.isFinite(week.week_index)
      ? week.week_index
      : null;
  const base = index != null ? `Week ${index}` : "Week";
  return goal ? `${base}: ${shortenWeekGoal(goal)}` : base;
}

// --- session-less day classification ----------------------------------------
//
// A coach-led / sparring / technical day legitimately carries no app S&C
// blocks (the contact load is owned by the coach), so the converter emits it as
// a day with an empty `sessions` array. Rather than relying on the LLM to build
// a session object for these — which wastes tokens and is a frequent source of
// dropped days — we deterministically derive a self-contained card from the
// day's own `today_card.headline` + `day_type`. Only a genuine rest/recovery
// day (or a truly empty day) falls through to "Rest day.".

const REST_DAY_TYPES = new Set(["rest", "recovery"]);
const REST_HEADLINE_RE = /\b(rest|recovery|off|no planned session)\b/i;
// `technical` is checked before `sparring` so a "technical only / no hard
// sparring" headline is not mislabelled as a sparring day by the stray
// "sparring" token, and `coach_led` is the catch-all for coach-owned contact.
const LIGHT_COMBAT_RE = /\b(light(?:[\s-]+technical)?[\s-]+combat|support[\s-]+work)\b/i;
const TECHNICAL_RE = /\b(technical|skill|drill|pad\s?work|pads|mitts?|footwork|shadow)/i;
const SPARRING_RE = /\bspar(?:r(?:ing|ed)|s)?\b/i;
const COACH_LED_RE = /\bcoach/i;

// Existing saved plans can still carry the old generic technical-contact title.
// Project that legacy title from the day's D-day at render time so the taper
// ladder applies immediately without requiring plan regeneration. Explicit
// countdown-specific titles from newer plans are preserved verbatim.
const GENERIC_TECHNICAL_CONTACT_TITLES = new Set([
  "technical-only combat",
  "technical combat",
]);

function technicalContactTitleForCountdown(headline: string, countdownLabel: unknown): string {
  if (!GENERIC_TECHNICAL_CONTACT_TITLES.has(headline.toLowerCase())) {
    return headline;
  }
  const countdown = formatCountdownLabel(countdownLabel);
  const match = countdown?.match(/^D-(\d+)$/i);
  const dDay = match ? Number(match[1]) : null;
  if (dDay == null || !Number.isFinite(dDay)) {
    return headline;
  }
  if (dDay >= 8 && dDay <= 17) {
    return "Controlled fight-speed technical rounds";
  }
  if (dDay >= 5 && dDay <= 7) {
    return "Technical rhythm only";
  }
  if (dDay >= 2 && dDay <= 4) {
    return "Technical touch — pads / shadow";
  }
  if (dDay >= 0 && dDay <= 1) {
    return "Technical activation — no contact";
  }
  return headline;
}

// Headlines the planner only ever stamps on a declared hard-sparring day it
// converted to technical work (D-17 inward): the canonical "technical only" /
// "no hard sparring" wording, its legacy spelling, and the countdown ladder above. A technical / light day the athlete
// declared keeps its own wording and must never read as a converted one.
const CONVERTED_TECHNICAL_LADDER_TITLES = new Set([
  "controlled fight-speed technical rounds",
  "technical rhythm only",
  "technical touch — pads / shadow",
  "technical activation — no contact",
]);
const CONVERTED_TECHNICAL_RE = /\btechnical[\s-]+only\b|\bno\s+hard\s+sparring\b/i;

/** Whether a technical contact headline marks a converted hard-sparring day. */
export function isConvertedTechnicalHeadline(headline: string): boolean {
  const normalized = headline.trim().toLowerCase();
  return (
    CONVERTED_TECHNICAL_RE.test(normalized) ||
    GENERIC_TECHNICAL_CONTACT_TITLES.has(normalized) ||
    CONVERTED_TECHNICAL_LADDER_TITLES.has(normalized)
  );
}

export type SessionlessDayKind =
  | "coach_led"
  | "light_combat"
  | "sparring"
  | "technical"
  | "scheduled"
  | "rest";

export type SessionlessDayView = {
  kind: SessionlessDayKind;
  title: string;
  /** Short tag for the day kind, or null when no kind tag should show. */
  tag: string | null;
  /** Whether to surface the "no app S&C — your own hard sparring/contact work" note. */
  coachLed: boolean;
  /** A technical day the planner converted from declared hard sparring. */
  converted: boolean;
};

const SESSIONLESS_DAY_TAGS: Record<SessionlessDayKind, string | null> = {
  coach_led: "Contact",
  light_combat: "Technical",
  sparring: "Sparring",
  technical: "Technical",
  scheduled: null,
  rest: null,
};

/** The day kind for a coach-led/contact headline (scheduled when none matches). */
function coachLedKindFromHeadline(headline: string): SessionlessDayKind {
  if (LIGHT_COMBAT_RE.test(headline)) {
    return "light_combat";
  }
  if (TECHNICAL_RE.test(headline)) {
    return "technical";
  }
  if (SPARRING_RE.test(headline)) {
    return "sparring";
  }
  if (COACH_LED_RE.test(headline)) {
    return "coach_led";
  }
  return "scheduled";
}

/**
 * Deterministically resolve how a day with no app sessions should render.
 *
 * Coach-led/sparring/technical days get their own card titled from the day
 * headline so a mostly-coach-led camp does not collapse into a wall of
 * "Rest day.". A headline-less rest/recovery day (or an otherwise empty day)
 * is the only case that renders as a rest day.
 */
export function classifySessionlessDay(
  day: StructuredDay | null | undefined,
): SessionlessDayView {
  const headline = cleanText(day?.today_card?.headline);
  const dayType = cleanText(day?.day_type)?.toLowerCase() ?? null;

  if (headline) {
    const headlineKind = coachLedKindFromHeadline(headline);
    // A declared light-combat day is never converted sparring, whatever wording
    // an older plan stamped on it (see getCoachLedContactView).
    const kind =
      headlineKind === "technical" && isDeclaredLightCombatOnlyDay(day) ? "light_combat" : headlineKind;
    // A rest/recovery day_type whose headline does not clearly identify
    // coach-led combat / sparring / technical work stays a rest day (e.g.
    // day_type "rest" + "Full rest and mobility"), rather than a generic
    // "scheduled" day. day_type is only allowed to override an unclassified
    // headline — a headline that names real combat/coach work always wins.
    if (kind === "scheduled" && dayType !== null && REST_DAY_TYPES.has(dayType)) {
      return {
        kind: "rest",
        title: REST_HEADLINE_RE.test(headline) ? headline : "No planned session",
        tag: null,
        coachLed: false,
        converted: false,
      };
    }
    return {
      kind,
      title:
        kind === "technical"
          ? technicalContactTitleForCountdown(headline, day?.countdown_label)
          : headline,
      tag: SESSIONLESS_DAY_TAGS[kind],
      coachLed:
        kind === "coach_led" ||
        kind === "sparring" ||
        kind === "technical",
      converted: kind === "technical" && isConvertedTechnicalHeadline(headline),
    };
  }

  // No headline to classify from: fall back to a plain rest day. The converter
  // is instructed to always headline a coach-led/sparring/technical day, so a
  // headline-less session-less day is treated as genuine rest.
  return { kind: "rest", title: "Rest day", tag: null, coachLed: false, converted: false };
}

function isDeclaredLightCombatOnlyDay(day: StructuredDay | null | undefined): boolean {
  const roles = Array.isArray(day?.planning_day_role_keys) ? day.planning_day_role_keys : [];
  return roles.includes("light_combat_day") && !roles.includes("hard_sparring_day");
}

export type CoachLedContactView = {
  kind: SessionlessDayKind;
  title: string;
  tag: string | null;
  /** A technical day the planner converted from declared hard sparring. */
  converted: boolean;
};

const REDUCED_DOSE_RE = /\breduced\s+dose\b/i;
// Mirrors _REDUCED_REASON_FALLBACK in api/structured_plan_sparring_reconcile.py,
// for plans saved before the server stamped today_card.contact_reason.
export const REDUCED_CONTACT_FALLBACK_REASON =
  "Reduced dose: It keeps this week's total sparring load manageable. Spar, but cut hard rounds and keep intensity controlled.";

/**
 * Why a declared hard-sparring day was deloaded, or null when it was not. The
 * server stamps a deterministic ``today_card.contact_reason`` from the
 * planner's reason codes; a reduced-dose card without one gets the fixed
 * fallback so it never renders unexplained. The reason is only trusted while
 * the day's contact still reads as reduced dose.
 */
export function getReducedContactReason(day: StructuredDay | null | undefined): string | null {
  const card = day?.today_card;
  const contactText = `${cleanText(card?.headline) ?? ""} ${cleanText(card?.coach_led_contact) ?? ""}`;
  // The day must still read as reduced: a stale reason on a day that is now
  // full hard or technical contact is never shown.
  if (!REDUCED_DOSE_RE.test(contactText)) {
    return null;
  }
  return cleanText(card?.contact_reason) ?? REDUCED_CONTACT_FALLBACK_REASON;
}

/**
 * Coach-owned contact (declared / downgraded sparring) that coexists with a
 * day's app sessions, or null when none is set. Driven by the deterministic
 * ``today_card.coach_led_contact`` field rather than the day headline (which a
 * session day uses for its own session title), so surfacing the contact never
 * clobbers the app session. The renderer shows it as a context block above the
 * session cards.
 */
export function getCoachLedContactView(
  day: StructuredDay | null | undefined,
): CoachLedContactView | null {
  const headline = cleanText(day?.today_card?.coach_led_contact);
  if (!headline) {
    return null;
  }
  // Plans saved before the reconcile fix stamped a declared light-combat day
  // with the converted-sparring wording ("Technical-only combat", or the taper
  // ladder). The day's role keys are deterministic: a light-combat day that
  // was never a hard-sparring day is the athlete's own technical session.
  if (isDeclaredLightCombatOnlyDay(day)) {
    return { kind: "light_combat", title: headline, tag: SESSIONLESS_DAY_TAGS.light_combat, converted: false };
  }
  const kind = coachLedKindFromHeadline(headline);
  const title =
    kind === "technical"
      ? technicalContactTitleForCountdown(headline, day?.countdown_label)
      : headline;
  return {
    kind,
    title,
    tag: SESSIONLESS_DAY_TAGS[kind],
    converted: kind === "technical" && isConvertedTechnicalHeadline(headline),
  };
}

web/lib/today.ts:
import type {
  InjuryFlagRecord,
  InjuryLoadRegion,
  StructuredBlock,
  TodayActiveInjury,
  TodayActivePlan,
  TodayCheckinBody,
  TodayCheckinPain,
  TodayCheckinPhase,
  TodayCheckinRequest,
  TodayCheckinSleep,
  TodayCommandView,
  TodayCompletionStatus,
  TodayPreviousSession,
  TodayRecommendationState,
  TodaySession,
} from "@/lib/types";
import { athleteFacingSessionTitle } from "@/lib/plan-labels";

type TodaySafetyFlags = {
  sharp_pain: boolean;
  instability: boolean;
  swelling: boolean;
  neurological_symptoms: boolean;
  illness_symptoms: boolean;
  cannot_warm_into_movement: boolean;
  worse_next_day_pain: boolean;
};

export const TODAY_EMPTY_TITLE = "No active plan yet";
export const TODAY_EMPTY_TEXT = "Complete intake to generate your training plan.";

export function hasActivePlan(plan: TodayActivePlan | null | undefined): boolean {
  return Boolean(plan?.id);
}

export function shouldShowTodayCheckin(state: TodayCommandView): boolean {
  return hasActivePlan(state.active_plan) && state.today.recommendation_state === "not_checked_in";
}

export function normalizeTodayPhase(phase: string | null | undefined): TodayCheckinPhase | null {
  if (phase === "GPP" || phase === "SPP" || phase === "TAPER" || phase === "REINTEGRATION") {
    return phase;
  }
  return null;
}

export function getRecommendationCopy(state: TodayRecommendationState): {
  label: string;
  icon: string;
  tone: TodayDecisionTone;
  actionText: string;
} {
  if (state === "train_as_planned") {
    return {
      label: "Train as planned",
      icon: "GO",
      tone: "green",
      actionText: "Start session and keep the work clean.",
    };
  }
  if (state === "modify") {
    return {
      label: "Adjust",
      icon: "ADJUST",
      tone: "amber",
      actionText: "Follow adjusted work and skip extras.",
    };
  }
  if (state === "pull_back") {
    return {
      label: "Pull back",
      icon: "PULL",
      tone: "red",
      actionText: "Skip hard combat work today. Use recovery or light mobility instead.",
    };
  }
  return {
    label: "Not checked in yet",
    icon: "CHK",
    tone: "neutral",
    actionText: "Submit the fast check-in to unlock today's recommendation.",
  };
}

export type TodayDecisionTone = "green" | "amber" | "red" | "neutral";

export type TodayDecisionDisplayState =
  | "go"
  | "adjust"
  | "stop"
  | "pull_back"
  | "rehab_only"
  | "no_training"
  | "injury_blocked"
  | "safety_notice"
  | "preview";

export type TodayDecisionBanner = {
  state: TodayRecommendationState;
  displayState: TodayDecisionDisplayState;
  chip: "GO" | "ADJUST" | "STOP" | "PULL BACK" | "REHAB ONLY" | "NO TRAINING" | "INJURY HOLD" | "SKIN CARE" | "CHECK" | "PREVIEW";
  /** Short coach-card headline, e.g. "Pull back today". */
  title: string;
  /** One clear reason sentence. Prefers the backend reason when present. */
  detail: string;
  /** One clear action sentence. */
  action?: string;
  /** Optional safety sentence, shown only when the backend sends one. */
  safety?: string;
  tone: TodayDecisionTone;
};

const DECISION_BANNERS: Record<
  Exclude<TodayRecommendationState, "not_checked_in">,
  { title: string; detail: string; action: string; tone: TodayDecisionTone }
> = {
  train_as_planned: {
    title: "Sharp work ready",
    detail: "Your check-in is clear for today's combat work.",
    action: "Start session and keep the work clean.",
    tone: "green",
  },
  modify: {
    title: "Session reduced",
    detail: "Hard combat work needs to be controlled today.",
    action: "Follow adjusted work and skip extras.",
    tone: "amber",
  },
  pull_back: {
    title: "Pull back today",
    detail: "Your body is not ready for hard combat work.",
    action: "Skip hard combat work today. Use recovery or light mobility instead.",
    tone: "red",
  },
};

const PREVIEW_BANNER = {
  title: "Session preview",
  detail: "This session is not open today.",
  action: "Completion opens on the matched training day.",
  tone: "neutral" as const,
};

function parseBackendAdjustment(reason: string | null | undefined): {
  title?: string;
  detail?: string;
  action?: string;
  safety?: string;
} {
  const lines = (reason ?? "")
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean);
  if (lines.length >= 3) {
    return {
      title: lines[0],
      detail: lines[1],
      action: lines[2],
      safety: lines[3],
    };
  }
  if (lines.length === 2) {
    return {
      title: lines[0],
      detail: lines[1],
    };
  }
  if (lines.length === 1) {
    return {
      detail: lines[0],
    };
  }
  return {};
}

function stripTitleStop(value: string | undefined): string | undefined {
  const text = value?.trim();
  if (!text) {
    return undefined;
  }
  return text.replace(/[.!?]+$/g, "").trim();
}

function normalizeTitleKey(value: string | undefined): string {
  return stripTitleStop(value)?.toLowerCase() ?? "";
}

/**
 * Guard against the title and the body repeating the same command. When the
 * first sentence of `detail` just restates the title — e.g. title "Pull back
 * today" with detail "Pull back today. Several warnings are showing…" — drop
 * that leading sentence so the card never shows the command twice. Pure display
 * cleanup: the meaning is unchanged, and nothing is removed when it would leave
 * the body empty. Applies to every recommendation state.
 */
function stripDuplicateLeadSentence(title: string, detail: string): string {
  const trimmed = detail.trim();
  if (!trimmed) {
    return trimmed;
  }
  const match = trimmed.match(/^([^.!?]*[.!?])\s+([\s\S]+)$/);
  if (!match) {
    return trimmed;
  }
  const [, firstSentence, rest] = match;
  const remainder = rest.trim();
  if (normalizeTitleKey(firstSentence) === normalizeTitleKey(title) && remainder) {
    return remainder;
  }
  return trimmed;
}

function normalizeBackendAdjustment(
  backend: ReturnType<typeof parseBackendAdjustment>,
): ReturnType<typeof parseBackendAdjustment> {
  const title = stripTitleStop(backend.title);
  const detail = backend.detail?.trim();
  const action = backend.action?.trim();
  const safety = backend.safety?.trim();

  if (
    normalizeTitleKey(backend.title) === "sharp work only" &&
    detail === "You are in taper, so sharpness matters more than extra work today." &&
    action === "Keep speed and timing work only; remove tiring rounds."
  ) {
    return {
      title: "Sharp taper work",
      detail: "Taper phase: sharpness over extra rounds.",
      action: "Keep speed and timing clean. Remove tiring rounds.",
      safety,
    };
  }

  return {
    title,
    detail,
    action,
    safety,
  };
}

function getSafetyDisplayState(
  state: TodayRecommendationState,
  backend: ReturnType<typeof parseBackendAdjustment>,
): TodayDecisionDisplayState | null {
  if (state !== "pull_back") {
    return null;
  }

  const titleKey = normalizeTitleKey(backend.title);
  const text = [backend.title, backend.detail, backend.action, backend.safety]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();

  if (
    titleKey === "no training today" ||
    text.includes("red flag") ||
    text.includes("seek medical advice")
  ) {
    return "no_training";
  }

  if (
    titleKey === "rehab only today" ||
    text.includes("injury is worse") ||
    text.includes("pain is high")
  ) {
    return "rehab_only";
  }

  return null;
}

function getDisplayState(
  state: TodayRecommendationState,
  backend: ReturnType<typeof parseBackendAdjustment>,
  isPreview: boolean,
): TodayDecisionDisplayState | null {
  const safetyState = getSafetyDisplayState(state, backend);
  if (safetyState) {
    return safetyState;
  }

  if (isPreview) {
    return "preview";
  }

  if (state === "train_as_planned") {
    return "go";
  }
  if (state === "modify") {
    return "adjust";
  }
  if (state === "pull_back") {
    return "pull_back";
  }
  return null;
}

function getDisplayTone(displayState: TodayDecisionDisplayState): TodayDecisionTone {
  if (displayState === "go") {
    return "green";
  }
  if (displayState === "adjust") {
    return "amber";
  }
  if (displayState === "preview") {
    return "neutral";
  }
  return "red";
}

function getDisplayChip(displayState: TodayDecisionDisplayState): TodayDecisionBanner["chip"] {
  if (displayState === "go") {
    return "GO";
  }
  if (displayState === "adjust") {
    return "ADJUST";
  }
  if (displayState === "stop") {
    return "STOP";
  }
  if (displayState === "pull_back") {
    return "PULL BACK";
  }
  if (displayState === "rehab_only") {
    return "REHAB ONLY";
  }
  if (displayState === "no_training") {
    return "NO TRAINING";
  }
  return "PREVIEW";
}

/**
 * The compact decision banner shown above today's session blocks once the
 * athlete has checked in. Returns null before check-in (no decision yet). The
 * banner title is fixed and command-like; the detail prefers the backend
 * readiness reason and falls back to the canned command copy. This does not
 * mutate the plan — it only frames the original blocks as train/modify/pull-back.
 */
export function getTodayDecisionBanner(
  state: TodayRecommendationState,
  reason?: string | null,
  options: { isPreview?: boolean } = {},
): TodayDecisionBanner | null {
  const backend = normalizeBackendAdjustment(parseBackendAdjustment(reason));
  const displayState = getDisplayState(state, backend, Boolean(options.isPreview));

  if (!displayState) {
    return null;
  }

  // Past the preview check, getDisplayState only returns a truthy display
  // state for a checked-in recommendation (not_checked_in yields "preview" or
  // null), so state is guaranteed to be a DECISION_BANNERS key here.
  const banner =
    displayState === "preview"
      ? PREVIEW_BANNER
      : DECISION_BANNERS[state as Exclude<TodayRecommendationState, "not_checked_in">];

  const title = backend.title || banner.title;
  const detail = stripDuplicateLeadSentence(title, backend.detail || banner.detail);

  return {
    state,
    displayState,
    chip: getDisplayChip(displayState),
    title,
    detail,
    action: backend.action || banner.action,
    safety: backend.safety,
    tone: getDisplayTone(displayState),
  };
}

/** Athlete-facing label for an open injury flag. Today's `open_injuries` carry a
 * clean server-computed `label` (built from the shared injury synonym logic);
 * fall back to a lightly capitalized body area only when it is absent. */
function injuryFlagLabel(injury: InjuryFlagRecord): string {
  const serverLabel = injury.label?.trim();
  if (serverLabel) {
    return serverLabel;
  }
  const raw = (injury.body_area?.trim() || injury.description?.trim() || "").replace(/\s+/g, " ");
  if (!raw) {
    return "a severe injury";
  }
  return raw.charAt(0).toUpperCase() + raw.slice(1);
}

/**
 * The highest-priority active injury that must hard-block training today: any
 * non-resolved injury the athlete flagged as SEVERE. The block is driven by
 * severity, not day-status — a severe injury is still severe while it is
 * "easing" (monitoring), so monitoring status must not unblock hard training
 * on the same day. Only resolving it — a deliberate, confirmed action — or
 * downgrading its severity removes the block.
 */
export function getActiveSevereInjury(
  openInjuries: readonly InjuryFlagRecord[] | null | undefined,
): InjuryFlagRecord | null {
  return (
    (openInjuries ?? []).find(
      (injury) =>
        injury.severity === "severe" &&
        (injury.status === "open" || injury.status === "monitoring"),
    ) ?? null
  );
}

/**
 * A severe active injury is the highest-priority constraint for today and
 * supersedes the daily check-in recommendation. When one is present this returns
 * a red, training-blocking banner that names the injury and the scheduled
 * session; otherwise null, so callers fall back to the daily decision banner.
 *
 * This is a display-priority override, not a plan mutation: the stored daily
 * recommendation stays in the command view / history, but the athlete sees the
 * injury stop lead instead of a stale "load reduced" adjustment. Safety never
 * gets weaker — a severe injury can only make today more restrictive.
 */
export function getInjuryOverrideBanner(
  state: TodayCommandView,
  sessionName?: string,
): TodayDecisionBanner | null {
  // A low-cost support / filler session (mental cue, breathing/mobility reset) is
  // exempt from the injury hold — it is the safe work the hold itself prescribes,
  // so a severe injury must not block it. The backend flags this on the command view.
  if (state.today?.injury_hold_exempt) {
    return null;
  }
  const injury = getActiveSevereInjury(state.open_injuries);
  if (!injury) {
    return null;
  }
  const label = injuryFlagLabel(injury);
  const name = (sessionName ?? "").trim();
  const sessionPhrase =
    name && name.toLowerCase() !== "today's session" ? name.toLowerCase() : "this session";
  const recommendationState = state.today?.recommendation_state ?? "not_checked_in";
  return {
    state: recommendationState,
    displayState: "injury_blocked",
    chip: "INJURY HOLD",
    title: "Session blocked",
    detail: `Active severe injury: ${label}. Do not complete ${sessionPhrase} until it is cleared.`,
    // Only call out the superseded guidance when a daily recommendation actually
    // exists to supersede (i.e. the athlete has checked in).
    safety:
      recommendationState !== "not_checked_in"
        ? "Previous readiness guidance is superseded by the injury warning."
        : undefined,
    tone: "red",
  };
}

export function getCompletionLabel(status: TodayCompletionStatus): string {
  if (status === "not_started") {
    return "Not started";
  }
  if (status === "started") {
    return "Started";
  }
  if (status === "done") {
    return "Session complete";
  }
  if (status === "modified") {
    return "Session modified";
  }
  return "Session skipped";
}

export function getCompletionActions(status: TodayCompletionStatus): string[] {
  if (status === "not_started") {
    return ["Start session", "Mark skipped"];
  }
  if (status === "started") {
    return ["Resume session", "Mark done", "Mark modified", "Mark skipped"];
  }
  if (status === "done") {
    return ["Session complete"];
  }
  if (status === "modified") {
    return ["Session modified"];
  }
  return ["Session skipped"];
}

const SESSION_VALUE_LABELS: Record<string, string> = {
  hard_as_planned: "Hard sparring",
  convert_to_technical_suggested: "Technical sparring",
  deload_suggested: "Reduced sparring",
  technical_skill: "Technical skill",
  no_hard_sparring_day: "No hard sparring",
  missing_effective_sparring_plan: "Plan detail unavailable",
  hard: "Hard session",
  technical: "Technical work",
  reduced: "Reduced work",
  none: "No training load",
};

export function formatSessionValue(value: string | null | undefined): string {
  const raw = value?.trim();
  if (!raw) {
    return "";
  }
  const normalized = raw.toLowerCase();
  if (SESSION_VALUE_LABELS[normalized]) {
    return SESSION_VALUE_LABELS[normalized];
  }
  return raw
    .replace(/[_-]+/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/\b\w/g, (match) => match.toUpperCase());
}

export function completionRequiresReviewFields(status: TodayCompletionStatus): boolean {
  return status === "done" || status === "modified";
}

export function completionRequiresModificationReason(status: TodayCompletionStatus): boolean {
  return status === "modified" || status === "skipped";
}

export function getCompletionReasonLabel(status: TodayCompletionStatus): string {
  return status === "skipped" ? "Reason for skipping" : "Modification reason";
}

export function getCompletionReasonError(status: TodayCompletionStatus): string {
  return status === "skipped"
    ? "Skipped sessions need a reason."
    : "Modified sessions need a reason.";
}

export function buildTodayCheckinPayload(params: {
  planId: string;
  phase?: string | null;
  sleep: TodayCheckinSleep;
  body: TodayCheckinBody;
  pain: TodayCheckinPain;
  activeInjury?: TodayActiveInjury;
  previousSession?: TodayPreviousSession;
  safetyFlags: TodaySafetyFlags;
}): TodayCheckinRequest {
  const phase = normalizeTodayPhase(params.phase);
  if (!phase) {
    throw new Error("Today phase is unavailable. Refresh Today before checking in.");
  }
  return {
    plan_id: params.planId,
    sleep: params.sleep,
    body: params.body,
    pain: params.pain,
    phase,
    // Carry the athlete-reported injury/session truth so the backend safety
    // evaluator can pull back for a worsening injury or modify after a very hard
    // prior session. Defaults stay conservative-neutral when not collected.
    active_injury: params.activeInjury ?? "none",
    previous_session: params.previousSession ?? "none",
    ...params.safetyFlags,
  };
}

export function getSessionTitle(session: TodaySession): string {
  return athleteFacingSessionTitle(
    session.title?.trim() ||
      session.label?.trim() ||
      formatSessionValue(session.status) ||
      formatSessionValue(session.effective_load) ||
      "Today's session",
  );
}

/**
 * Human-readable focus line for a session — never a raw backend enum. Prefers
 * the plain-language focus/emphasis fields and only falls back to the humanized
 * load value, then coach copy. Shared by Today and Overview so both agree.
 */
export function getSessionFocus(session: TodaySession): string {
  const focus =
    session.primary_focus?.trim() ||
    session.emphasis?.trim() ||
    formatSessionValue(session.effective_load) ||
    session.reason?.trim() ||
    // Falls back to the session objective ("Why:" line), which is authored
    // lower-case, so capitalise the first letter to match the other sources.
    session.coach_note?.trim() ||
    "Follow the current plan guidance.";
  return focus ? focus.charAt(0).toUpperCase() + focus.slice(1) : focus;
}

/**
 * Short supporting day line, e.g. "Thu · D-17". Keeps the weekday/countdown
 * visible as a sub-label so the session type can headline the card instead.
 */
export function getSessionDayLabel(session: TodaySession): string {
  const dayText = (session.weekday_with_label || session.weekday || "").trim();
  const countdown =
    typeof session.d_day === "number" ? `D-${Math.abs(session.d_day)}` : (session.day_label || "").trim();
  const hasCountdownInDayText = Boolean(dayText && countdown && dayText.includes(countdown));
  const parts = [dayText, hasCountdownInDayText ? "" : countdown].filter(Boolean);
  return parts.join(" · ");
}

export function hasTodaySession(session: TodaySession): boolean {
  return Boolean(session.session_id || session.weekday || session.status || session.title);
}

/**
 * The calendar day the structured-plan view (Today's blocks, Plan's "Today"
 * highlight) should center on. Normally the athlete-local `trainingDay`, but once
 * the backend command view has advanced past today's session — today logged as
 * done/modified/skipped, or a coach-led / rest day that carries no app card — the
 * `next_session` it returns carries `session_relation: "next"` plus the next
 * scheduled session's `calendar_date`. Centering the structured resolver on that
 * day keeps Today and Plan aligned with Overview's "Next session" instead of
 * sticking on the completed/empty current day (the original bug: the header
 * advanced to "Next scheduled session" while the card body kept the finished
 * day). Falls back to `trainingDay` whenever the next session has no usable
 * calendar date (e.g. weekday-only undated plans).
 */
export function resolveSessionFocusDate(
  trainingDay: Date | null,
  session: TodaySession | null | undefined,
): Date | null {
  if (session?.session_relation === "next") {
    const iso = (session.calendar_date || "").slice(0, 10);
    if (iso) {
      const focus = new Date(`${iso}T12:00:00`);
      if (!Number.isNaN(focus.getTime())) {
        return focus;
      }
    }
  }
  return trainingDay;
}

export function canCompleteTodaySession(session: TodaySession): boolean {
  if (!session.session_id) {
    return false;
  }
  // An off/rest day carries a session_id (keyed on the calendar date) but no
  // real load. Never let it be started/completed — that would persist a false
  // session state. Missing load is allowed (older payloads omit the field).
  return session.effective_load?.trim().toLowerCase() !== "none";
}

export function getVisibleRiskWatch(risks: TodayCommandView["risk_watch"]): {
  visible: TodayCommandView["risk_watch"];
  overflow: number;
} {
  const visible = risks.slice(0, 2);
  return { visible, overflow: Math.max(0, risks.length - visible.length) };
}

const RISK_TIMEFRAME_LABELS: Record<
  NonNullable<TodayCommandView["risk_watch"][number]["timeframe"]>,
  string
> = {
  today: "Today",
  last_session: "Last session",
  recent_sessions: "Recent sessions",
  active: "Active",
};

/** Athlete-facing timing label for a structured risk signal. */
export function getRiskTimeframeLabel(
  timeframe?: TodayCommandView["risk_watch"][number]["timeframe"],
): string {
  return timeframe ? RISK_TIMEFRAME_LABELS[timeframe] : "";
}

/**
 * Display copy for a risk-watch row. Keyed on the backend category so the row
 * never parrots the main recommendation word-for-word ("Recommendation: pull
 * back today.") — it names the consequence instead ("Hard combat work is
 * blocked today."). Falls back to the backend text for categories without an
 * override. Pure display transform — the stored risk data is untouched.
 */
const RISK_WATCH_TEXT_OVERRIDES: Record<string, string> = {
  stop_red_flag: "Hard combat work is blocked today.",
};

export function getRiskWatchText(risk: { category?: string | null; text?: string | null }): string {
  const key = (risk.category ?? "").trim();
  return RISK_WATCH_TEXT_OVERRIDES[key] || risk.text?.trim() || "Monitor this before training.";
}

// ---------------------------------------------------------------------------
// Decision hierarchy (STOP / PULL BACK / MODIFY / GREEN LIGHT)
//
// A single tier abstraction the Overview and Today screens both consume so the
// two can never disagree on the strongest decision. The tier is derived from the
// display-state the readiness engine + injury override already produce — no new
// backend signal. STOP is the hard-block tier (severe injury / red flag / rehab
// only) and always leads the page.
// ---------------------------------------------------------------------------

export type TodayDecisionTier =
  | "stop"
  | "pull_back"
  | "modify"
  | "green"
  | "preview"
  | "not_checked_in";

/** Map a resolved decision banner to its tier. Null banner (not checked in) is
 *  its own tier so the UI can prompt a check-in rather than imply a decision. */
export function getDecisionTier(banner: TodayDecisionBanner | null): TodayDecisionTier {
  if (!banner) {
    return "not_checked_in";
  }
  switch (banner.displayState) {
    case "stop":
    case "injury_blocked":
    case "no_training":
    case "rehab_only":
      return "stop";
    case "pull_back":
      return "pull_back";
    case "adjust":
      return "modify";
    case "go":
      return "green";
    case "preview":
      return "preview";
    default:
      return "not_checked_in";
  }
}

/**
 * The authoritative decision tier the whole Today UI should render from. Prefers
 * the backend-computed `today.decision_tier` (the single source of truth that
 * keeps the banner and the risk-watch footer in agreement) and only falls back to
 * the banner-derived tier for the preview framing (a client-only display concern)
 * or for older payloads that predate the field.
 */
export function resolveDecisionTier(
  today: Pick<TodayCommandView["today"], "decision_tier"> | null | undefined,
  banner: TodayDecisionBanner | null,
): TodayDecisionTier {
  const bannerTier = getDecisionTier(banner);
  // "preview" is a display framing for a future/next session, not a decision the
  // backend tier models — keep it.
  if (bannerTier === "preview") {
    return "preview";
  }
  const backendTier = today?.decision_tier;
  if (backendTier) {
    return backendTier;
  }
  return bannerTier;
}

export type TodayTierMeta = {
  /** Uppercase headline, e.g. "STOP TODAY". */
  label: string;
  /** Eyebrow above the headline. */
  eyebrow: string;
  tone: TodayDecisionTone;
};

const TIER_META: Record<TodayDecisionTier, TodayTierMeta> = {
  stop: { label: "Stop today", eyebrow: "Today's action", tone: "red" },
  pull_back: { label: "Pull back today", eyebrow: "Today's action", tone: "red" },
  modify: { label: "Modify today", eyebrow: "Today's action", tone: "amber" },
  green: { label: "Green light", eyebrow: "Today's action", tone: "green" },
  preview: { label: "Session preview", eyebrow: "Next session", tone: "neutral" },
  not_checked_in: { label: "Check in required", eyebrow: "Today's action", tone: "neutral" },
};

export function getTierMeta(tier: TodayDecisionTier): TodayTierMeta {
  return TIER_META[tier];
}

/** Reserve Today's command for a command that applies to the current day. */
export function getOverviewCommandEyebrow(tier: TodayDecisionTier): string {
  return tier === "preview" ? "Next up" : "Today's command";
}

export type OverviewPrimaryAction = { href: string; label: string };

/**
 * The single dominant CTA for the Overview command area, resolved from the
 * whole athlete state so the button can never contradict the rest of the card.
 * Priority: no active plan (build vs select) → severe-injury override → not yet
 * checked in → STOP → everything else. STOP never falls through to a "train"
 * label: with a safe replacement it routes to it, otherwise it points at the
 * stop guidance. Pure so it can be unit-tested across every state.
 */
export function getOverviewPrimaryAction(params: {
  hasActivePlan: boolean;
  planCount: number;
  hasInjuryOverride: boolean;
  recommendation: TodayRecommendationState;
  decisionTier: TodayDecisionTier;
  hasSafeSession: boolean;
  sessionIsToday: boolean;
}): OverviewPrimaryAction {
  const {
    hasActivePlan,
    planCount,
    hasInjuryOverride,
    recommendation,
    decisionTier,
    hasSafeSession,
    sessionIsToday,
  } = params;

  if (!hasActivePlan) {
    return planCount > 0
      ? { href: "/plans", label: "Select active plan" }
      : { href: "/onboarding", label: "Build your plan" };
  }
  if (hasInjuryOverride) {
    return { href: "/today#today-injury", label: "Open injury check-in" };
  }
  if (recommendation === "not_checked_in") {
    return { href: "/today#today-checkin", label: "Check in now" };
  }
  if (decisionTier === "stop") {
    return hasSafeSession
      ? { href: "/today#today-session", label: "View safe session" }
      : { href: "/today#today-session", label: "Review stop guidance" };
  }
  return {
    href: "/today#today-session",
    label: sessionIsToday ? "Today's session" : "Next session",
  };
}

/**
 * Whether the scheduled session is TODAY (vs a future planned day).
 *
 * `session_scope` is the answer, not an input to one. The backend
 * (today_service.build_today_command_view) is the single place session timing
 * is derived — it owns rest days, multi-session days, completed sessions and
 * the roll forward to the next training day — so this reads its result rather
 * than re-deriving the day from calendar dates. When surfaces did their own
 * date maths, Overview and Today could disagree about the same payload.
 */
export function isSessionToday(
  session: Pick<TodaySession, "session_relation"> | null | undefined,
  sessionScope?: TodayCommandView["today"]["session_scope"] | null,
): boolean {
  if (sessionScope) {
    return sessionScope === "today";
  }
  // Payloads that predate session_scope still carry the per-session relation.
  return session?.session_relation === "today";
}

/**
 * Whether a session is hard combat / high-risk work (sparring, hard pads, hard
 * rounds). There is no dedicated flag, so this reads the load + status enums the
 * plan already carries. Technical / reduced / rest sessions are NOT hard combat.
 */
export function isHardCombatSession(
  session: Pick<TodaySession, "effective_load" | "status"> | null | undefined,
): boolean {
  const load = (session?.effective_load ?? "").trim().toLowerCase();
  if (load === "hard") {
    return true;
  }
  const status = (session?.status ?? "").trim().toLowerCase();
  return status === "hard_as_planned" || status === "hard";
}

export type SafeSessionView = {
  eyebrow: string;
  title: string;
  detail: string;
  allowed: string[];
  blocked: string[];
};

// ── Safe-session activity gating ─────────────────────────────────────────────
// Anatomy and injury consequence are resolved by the backend's shared injury
// system. This module consumes structured fields only; it never carries a second
// body-part synonym list or re-parses athlete-entered injury text.

type InjuryRegion = Exclude<InjuryLoadRegion, "unknown">;

function isActiveInjury(injury: InjuryFlagRecord): boolean {
  return injury.status === "open" || injury.status === "monitoring";
}

function injuryIsLoadIntolerant(injury: InjuryFlagRecord): boolean {
  return (
    injury.severity === "severe" ||
    injury.consequence === "structural" ||
    injury.consequence === "neuro"
  );
}

function hasLoadIntolerantInjuryInRegion(
  openInjuries: readonly InjuryFlagRecord[] | null | undefined,
  region: InjuryRegion,
): boolean {
  return (openInjuries ?? []).some(
    (injury) =>
      isActiveInjury(injury) &&
      injury.load_region === region &&
      injuryIsLoadIntolerant(injury),
  );
}

function hasUnclassifiedActiveInjury(
  openInjuries: readonly InjuryFlagRecord[] | null | undefined,
): boolean {
  return (openInjuries ?? []).some((injury) => {
    const region = injury.load_region;
    return isActiveInjury(injury) && (!region || region === "unknown");
  });
}

/** Whether an active lower-limb injury cannot take gait or pedal load. */
export function hasLoadIntolerantLowerLegInjury(
  openInjuries: readonly InjuryFlagRecord[] | null | undefined,
): boolean {
  return hasLoadIntolerantInjuryInRegion(openInjuries, "lower_limb");
}

function hasNeuroDownregulationInjury(
  openInjuries: readonly InjuryFlagRecord[] | null | undefined,
): boolean {
  return (openInjuries ?? []).some(
    (injury) =>
      isActiveInjury(injury) &&
      injury.load_region === "head_neck" &&
      injuryIsLoadIntolerant(injury),
  );
}

type SafeSessionPosture = "rest_only" | "downregulate" | "standard";

function resolveSafeSessionPosture(
  openInjuries?: readonly InjuryFlagRecord[] | null,
): SafeSessionPosture {
  // A structural/severe injury whose anatomy could not be classified is never a
  // green light for generic movement. Fail closed rather than guessing a limb.
  if (
    hasUnclassifiedActiveInjury(openInjuries) ||
    hasLoadIntolerantInjuryInRegion(openInjuries, "trunk_spine")
  ) {
    return "rest_only";
  }
  if (hasNeuroDownregulationInjury(openInjuries)) {
    return "downregulate";
  }
  return "standard";
}

export function resolveSafeSessionAllowed(
  openInjuries?: readonly InjuryFlagRecord[] | null,
): string[] {
  const posture = resolveSafeSessionPosture(openInjuries);
  if (posture === "rest_only") {
    return ["Breathing reset", "Clinician-approved rehab"];
  }
  if (posture === "downregulate") {
    return ["Easy mobility", "Breathing reset", "Clinician-approved rehab"];
  }

  const lowerBlocked = hasLoadIntolerantLowerLegInjury(openInjuries);
  const upperBlocked = hasLoadIntolerantInjuryInRegion(openInjuries, "upper_limb");

  let conditioning: string | null;
  if (lowerBlocked && upperBlocked) {
    conditioning = null;
  } else if (lowerBlocked) {
    conditioning = "Seated upper-body cardio, only if pain-free and available";
  } else {
    conditioning = "Light bike or walk";
  }

  const allowed = ["Easy mobility"];
  if (conditioning) {
    allowed.push(conditioning);
  }
  allowed.push("Breathing reset", "Gentle activation", "Coach-approved rehab");
  return allowed;
}

export function resolveSafeSessionBlocked(
  openInjuries?: readonly InjuryFlagRecord[] | null,
): string[] {
  const lowerBlocked = hasLoadIntolerantLowerLegInjury(openInjuries);
  const upperBlocked = hasLoadIntolerantInjuryInRegion(openInjuries, "upper_limb");
  const trunkBlocked = hasLoadIntolerantInjuryInRegion(openInjuries, "trunk_spine");
  const neuro = hasNeuroDownregulationInjury(openInjuries);
  const unclassified = hasUnclassifiedActiveInjury(openInjuries);

  let explosive: string;
  if (unclassified || (upperBlocked && lowerBlocked)) {
    explosive = "Plyos or explosive work";
  } else if (upperBlocked) {
    explosive = "Plyos or explosive upper-body work";
  } else {
    explosive = "Plyos or explosive lower-body work";
  }

  const blocked = ["Sparring", "Hard pads", "HIIT", "Heavy lifting", explosive];
  if (upperBlocked) {
    blocked.push("Overhead or pressing work");
  }
  if (trunkBlocked) {
    blocked.push("Loaded rotation or bracing");
  }
  if (neuro) {
    blocked.push("Head impact or contact drills");
  }
  if (unclassified) {
    blocked.push("Loaded movement");
  }
  return blocked;
}

const SAFE_SESSION_POSTURE_DETAIL: Record<SafeSessionPosture, string> = {
  rest_only:
    "Protect the injured area and let it settle. No loaded movement today, and follow your clinician on what is safe.",
  downregulate:
    "Keep everything calm and symptom-free today. No exertion, and follow your clinician before adding work back.",
  standard: "Protect freshness, reduce risk, and keep the body moving without adding stress.",
};

/**
 * The recovery-only session shown in place of scheduled work when today is a STOP.
 * The backend classifies each active injury; this display only applies the supplied
 * broad region and consequence fields.
 */
export function getSafeSessionView(
  blockedSessionName?: string,
  openInjuries?: readonly InjuryFlagRecord[] | null,
): SafeSessionView {
  const name = (blockedSessionName ?? "").trim();
  const blockedLead =
    name && name.toLowerCase() !== "today's session"
      ? `${name} is blocked today.`
      : "Hard combat work is blocked today.";
  const posture = resolveSafeSessionPosture(openInjuries);
  return {
    eyebrow: "Today's safe session",
    title: posture === "rest_only" ? "Rest and recover" : "Recovery / mobility only",
    detail: `${blockedLead} ${SAFE_SESSION_POSTURE_DETAIL[posture]}`,
    allowed: resolveSafeSessionAllowed(openInjuries),
    blocked: resolveSafeSessionBlocked(openInjuries),
  };
}

/**
 * Today's countdown to the fight ("D-17"), computed from the training day and
 * fight date. Returns "" when either is missing/unparseable. Fight day is D-0.
 */
export function getCampDayLabel(
  trainingDay?: string | null,
  fightDate?: string | null,
): string {
  const toUtcNoon = (value?: string | null): number | null => {
    const iso = (value ?? "").trim().slice(0, 10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(iso)) {
      return null;
    }
    const ms = new Date(`${iso}T12:00:00Z`).getTime();
    return Number.isNaN(ms) ? null : ms;
  };
  const today = toUtcNoon(trainingDay);
  const fight = toUtcNoon(fightDate);
  if (today === null || fight === null) {
    return "";
  }
  const days = Math.round((fight - today) / 86_400_000);
  if (days < 0) {
    return "";
  }
  return `D-${days}`;
}

