const TIER_SIGNAL_LABEL: Record<TodayDecisionTier, string> = {
  stop: "STOP",
  pull_back: "PULL BACK",
  modify: "MODIFY",
  green: "GREEN",
  preview: "",
  not_checked_in: "",
